INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C1','math',4,1,'u4',2,'삼각형의 세 각 — 삼각형은 변 3개·꼭짓점 3개·각 3개로 이루어지고, 모양과 크기에 상관없이 세 각의 크기의 합은 180°라서 두 각을 알면 나머지 한 각을 구한다',ARRAY['4수02-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C2','math',4,1,'u4',2,'각의 크기에 따른 분류 — 세 각이 모두 예각이면 예각삼각형, 한 각이 직각이면 직각삼각형, 한 각이 둔각이면 둔각삼각형이다',ARRAY['4수02-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C3','math',4,1,'u4',2,'예각삼각형만 「모두」 — 어느 삼각형에나 예각이 적어도 2개 있고 직각·둔각은 많아야 하나뿐이므로, 예각이 있다고 예각삼각형이 되는 것은 아니다(가장 큰 각을 보고 정한다)',ARRAY['4수02-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C4','math',4,1,'u4',3,'이등변삼각형 — 두 변의 길이가 같은 삼각형이며, 놓인 방향이나 크기와 상관없고, 세 변의 길이의 합(둘레)으로 모르는 변의 길이를 구한다',ARRAY['4수02-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C5','math',4,1,'u4',3,'정삼각형 — 세 변의 길이가 같은 삼각형이며, 한 변의 길이 × 3 = 세 변의 길이의 합, 세 변의 길이의 합 ÷ 3 = 한 변의 길이이다',ARRAY['4수02-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C6','math',4,1,'u4',4,'이등변삼각형의 성질 — 반으로 접으면 포개지듯 길이가 같은 두 변에 있는 두 각의 크기가 같고(뜻은 변, 성질은 각), 이를 이용해 180°에서 모르는 각을 구한다',ARRAY['4수02-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C7','math',4,1,'u4',5,'정삼각형의 성질 — 세 변과 세 각의 크기가 모두 같고, 한 각은 180 ÷ 3 = 60°이며 삼각형이 크든 작든 언제나 60°이다',ARRAY['4수02-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C8','math',4,1,'u4',6,'두 잣대로 이름 붙이기 — 각의 크기와 변의 길이라는 서로 다른 잣대로 나누므로 한 삼각형에 이름이 여럿일 수 있고, 각으로는 반드시 하나, 변으로는 붙을 수도 안 붙을 수도 있다',ARRAY['4수02-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C9','math',4,1,'u4',6,'정삼각형과 이등변삼각형 — 정삼각형은 두 변의 길이도 같으므로 이등변삼각형이라고도 할 수 있지만, 이등변삼각형이 모두 정삼각형은 아니며 정삼각형은 언제나 예각삼각형이다',ARRAY['4수02-06']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u4-C10','math',4,1,'u4',7,'조건에 맞게 삼각형 만들기 — 색종이를 남김없이 잘라 조각이 모두 삼각형이고 예각·직각·둔각삼각형이 모두 있도록, 선을 먼저 그어 계획하고 조각의 수와 종류를 센다',ARRAY['4수02-06']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X01','math',4,'u4',ARRAY['M4-1-u4-C2','M4-1-u4-C3','M4-1-u4-C8']::text[],'예각이 하나라도 있으면 예각삼각형이라고 생각한다 — 직각삼각형·둔각삼각형의 예각을 보고 예각삼각형이라고 한다','세 각이 모두 예각인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X02','math',4,'u4',ARRAY['M4-1-u4-C1','M4-1-u4-C3','M4-1-u4-C9']::text[],'한 삼각형에 직각이나 둔각이 두 개 있을 수 있다고 생각한다','두 각만 더해도 180° 이상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X03','math',4,'u4',ARRAY['M4-1-u4-C1','M4-1-u4-C6','M4-1-u4-C7']::text[],'삼각형의 세 각의 크기의 합을 360°로 알거나, 나머지 한 각을 구할 때 아는 각을 빠짐없이 빼지 않는다','180°에서 아는 각을 모두 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X04','math',4,'u4',ARRAY['M4-1-u4-C2','M4-1-u4-C8']::text[],'직각삼각형의 직각(90°)을 예각이나 둔각으로 보아 예각삼각형·둔각삼각형이라고 한다','90°는 직각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X05','math',4,'u4',ARRAY['M4-1-u4-C4','M4-1-u4-C5']::text[],'삼각형이 놓인 방향이 바뀌면 이름도 바뀐다고 생각한다 — 뾰족한 곳이 위를 향해야 이등변삼각형이라고 한다','돌려 놓아도 변의 길이는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X06','math',4,'u4',ARRAY['M4-1-u4-C4','M4-1-u4-C6','M4-1-u4-C7']::text[],'뜻과 성질의 말을 섞는다 — 「두 각의 길이가 같다」·「세 변의 크기」처럼 길이와 크기를 바꾸어 쓰거나, 이등변삼각형의 뜻을 각으로 말한다','길이는 변에, 크기는 각에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X07','math',4,'u4',ARRAY['M4-1-u4-C5','M4-1-u4-C7']::text[],'정삼각형의 한 변과 세 변의 길이의 합 사이에서 나눌 것을 곱하거나 곱할 것을 나눈다(×2·÷2로 셈한다)','한 변 × 3 = 세 변의 합') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X08','math',4,'u4',ARRAY['M4-1-u4-C4']::text[],'이등변삼각형의 둘레에서 모르는 변을 구할 때 길이가 같은 변을 한 번만 빼거나, 같은 두 변이 어느 것인지 헷갈린다','같은 변은 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X09','math',4,'u4',ARRAY['M4-1-u4-C6']::text[],'이등변삼각형에서 크기가 같은 두 각을 잘못 고른다 — 꼭대기 각과 아래쪽 각이 같다고 하거나, 주어진 한 각이 둔각인데도 그 각과 같은 각이 하나 더 있다고 한다','길이가 같은 두 변에 있는 두 각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X10','math',4,'u4',ARRAY['M4-1-u4-C6']::text[],'꼭대기 각을 알 때 아래쪽 한 각을 구하면서 180°에서 뺀 값을 2로 나누지 않는다','남은 각을 똑같이 둘로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X11','math',4,'u4',ARRAY['M4-1-u4-C6','M4-1-u4-C7','M4-1-u4-C8']::text[],'두 각만 보고 판단한다 — 나머지 한 각을 구해 보지 않고 크기가 같은 두 각이 없다고(또는 있다고) 한다','나머지 한 각부터 구하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X12','math',4,'u4',ARRAY['M4-1-u4-C7']::text[],'정삼각형이 클수록(변이 길수록) 한 각도 크다고 생각한다','크든 작든 60°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X13','math',4,'u4',ARRAY['M4-1-u4-C7']::text[],'정삼각형의 한 각을 180 ÷ 2 = 90°, 360 ÷ 3 = 120°처럼 잘못 구한다','180°를 똑같이 셋으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X14','math',4,'u4',ARRAY['M4-1-u4-C8','M4-1-u4-C9']::text[],'한 삼각형에는 이름이 하나뿐이라고 생각해 각으로 붙인 이름과 변으로 붙인 이름 가운데 하나만 고른다','각으로 한 번, 변으로 한 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X15','math',4,'u4',ARRAY['M4-1-u4-C8']::text[],'각으로 붙이는 이름이 둘일 수 있다고 하거나(예각삼각형이면서 둔각삼각형), 변으로 붙일 이름이 없으면 각으로 붙인 이름도 빠뜨린다','각으로는 반드시 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X16','math',4,'u4',ARRAY['M4-1-u4-C9']::text[],'정삼각형은 이등변삼각형이 아니라고 생각한다 — 세 변이 같으면 「두 변이 같다」는 말에 맞지 않는다고 한다','세 변이 같으면 두 변도 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X17','math',4,'u4',ARRAY['M4-1-u4-C9']::text[],'이등변삼각형은 모두 정삼각형이라고 하거나, 정삼각형도 직각삼각형·둔각삼각형일 수 있다고 한다','정삼각형은 언제나 60°·60°·60°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X18','math',4,'u4',ARRAY['M4-1-u4-C10']::text[],'색종이 자르기 조건 가운데 하나를 빠뜨린다 — 가운데를 남기거나, 사각형 조각을 두거나, 한 종류의 삼각형만 만들고 조건을 다 지켰다고 한다','남김없이 · 모두 삼각형 · 세 종류') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X19','math',4,'u4',ARRAY['M4-1-u4-C1','M4-1-u4-C2','M4-1-u4-C3','M4-1-u4-C4','M4-1-u4-C5','M4-1-u4-C6','M4-1-u4-C7','M4-1-u4-C8','M4-1-u4-C9','M4-1-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 맞는↔아닌, 잘못된↔바른, 예각↔둔각','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X20','math',4,'u4',ARRAY['M4-1-u4-C10']::text[],'색종이를 대각선으로 자른 조각의 이름과 각을 잘못 안다 — 조각의 모서리 각을 90°로 보거나 조각 수를 잘못 센다','정사각형의 직각이 반으로 — 45°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u4-X21','math',4,'u4',ARRAY['M4-1-u4-C2','M4-1-u4-C4','M4-1-u4-C7']::text[],'삼각형의 크기나 생김새(뾰족함·납작함)만 보고 이름을 정하거나, 변의 길이를 재지 않고 크기만으로 정삼각형·이등변삼각형을 가른다','각은 재고, 변은 길이를 보고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#1','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C1',1,'sa','auto','삼각형에는 각이 몇 개 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형에는 각이 몇 개 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","모양·크기와 상관없어요.","답은 3개예요."],"variant_rule":{"alt":[{"stem":"삼각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["변과 변이 만나는 점이 꼭짓점이에요.","모양·크기와 상관없어요.","답은 3개예요."],"asset":null},{"stem":"어떤 삼각형이든 세 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["세 각을 오려 모으면 일직선이에요.","모양·크기와 상관없어요.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#2','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C1',1,'sa','auto','삼각형의 두 각이 50°, 60°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형의 두 각이 50°, 60°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 50 − 60 = 70.","나머지 한 각은 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,136.018364191],[186.0,136.018364191],[116.707365127,16.0]]],"arc":[[[116.707365127,16.0],[16.0,136.018364191],[186.0,136.018364191]],[[16.0,136.018364191],[186.0,136.018364191],[116.707365127,16.0]],[[186.0,136.018364191],[116.707365127,16.0],[16.0,136.018364191]]],"lab":[[[66.753236074,112.351741533],"50°"],[[147.894882233,114.018364191],"60°"],[[112.872512446,59.832566716],"?"]],"w":202,"h":152}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 70°, 45°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 70 − 45 = 65.","나머지 한 각은 65°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,140.636150943],[186.0,140.636150943],[61.363849057,16.0]]],"arc":[[[61.363849057,16.0],[16.0,140.636150943],[186.0,140.636150943]],[[16.0,140.636150943],[186.0,140.636150943],[61.363849057,16.0]],[[186.0,140.636150943],[61.363849057,16.0],[16.0,140.636150943]]],"lab":[[[52.042689949,115.398787744],"70°"],[[134.262746179,119.205878731],"45°"],[[70.88719207,58.957024313],"?"]],"w":202,"h":157}],"tag":false}},{"stem":"삼각형의 두 각이 35°, 85°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 35 − 85 = 60.","나머지 한 각은 60°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,128.164084793],[186.0,128.164084793],[176.186914126,16.0]]],"arc":[[[176.186914126,16.0],[16.0,128.16408