INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#7','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C3',2,'mc','auto','「예각이 있는 삼각형은 모두 예각삼각형이야.」 이 말이 틀린 까닭은 무엇인가요?',ARRAY['M4-1-u4-X21','M4-1-u4-X19','M4-1-u4-X03']::text[],true,'{"seq":7,"concept":"M4-1-u4-C3","difficulty":2,"kind":"mc","stem":"「예각이 있는 삼각형은 모두 예각삼각형이야.」 이 말이 틀린 까닭은 무엇인가요?","options":[{"t":"직각삼각형과 둔각삼각형에도 예각이 2개씩 있기 때문이에요","correct":true},{"t":"예각삼각형은 크기가 작은 삼각형이기 때문이에요","mis":"M4-1-u4-X21"},{"t":"예각삼각형에는 예각이 2개만 있기 때문이에요","mis":"M4-1-u4-X19"},{"t":"예각삼각형은 예각이 4개여야 하기 때문이에요","mis":"M4-1-u4-X03"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","직각삼각형은 직각 1개·예각 2개, 둔각삼각형은 둔각 1개·예각 2개예요.","그래서 예각삼각형은 「세 각이 모두」 예각이어야 해요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 「예각이 있는 삼각형은 모두 예각삼각형이야.」 이 말이 틀린 까닭은 무엇인가요?","options":[{"t":"직각삼각형과 둔각삼각형에도 예각이 2개씩 있기 때문이에요","correct":true},{"t":"예각이 있는 삼각형은 세상에 없기 때문이에요","mis":"M4-1-u4-X03"},{"t":"예각삼각형은 예각이 4개여야 하기 때문이에요","mis":"M4-1-u4-X03"},{"t":"예각삼각형은 크기가 작은 삼각형이기 때문이에요","mis":"M4-1-u4-X21"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","직각삼각형은 직각 1개·예각 2개, 둔각삼각형은 둔각 1개·예각 2개예요.","그래서 예각삼각형은 「세 각이 모두」 예각이어야 해요."],"asset":null},{"stem":"보기를 바꾸었어요. 「예각이 있는 삼각형은 모두 예각삼각형이야.」 이 말이 틀린 까닭은 무엇인가요?","options":[{"t":"직각삼각형과 둔각삼각형에도 예각이 2개씩 있기 때문이에요","correct":true},{"t":"예각삼각형은 크기가 작은 삼각형이기 때문이에요","mis":"M4-1-u4-X21"},{"t":"예각삼각형에는 예각이 2개만 있기 때문이에요","mis":"M4-1-u4-X19"},{"t":"예각삼각형은 예각이 4개여야 하기 때문이에요","mis":"M4-1-u4-X03"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","직각삼각형은 직각 1개·예각 2개, 둔각삼각형은 둔각 1개·예각 2개예요.","그래서 예각삼각형은 「세 각이 모두」 예각이어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#8','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C2',2,'mc','auto','삼각형의 두 각이 40°, 45°예요. 이 삼각형은 어떤 삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X01','M4-1-u4-X21']::text[],true,'{"seq":8,"concept":"M4-1-u4-C2","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 40°, 45°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 40 − 45 = 95.","세 각 40°, 45°, 95° — 가장 큰 각은 95°.","둔각삼각형이에요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 25°, 65°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"}],"explanation":["나머지 한 각부터 구해요: 180 − 25 − 65 = 90.","세 각 25°, 65°, 90° — 가장 큰 각은 90°.","직각삼각형이에요."],"asset":null},{"stem":"삼각형의 두 각이 55°, 60°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 55 − 60 = 65.","세 각 55°, 60°, 65° — 가장 큰 각은 65°.","예각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#9','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C3',2,'ox','auto','직각이 2개인 삼각형을 만들 수 있어요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X02']::text[],true,'{"seq":9,"concept":"M4-1-u4-C3","difficulty":2,"kind":"ox","stem":"직각이 2개인 삼각형을 만들 수 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"직각 2개만 더해도 180°가 되어 나머지 한 각이 0°라서","correct":true},{"t":"나머지 한 각을 아주 작게 하면 되어서","mis":"M4-1-u4-X02"}],"mis":"M4-1-u4-X02","explanation":["세 각의 합은 180°예요.","90 + 90 = 180 — 남는 각이 없어요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"둔각이 2개인 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"둔각 2개만 더해도 180°보다 커져서","correct":true},{"t":"각이 3개라 둘은 둔각일 수 있어서","mis":"M4-1-u4-X02"}],"explanation":["둔각은 90°보다 커요.","두 둔각의 합은 180°를 넘어요.","그래서 틀렸어요."],"asset":null},{"stem":"둔각삼각형에도 예각이 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"둔각 하나를 뺀 나머지 두 각의 합이 90°보다 작아 둘 다 예각이라서","correct":true},{"t":"둔각삼각형은 세 각이 모두 둔각이라서","mis":"M4-1-u4-X01"}],"explanation":["둔각 1개와 예각 2개예요.","어느 삼각형에나 예각이 적어도 2개.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_basic#10','math',4,1,'u4','L02','g4_1_math_u4_L02_basic','lesson_basic','M4-1-u4-C3',3,'error','auto','세 각이 ㉮ 70°, 60°, 50°, ㉯ 100°, 45°, 35°인 삼각형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C3","difficulty":3,"kind":"error","stem":"세 각이 ㉮ 70°, 60°, 50°, ㉯ 100°, 45°, 35°인 삼각형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「100°, 45°, 35°는 예각이 있으니 예각삼각형이에요.」","correct":true,"mis_target":"M4-1-u4-X01"},{"t":"준서 — 「㉮는 예각삼각형이에요」","mis":"M4-1-u4-X19"},{"t":"지호 — 「㉯는 둔각삼각형이에요」","mis":"M4-1-u4-X19"}],"explanation":["가장 큰 각으로 이름을 정해요.","㉮의 가장 큰 각 70° → 예각삼각형, ㉯의 가장 큰 각 100° → 둔각삼각형.","도윤은 예각만 보고 잘못 말했어요 — ㉯는 둔각삼각형이에요."],"variant_rule":{"alt":[{"stem":"세 각이 ㉮ 90°, 40°, 50°, ㉯ 120°, 30°, 30°인 삼각형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「120°, 30°, 30°는 예각이 있으니 예각삼각형이에요.」","correct":true,"mis_target":"M4-1-u4-X01"},{"t":"도윤 — 「㉮는 직각삼각형이에요」","mis":"M4-1-u4-X19"},{"t":"하람 — 「㉯는 둔각삼각형이에요」","mis":"M4-1-u4-X19"}],"explanation":["가장 큰 각으로 이름을 정해요.","㉮의 가장 큰 각 90° → 직각삼각형, ㉯의 가장 큰 각 120° → 둔각삼각형.","예린은 예각만 보고 잘못 말했어요 — ㉯는 둔각삼각형이에요."],"asset":null},{"stem":"세 각이 ㉮ 110°, 35°, 35°, ㉯ 90°, 55°, 35°인 삼각형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「90°, 55°, 35°는 예각이 있으니 예각삼각형이에요.」","correct":true,"mis_target":"M4-1-u4-X01"},{"t":"예린 — 「㉮는 둔각삼각형이에요」","mis":"M4-1-u4-X19"},{"t":"나래 — 「㉯는 직각삼각형이에요」","mis":"M4-1-u4-X19"}],"explanation":["가장 큰 각으로 이름을 정해요.","㉮의 가장 큰 각 110° → 둔각삼각형, ㉯의 가장 큰 각 90° → 직각삼각형.","은비는 예각만 보고 잘못 말했어요 — ㉯는 직각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#1','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C2',2,'match','auto','세 각과 삼각형의 이름을 알맞게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C2","difficulty":2,"kind":"match","stem":"세 각과 삼각형의 이름을 알맞게 이으세요.","pairs":[{"l":"70°, 60°, 50°","r":"예각삼각형"},{"l":"90°, 35°, 55°","r":"직각삼각형"},{"l":"110°, 40°, 30°","r":"둔각삼각형"}],"mis":"M4-1-u4-X01","explanation":["가장 큰 각을 찾아요.","70°, 60°, 50° → 예각삼각형, 90°, 35°, 55° → 직각삼각형, 110°, 40°, 30° → 둔각삼각형.","예각삼각형만 세 각이 모두 예각이에요."],"variant_rule":{"alt":[{"stem":"짝을 바꾸었어요. 세 각과 삼각형의 이름을 알맞게 이으세요.","pairs":[{"l":"25°, 65°, 90°","r":"직각삼각형"},{"l":"45°, 105°, 30°","r":"둔각삼각형"},{"l":"55°, 55°, 70°","r":"예각삼각형"}],"explanation":["가장 큰 각을 찾아요.","25°, 65°, 90° → 직각삼각형, 45°, 105°, 30° → 둔각삼각형, 55°, 55°, 70° → 예각삼각형.","예각삼각형만 세 각이 모두 예각이에요."],"asset":null},{"stem":"짝을 바꾸었어요. 세 각과 삼각형의 이름을 알맞게 이으세요.","pairs":[{"l":"20°, 130°, 30°","r":"둔각삼각형"},{"l":"80°, 50°, 50°","r":"예각삼각형"},{"l":"60°, 90°, 30°","r":"직각삼각형"}],"explanation":["가장 큰 각을 찾아요.","20°, 130°, 30° → 둔각삼각형, 80°, 50°, 50° → 예각삼각형, 60°, 90°, 30° → 직각삼각형.","예각삼각형만 세 각이 모두 예각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#2','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C1',2,'mc','auto','강을 건너는 다리를 삼각형 모양으로 짜는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M4-1-u4-X21','M4-1-u4-X03']::text[],true,'{"seq":2,"concept":"M4-1-u4-C1","difficulty":2,"kind":"mc","stem":"강을 건너는 다리를 삼각형 모양으로 짜는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"한쪽에 힘이 실려도 나머지 두 변이 힘을 나누어 모양이 잘 변하지 않기 때문이에요","correct":true},{"t":"삼각형이 사각형보다 모양이 예뻐서예요","mis":"M4-1-u4-X21"},{"t":"삼각형은 세 각의 합이 360°라서예요","mis":"M4-1-u4-X03"},{"t":"삼각형은 각이 4개라서 튼튼해서예요","mis":"M4-1-u4-X03"}],"explanation":["삼각형은 세 변의 길이가 정해지면 모양이 바뀌지 않아요.","그래서 힘을 받아도 잘 찌그러지지 않아요.","다리처럼 튼튼해야 하는 곳에 삼각형을 써요."],"variant_rule":{"alt":[{"stem":"집 지붕의 나무 틀을 삼각형 모양으로 짜는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"한쪽에 힘이 실려도 나머지 두 변이 힘을 나누어 모양이 잘 변하지 않기 때문이에요","correct":true},{"t":"삼각형이 사각형보다 모양이 예뻐서예요","mis":"M4-1-u4-X21"},{"t":"삼각형은 세 각의 합이 360°라서예요","mis":"M4-1-u4-X03"},{"t":"삼각형은 각이 4개라서 튼튼해서예요","mis":"M4-1-u4-X03"}],"explanation":["삼각형은 세 변의 길이가 정해지면 모양이 바뀌지 않아요.","그래서 힘을 받아도 잘 찌그러지지 않아요.","지붕처럼 튼튼해야 하는 곳에 삼각형을 써요."],"asset":null},{"stem":"놀이터 그네의 다리를 삼각형 모양으로 짜는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"한쪽에 힘이 실려도 나머지 두 변이 힘을 나누어 모양이 잘 변하지 않기 때문이에요","correct":true},{"t":"삼각형이 사각형보다 모양이 예뻐서예요","mis":"M4-1-u4-X21"},{"t":"삼각형은 세 각의 합이 360°라서예요","mis":"M4-1-u4-X03"},{"t":"삼각형은 각이 4개라서 튼튼해서예요","mis":"M4-1-u4-X03"}],"explanation":["삼각형은 세 변의 길이가 정해지면 모양이 바뀌지 않아요.","그래서 힘을 받아도 잘 찌그러지지 않아요.","그네처럼 튼튼해야 하는 곳에 삼각형을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#3','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C2',3,'mc','auto','어떤 삼각형에서 가장 큰 각이 85°예요. 이 삼각형은 어떤 삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X21']::text[],true,'{"seq":3,"concept":"M4-1-u4-C2","difficulty":3,"kind":"mc","stem":"어떤 삼각형에서 가장 큰 각이 85°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"나머지 두 각을 몰라서 알 수 없어요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["가장 큰 각이 85°이면 나머지 두 각은 그보다 작아요.","그래서 가장 큰 각만 보면 이름이 정해져요.","예각삼각형이에요."],"variant_rule":{"alt":[{"stem":"어떤 삼각형에서 가장 큰 각이 90°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"나머지 두 각을 몰라서 알 수 없어요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"}],"explanation":["가장 큰 각이 90°이면 나머지 두 각은 그보다 작아요.","그래서 가장 큰 각만 보면 이름이 정해져요.","직각삼각형이에요."],"asset":null},{"stem":"어떤 삼각형에서 가장 큰 각이 105°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"나머지 두 각을 몰라서 알 수 없어요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["가장 큰 각이 105°이면 나머지 두 각은 그보다 작아요.","그래서 가장 큰 각만 보면 이름이 정해져요.","둔각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#4','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C2',3,'sa','auto','세 각이 다음과 같은 삼각형들이 있어요. (50°, 60°, 70°) / (90°, 45°, 45°) / (100°, 40°, 40°) / (30°, 30°, 120°) / (80°, 60°, 40°) — 이 가운데 둔각삼각형은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C2","difficulty":3,"kind":"sa","stem":"세 각이 다음과 같은 삼각형들이 있어요. (50°, 60°, 70°) / (90°, 45°, 45°) / (100°, 40°, 40°) / (30°, 30°, 120°) / (80°, 60°, 40°) — 이 가운데 둔각삼각형은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["묶음마다 가장 큰 각을 찾아요.","예각 / 직각 / 둔각 / 둔각 / 예각.","둔각삼각형은 2개예요."],"variant_rule":{"alt":[{"stem":"세 각이 다음과 같은 삼각형들이 있어요. (20°, 70°, 90°) / (60°, 60°, 60°) / (95°, 45°, 40°) / (35°, 55°, 90°) / (25°, 75°, 80°) — 이 가운데 직각삼각형은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["묶음마다 가장 큰 각을 찾아요.","직각 / 예각 / 둔각 / 직각 / 예각.","직각삼각형은 2개예요."],"asset":null},{"stem":"세 각이 다음과 같은 삼각형들이 있어요. (45°, 65°, 70°) / (15°, 75°, 90°) / (110°, 50°, 20°) / (85°, 50°, 45°) / (55°, 55°, 70°) — 이 가운데 예각삼각형은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["묶음마다 가장 큰 각을 찾아요.","예각 / 직각 / 둔각 / 예각 / 예각.","예각삼각형은 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#5','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C3',3,'mc','auto','삼각형의 두 각이 모두 예각이에요. 이 삼각형은 어떤 삼각형일 수 있나요?',ARRAY['M4-1-u4-X01','M4-1-u4-X19','M4-1-u4-X03']::text[],true,'{"seq":5,"concept":"M4-1-u4-C3","difficulty":3,"kind":"mc","stem":"삼각형의 두 각이 모두 예각이에요. 이 삼각형은 어떤 삼각형일 수 있나요?","options":[{"t":"예각·직각·둔각삼각형 모두 될 수 있어요","correct":true},{"t":"예각삼각형뿐이에요","mis":"M4-1-u4-X01"},{"t":"둔각삼각형뿐이에요","mis":"M4-1-u4-X19"},{"t":"예각이 두 개라 삼각형이 될 수 없어요","mis":"M4-1-u4-X03"}],"explanation":["두 각이 예각이어도 나머지 한 각은 예각·직각·둔각 모두 될 수 있어요.","어느 삼각형에나 예각이 2개 있으니까요.","답은 「예각·직각·둔각삼각형 모두 될 수 있어요」."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 둔각이에요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형뿐이에요","correct":true},{"t":"예각·직각·둔각삼각형 모두 될 수 있어요","mis":"M4-1-u4-X02"},{"t":"예각이 두 개 있으니 예각삼각형이에요","mis":"M4-1-u4-X01"},{"t":"나머지 두 각을 알아야 정할 수 있어요","mis":"M4-1-u4-X11"}],"explanation":["둔각이 하나 있으면 나머지 두 각은 모두 예각이에요.","둔각이나 직각은 두 개 있을 수 없으니까요.","답은 「둔각삼각형뿐이에요」."],"asset":null},{"stem":"삼각형의 한 각이 직각이에요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"직각삼각형뿐이에요","correct":true},{"t":"나머지 한 각이 둔각이면 둔각삼각형이에요","mis":"M4-1-u4-X02"},{"t":"예각이 두 개 있으니 예각삼각형이에요","mis":"M4-1-u4-X01"},{"t":"예각·직각·둔각삼각형 모두 될 수 있어요","mis":"M4-1-u4-X02"}],"explanation":["직각이 하나 있으면 나머지 두 각의 합은 90° — 둘 다 예각이에요.","그래서 직각삼각형으로 정해져요.","답은 「직각삼각형뿐이에요」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#6','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C3',3,'ox','auto','직각 1개와 둔각 1개가 있는 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X02']::text[],true,'{"seq":6,"concept":"M4-1-u4-C3","difficulty":3,"kind":"ox","stem":"직각 1개와 둔각 1개가 있는 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"두 각의 합이 벌써 180°보다 커서","correct":true},{"t":"직각과 둔각은 서로 다른 각이라 함께 있을 수 있어서","mis":"M4-1-u4-X02"}],"mis":"M4-1-u4-X02","explanation":["90°에 둔각을 더하면 180°보다 커요.","그런 삼각형은 없어요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"직각삼각형의 직각이 아닌 두 각의 합은 90°예요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"세 각의 합 180°에서 90°를 빼면 90°라서","correct":true},{"t":"두 각의 합도 180°라서","mis":"M4-1-u4-X03"}],"explanation":["180 − 90 = 90.","두 예각을 더하면 90°예요.","그래서 맞아요."],"asset":null},{"stem":"둔각이 2개인 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"둔각 2개만 더해도 180°보다 커져서","correct":true},{"t":"각이 3개라 둘은 둔각일 수 있어서","mis":"M4-1-u4-X02"}],"explanation":["둔각은 90°보다 커요.","두 둔각의 합은 180°를 넘어요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#7','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C3',3,'error','auto','삼각형에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X19']::text[],true,'{"seq":7,"concept":"M4-1-u4-C3","difficulty":3,"kind":"error","stem":"삼각형에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「직각삼각형에는 예각이 하나뿐이에요.」","correct":true,"mis_target":"M4-1-u4-X01"},{"t":"준서 — 「둔각삼각형에는 예각이 2개 있어요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「예각삼각형은 세 각이 모두 예각이에요.」","mis":"M4-1-u4-X19"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","직각삼각형도 직각 1개·예각 2개예요.","도윤이 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 삼각형에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「삼각형에 둔각이 2개 있을 수도 있어요.」","correct":true,"mis_target":"M4-1-u4-X02"},{"t":"도윤 — 「직각과 둔각은 한 삼각형에 함께 있을 수 없어요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「가장 큰 각으로 이름을 정해요.」","mis":"M4-1-u4-X19"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","둔각 2개만 더해도 180°를 넘어요.","예린이 잘못 말했어요."],"asset":null},{"stem":"보기를 바꾸었어요. 삼각형에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「세 각이 90°, 45°, 45°이면 예각이 2개라 예각삼각형이에요.」","correct":true,"mis_target":"M4-1-u4-X04"},{"t":"예린 — 「세 각이 60°, 60°, 60°이면 예각삼각형이에요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「세 각이 100°, 50°, 30°이면 둔각삼각형이에요.」","mis":"M4-1-u4-X19"}],"explanation":["어느 삼각형에나 예각이 적어도 2개 있어요.","90°가 있으면 직각삼각형이에요.","은비가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#8','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C3',4,'essay','teacher','「예각이 2개 있는 삼각형은 예각삼각형이에요.」라는 말이 맞는지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C3","difficulty":4,"kind":"essay","stem":"「예각이 2개 있는 삼각형은 예각삼각형이에요.」라는 말이 맞는지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀리다. 어느 삼각형에나 예각이 적어도 2개 있다. 예를 들어 세 각이 90°, 50°, 40°인 직각삼각형에도 예각이 2개 있다. 예각삼각형은 세 각이 모두 예각이어야 한다.","scoring_points":["틀리다고 답했는가","직각삼각형·둔각삼각형에도 예각이 2개 있다고 했는가","예각삼각형은 세 각이 모두 예각이라고 했는가"]},"explanation":["어느 삼각형에나 예각은 2개 이상.","세 번째 각이 무엇인지가 중요해요.","예각삼각형은 「세 각 모두」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#9','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C2',4,'essay','teacher','삼각형의 두 각이 35°, 55°예요. 이 삼각형이 어떤 삼각형인지 풀이 과정과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C2","difficulty":4,"kind":"essay","stem":"삼각형의 두 각이 35°, 55°예요. 이 삼각형이 어떤 삼각형인지 풀이 과정과 함께 써 보세요.","answer_guide":{"answer":"예: 나머지 한 각은 180° − 35° − 55° = 90°이다. 한 각이 직각이므로 직각삼각형이다.","scoring_points":["180 − 35 − 55 = 90을 구했는가","한 각이 직각이라고 했는가","직각삼각형이라고 답했는가"]},"explanation":["나머지 한 각부터 구해요.","180 − 35 − 55 = 90.","직각삼각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L02_challenge#10','math',4,1,'u4','L02','g4_1_math_u4_L02_challenge','lesson_challenge','M4-1-u4-C1',4,'sa','auto','삼각형의 한 각이 60°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 2배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C1","difficulty":4,"kind":"sa","stem":"삼각형의 한 각이 60°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 2배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["나머지 두 각의 합: 180 − 60 = 120.","작은 각 = 120 ÷ 3 = 40, 큰 각 = 40 × 2 = 80.","세 각 60°, 40°, 80° — 가장 큰 각은 80°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 20°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 3배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["나머지 두 각의 합: 180 − 20 = 160.","작은 각 = 160 ÷ 4 = 40, 큰 각 = 40 × 3 = 120.","세 각 20°, 40°, 120° — 가장 큰 각은 120°예요."],"asset":null},{"stem":"삼각형의 한 각이 90°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 2배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["나머지 두 각의 합: 180 − 90 = 90.","작은 각 = 90 ÷ 3 = 30, 큰 각 = 30 × 2 = 60.","세 각 90°, 30°, 60° — 가장 큰 각은 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#1','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C4',1,'mc','auto','이등변삼각형은 어느 것인가요?',ARRAY['M4-1-u4-X05','M4-1-u4-X21']::text[],true,'{"seq":1,"concept":"M4-1-u4-C4","difficulty":1,"kind":"mc","stem":"이등변삼각형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-1-u4-X05"},{"t":"㉯","mis":"M4-1-u4-X21"},{"t":"㉰","mis":"M4-1-u4-X05"}],"explanation":["두 변의 길이가 같은지 봐요 — 놓인 방향은 상관없어요.","㉱는 두 변이 6 cm로 같아요.","이등변삼각형은 ㉱예요."],"asset":{"type":"geo","items":[{"poly":[[[38.636617591,83.383304295],[128.250252539,116.0],[84.908950639,16.0]]],"lab":[[[76.549553047,118.632437325],"7 cm"],[[134.578475591,53.86492349],"8 cm"],[[38.0,33.366804389],"6 cm"]],"w":173,"h":143},{"poly":[[[73.803232665,104.184645253],[165.733393255,70.724803167],[65.733393255,20.71954031]]],"lab":[[[126.662194979,106.395509388],"7 cm"],[[125.595517074,26.0],"8 cm"],[[38.0,65.52361811],"6 cm"]],"w":182,"h":130},{"poly":[[[16.0,59.558797708],[94.555973061,88.150833626],[116.0,29.23385383]]],"right":[[[16.0,59.558797708],[94.555973061,88.150833626],[116.0,29.23385383]]],"lab":[[[48.384104512,92.795600845],"4 cm"],[[134.32808321,69.265714222],"3 cm"],[[60.421324535,26.0],"5 cm"]],"w":172,"h":117},{"poly":[[[52.557738586,80.831651223],[113.471105486,116.0],[79.836082055,16.0]]],"lab":[[[71.514422036,118.334409899],"6 cm"],[[126.093697722,56.097814138],"9 cm"],[[38.0,36.551790222],"6 cm"]],"w":164,"h":142}]},"variant_rule":{"alt":[{"stem":"그림을 바꾸었어요. 이등변삼각형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u4-X05"},{"t":"㉰","mis":"M4-1-u4-X05"},{"t":"㉱","mis":"M4-1-u4-X21"}],"explanation":["두 변의 길이가 같은지 봐요 — 놓인 방향은 상관없어요.","㉯는 두 변이 8 cm로 같아요.","이등변삼각형은 ㉯예요."],"asset":{"type":"geo","items":[{"poly":[[[56.097065189,98.394530379],[104.467695431,116.