INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#3','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C5',1,'sa','auto','세 변의 길이의 합이 9 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C5","difficulty":1,"kind":"sa","stem":"세 변의 길이의 합이 9 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","9 ÷ 3 = 3.","한 변은 3 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 12 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","12 ÷ 3 = 4.","한 변은 4 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 15 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","15 ÷ 3 = 5.","한 변은 5 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#4','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C4',1,'mc','auto','이등변삼각형을 바르게 설명한 것은 무엇인가요?',ARRAY['M4-1-u4-X19','M4-1-u4-X05','M4-1-u4-X06']::text[],true,'{"seq":4,"concept":"M4-1-u4-C4","difficulty":1,"kind":"mc","stem":"이등변삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"두 변의 길이가 같은 삼각형","correct":true},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X19"},{"t":"뾰족한 꼭짓점이 위를 향한 삼각형","mis":"M4-1-u4-X05"},{"t":"세 각의 크기가 모두 같은 삼각형","mis":"M4-1-u4-X06"}],"explanation":["변의 길이로 붙인 이름이에요.","이등변삼각형 — 두 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 이등변삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"두 변의 길이가 같은 삼각형","correct":true},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X19"},{"t":"두 각의 길이가 같은 삼각형","mis":"M4-1-u4-X06"},{"t":"뾰족한 꼭짓점이 위를 향한 삼각형","mis":"M4-1-u4-X05"}],"explanation":["변의 길이로 붙인 이름이에요.","이등변삼각형 — 두 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"asset":null},{"stem":"보기를 바꾸었어요. 이등변삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"두 변의 길이가 같은 삼각형","correct":true},{"t":"마주 보는 두 쌍의 변의 길이가 같은 삼각형","mis":"M4-1-u4-X06"},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X19"},{"t":"뾰족한 꼭짓점이 위를 향한 삼각형","mis":"M4-1-u4-X05"}],"explanation":["변의 길이로 붙인 이름이에요.","이등변삼각형 — 두 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
