INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#7','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C5',2,'sa','auto','한 변이 6 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u4-C5","difficulty":2,"kind":"sa","stem":"한 변이 6 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["세 변이 모두 6 cm예요.","6 × 3 = 18.","세 변의 길이의 합은 18 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"6 cm"]],"w":202,"h":201}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["세 변이 모두 8 cm예요.","8 × 3 = 24.","세 변의 길이의 합은 24 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"8 cm"]],"w":202,"h":201}],"tag":false}},{"stem":"한 변이 11 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["세 변이 모두 11 cm예요.","11 × 3 = 33.","세 변의 길이의 합은 33 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"11 cm"]],"w":202,"h":201}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misc