INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#8','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C4',2,'mc','auto','길이가 5 cm, 5 cm, 3 cm인 막대 세 개로 삼각형을 만들었어요. 어떤 삼각형인가요?',ARRAY['M4-1-u4-X16','M4-1-u4-X21','M4-1-u4-X19']::text[],true,'{"seq":8,"concept":"M4-1-u4-C4","difficulty":2,"kind":"mc","stem":"길이가 5 cm, 5 cm, 3 cm인 막대 세 개로 삼각형을 만들었어요. 어떤 삼각형인가요?","options":[{"t":"이등변삼각형","correct":true},{"t":"정삼각형","mis":"M4-1-u4-X16"},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X21"},{"t":"막대로는 삼각형을 만들 수 없어요","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 막대가 몇 개인지 세어요.","같은 길이 두 개.","이등변삼각형이에요."],"variant_rule":{"alt":[{"stem":"길이가 4 cm, 7 cm, 7 cm인 막대 세 개로 삼각형을 만들었어요. 어떤 삼각형인가요?","options":[{"t":"이등변삼각형","correct":true},{"t":"정삼각형","mis":"M4-1-u4-X16"},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X21"},{"t":"막대로는 삼각형을 만들 수 없어요","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 막대가 몇 개인지 세어요.","같은 길이 두 개.","이등변삼각형이에요."],"asset":null},{"stem":"길이가 6 cm, 9 cm, 6 cm인 막대 세 개로 삼각형을 만들었어요. 어떤 삼각형인가요?","options":[{"t":"이등변삼각형","correct":true},{"t":"정삼각형","mis":"M4-1-u4-X16"},{"t":"세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X21"},{"t":"막대로는 삼각형을 만들 수 없어요","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 막대가 몇 개인지 세어요.","같은 길이 두 개.","이등변삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#9','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C4',2,'ox','auto','뾰족한 꼭짓점이 아래를 향하도록 놓인 삼각형은 이등변삼각형이 될 수 없어요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X05']::text[],true,'{"seq":9,"concept":"M4-1-u4-C4","difficulty":2,"kind":"ox","stem":"뾰족한 꼭짓점이 아래를 향하도록 놓인 삼각형은 이등변삼각형이 될 수 없어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"돌려 놓아도 두 변의 길이는 그대로라서","correct":true},{"t":"이등변삼각형은 꼭짓점이 위를 향해야 해서","mis":"M4-1-u4-X05"}],"mis":"M4-1-u4-X05","explanation":["이름은 변의 길이로 정해요.","놓인 방향은 상관없어요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"큰 삼각형은 정삼각형, 작은 삼각형은 이등변삼각형이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"이름은 크기가 아니라 변의 길이로 정해서","correct":true},{"t":"크기가 다르면 이름도 달라서","mis":"M4-1-u4-X21"}],"explanation":["정삼각형은 세 변, 이등변삼각형은 두 변이 같아요.","크기와는 상관없어요.","그래서 틀렸어요."],"asset":null},{"stem":"이등변삼각형을 옆으로 눕혀 놓아도 이등변삼각형이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"눕혀도 두 변의 길이는 그대로라서","correct":true},{"t":"눕히면 변의 길이가 바뀌어서","mis":"M4-1-u4-X05"}],"explanation":["돌려 놓으면 방향만 바뀌어요.","변의 길이는 그대로예요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_basic#10','math',4,1,'u4','L03','g4_1_math_u4_L03_basic','lesson_basic','M4-1-u4-C4',3,'error','auto','세 변의 길이의 합이 20 cm인 이등변삼각형에서 길이가 같은 두 변이 각각 7 cm예요. 나머지 한 변을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X08','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C4","difficulty":3,"kind":"error","stem":"세 변의 길이의 합이 20 cm인 이등변삼각형에서 길이가 같은 두 변이 각각 7 cm예요. 나머지 한 변을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「20 − 7 = 13, 나머지 한 변은 13 cm예요.」","correct":true,"mis_target":"M4-1-u4-X08"},{"t":"준서 — 「20 − 7 − 7 = 6, 나머지 한 변은 6 cm예요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「같은 변이 두 개라 7 cm를 두 번 빼요.」","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 변이 두 개예요.","20 − 7 − 7 = 6.","도윤은 같은 변을 한 번만 뺐어요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 25 cm인 이등변삼각형에서 길이가 같은 두 변이 각각 9 cm예요. 나머지 한 변을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「25 − 9 = 16, 나머지 한 변은 16 cm예요.」","correct":true,"mis_target":"M4-1-u4-X08"},{"t":"도윤 — 「25 − 9 − 9 = 7, 나머지 한 변은 7 cm예요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「같은 변이 두 개라 9 cm를 두 번 빼요.」","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 변이 두 개예요.","25 − 9 − 9 = 7.","예린은 같은 변을 한 번만 뺐어요."],"asset":null},{"stem":"세 변의 길이의 합이 19 cm인 이등변삼각형에서 길이가 같은 두 변이 각각 6 cm예요. 나머지 한 변을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「19 − 6 = 13, 나머지 한 변은 13 cm예요.」","correct":true,"mis_target":"M4-1-u4-X08"},{"t":"예린 — 「19 − 6 − 6 = 7, 나머지 한 변은 7 cm예요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「같은 변이 두 개라 6 cm를 두 번 빼요.」","mis":"M4-1-u4-X19"}],"explanation":["길이가 같은 변이 두 개예요.","19 − 6 − 6 = 7.","은비는 같은 변을 한 번만 뺐어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#1','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',2,'mc','auto','정삼각형을 바르게 설명한 것은 무엇인가요?',ARRAY['M4-1-u4-X06','M4-1-u4-X19','M4-1-u4-X21']::text[],true,'{"seq":1,"concept":"M4-1-u4-C5","difficulty":2,"kind":"mc","stem":"정삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"세 변의 길이가 같은 삼각형","correct":true},{"t":"세 변의 크기가 모두 다른 삼각형","mis":"M4-1-u4-X06"},{"t":"두 변의 길이만 같은 삼각형","mis":"M4-1-u4-X19"},{"t":"크기가 작은 삼각형","mis":"M4-1-u4-X21"}],"explanation":["변의 길이로 붙인 이름이에요.","정삼각형 — 세 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 정삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"세 변의 길이가 같은 삼각형","correct":true},{"t":"두 변의 길이만 같은 삼각형","mis":"M4-1-u4-X19"},{"t":"세 각의 길이가 같은 삼각형","mis":"M4-1-u4-X06"},{"t":"크기가 작은 삼각형","mis":"M4-1-u4-X21"}],"explanation":["변의 길이로 붙인 이름이에요.","정삼각형 — 세 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"asset":null},{"stem":"보기를 바꾸었어요. 정삼각형을 바르게 설명한 것은 무엇인가요?","options":[{"t":"세 변의 길이가 같은 삼각형","correct":true},{"t":"크기가 작은 삼각형","mis":"M4-1-u4-X21"},{"t":"세 변의 크기가 모두 다른 삼각형","mis":"M4-1-u4-X06"},{"t":"세 각의 길이가 같은 삼각형","mis":"M4-1-u4-X06"}],"explanation":["변의 길이로 붙인 이름이에요.","정삼각형 — 세 변의 길이가 같은 삼각형.","길이는 변에 쓰는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#2','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C4',2,'sa','auto','세 변의 길이의 합이 22 cm인 이등변삼각형이에요. 나머지 한 변이 8 cm일 때, 길이가 같은 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u4-C4","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 22 cm인 이등변삼각형이에요. 나머지 한 변이 8 cm일 때, 길이가 같은 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["같은 두 변의 길이의 합: 22 − 8 = 14.","14 ÷ 2 = 7.","길이가 같은 한 변은 7 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 19 cm인 이등변삼각형이에요. 나머지 한 변이 5 cm일 때, 길이가 같은 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["같은 두 변의 길이의 합: 19 − 5 = 14.","14 ÷ 2 = 7.","길이가 같은 한 변은 7 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 26 cm인 이등변삼각형이에요. 나머지 한 변이 10 cm일 때, 길이가 같은 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["같은 두 변의 길이의 합: 26 − 10 = 16.","16 ÷ 2 = 8.","길이가 같은 한 변은 8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#3','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C4',3,'sa','auto','이등변삼각형의 두 변의 길이가 4 cm, 9 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C4","difficulty":3,"kind":"sa","stem":"이등변삼각형의 두 변의 길이가 4 cm, 9 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["같은 두 변이 4 cm이면 4 cm, 4 cm, 9 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 9 cm — 9 cm, 9 cm, 4 cm.","9 + 9 + 4 = 22 — 22 cm예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 두 변의 길이가 3 cm, 8 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 8 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 8 cm — 8 cm, 8 cm, 3 cm.","8 + 8 + 3 = 19 — 19 cm예요."],"asset":null},{"stem":"이등변삼각형의 두 변의 길이가 5 cm, 11 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["같은 두 변이 5 cm이면 5 cm, 5 cm, 11 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 11 cm — 11 cm, 11 cm, 5 cm.","11 + 11 + 5 = 27 — 27 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#4','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',3,'sa','auto','한 변이 8 cm인 정삼각형과 세 변의 길이의 합이 같은 이등변삼각형이 있어요. 이등변삼각형의 길이가 같은 두 변이 각각 9 cm라면 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C5","difficulty":3,"kind":"sa","stem":"한 변이 8 cm인 정삼각형과 세 변의 길이의 합이 같은 이등변삼각형이 있어요. 이등변삼각형의 길이가 같은 두 변이 각각 9 cm라면 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 세 변의 길이의 합: 8 × 3 = 24.","24 − 9 − 9 = 6.","나머지 한 변은 6 cm예요."],"variant_rule":{"alt":[{"stem":"한 변이 7 cm인 정삼각형과 세 변의 길이의 합이 같은 이등변삼각형이 있어요. 이등변삼각형의 길이가 같은 두 변이 각각 8 cm라면 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형의 세 변의 길이의 합: 7 × 3 = 21.","21 − 8 − 8 = 5.","나머지 한 변은 5 cm예요."],"asset":null},{"stem":"한 변이 10 cm인 정삼각형과 세 변의 길이의 합이 같은 이등변삼각형이 있어요. 이등변삼각형의 길이가 같은 두 변이 각각 12 cm라면 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 세 변의 길이의 합: 10 × 3 = 30.","30 − 12 − 12 = 6.","나머지 한 변은 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
