INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#6','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',3,'sa','auto','한 변이 4 cm인 정삼각형 3개를 변끼리 꼭 맞게 한 줄로 이어 붙였어요. 이어 붙인 모양의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u4-C5","difficulty":3,"kind":"sa","stem":"한 변이 4 cm인 정삼각형 3개를 변끼리 꼭 맞게 한 줄로 이어 붙였어요. 이어 붙인 모양의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["맞붙은 변은 둘레에서 빠져요.","둘레에 남는 변은 5개 — 4 × 5 = 20.","둘레는 20 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,85.282032303],[56.0,16.0],[96.0,85.282032303]],[[56.0,16.0],[96.0,85.282032303],[136.0,16.0]],[[96.0,85.282032303],[136.0,16.0],[176.0,85.282032303]]],"tick":[[[16.0,85.282032303],[56.0,16.0],1],[[56.0,16.0],[96.0,85.282032303],1],[[96.0,85.282032303],[136.0,16.0],1],[[136.0,16.0],[176.0,85.282032303],1],[[16.0,85.282032303],[96.0,85.282032303],1],[[56.0,16.0],[136.0,16.0],1],[[96.0,85.282032303],[176.0,85.282032303],1]],"w":192,"h":101}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변이 5 cm인 정삼각형 2개를 변끼리 꼭 맞게 한 줄로 이어 붙였어요. 이어 붙인 모양의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["맞붙은 변은 둘레에서 빠져요.","둘레에 남는 변은 4개 — 5 × 4 = 20.","둘레는 20 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,85.282032303],[56.0,16.0],[96.0,85.282032303]],[[56.0,16.0],[96.0,85.282032303],[136.0,16.0]]],"tick":[[[16.0,85.282032303],[56.0,16.0],1],[[56.0,16.0],[96.0,85.282032303],1],[[96.0,85.282032303],[136.0,16.0],1],[[16.0,85.282032303],[96.0,85.282032303],1],[[56.0,16.0],[136.0,16.0],1]],"w":152,"h":101}],"tag":false}},{"stem":"한 변이 3 cm인 정삼각형 4개를 변끼리 꼭 맞게 한 줄로 이어 붙였어요. 이어 붙인 모양의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["맞붙은 변은 둘레에서 빠져요.","둘레에 남는 변은 6개 — 3 × 6 = 18.","둘레는 18 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,85.282032303],[56.0,16.0],[96.0,85.282032303]],