INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#7','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',3,'mc','auto','세 변의 길이의 합이 36 cm인 정삼각형의 한 변의 길이를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u4-X07','M4-1-u4-X19']::text[],true,'{"seq":7,"concept":"M4-1-u4-C5","difficulty":3,"kind":"mc","stem":"세 변의 길이의 합이 36 cm인 정삼각형의 한 변의 길이를 바르게 구한 것은 어느 것인가요?","options":[{"t":"12 cm","correct":true},{"t":"108 cm","mis":"M4-1-u4-X07"},{"t":"33 cm","mis":"M4-1-u4-X07"},{"t":"36 cm","mis":"M4-1-u4-X19"}],"explanation":["세 변의 길이가 모두 같아요 — 똑같이 셋으로 나눠요.","36 ÷ 3 = 12.","한 변은 12 cm예요."],"variant_rule":{"alt":[{"stem":"한 변이 14 cm인 정삼각형의 세 변의 길이의 합을 바르게 구한 것은 어느 것인가요?","options":[{"t":"42 cm","correct":true},{"t":"28 cm","mis":"M4-1-u4-X07"},{"t":"17 cm","mis":"M4-1-u4-X07"},{"t":"14 cm","mis":"M4-1-u4-X19"}],"explanation":["세 변이 모두 14 cm예요.","14 × 3 = 42.","세 변의 길이의 합은 42 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 51 cm인 정삼각형의 한 변의 길이를 바르게 구한 것은 어느 것인가요?","options":[{"t":"17 cm","correct":true},{"t":"153 cm","mis":"M4-1-u4-X07"},{"t":"48 cm","mis":"M4-1-u4-X07"},{"t":"51 cm","mis":"M4-1-u4-X19"}],"explanation":["세 변의 길이가 모두 같아요 — 똑같이 셋으로 나눠요.","51 ÷ 3 = 17.","한 변은 17 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#8','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C4',4,'essay','teacher','이등변삼각형 하나를 돌려 뾰족한 꼭짓점이 아래로 가게 놓았어요. 이 삼각형이 여전히 이등변삼각형인지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C4","difficulty":4,"kind":"essay","stem":"이등변삼각형 하나를 돌려 뾰족한 꼭짓점이 아래로 가게 놓았어요. 이 삼각형이 여전히 이등변삼각형인지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 여전히 이등변삼각형이다. 이등변삼각형은 두 변의 길이가 같은 삼각형인데, 돌려 놓아도 변의 길이는 바뀌지 않으므로 두 변의 길이가 여전히 같다.","scoring_points":["이등변삼각형이라고 답했는가","두 변의 길이가 같다는 뜻을 썼는가","돌려도 변의 길이는 그대로라고 했는가"]},"explanation":["이름은 변의 길이로 정해요.","돌리면 방향만 바뀌어요.","그래서 그대로 이등변삼각형."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#9','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',4,'essay','teacher','길이가 15 cm인 철사를 남김없이 모두 써서 정삼각형 하나를 만들었어요. 한 변의 길이를 구하는 방법을 설명하고 답을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C5","difficulty":4,"kind":"essay","stem":"길이가 15 cm인 철사를 남김없이 모두 써서 정삼각형 하나를 만들었어요. 한 변의 길이를 구하는 방법을 설명하고 답을 써 보세요.","answer_guide":{"answer":"예: 정삼각형은 세 변의 길이가 같으므로 철사 15 cm를 똑같이 셋으로 나눈다. 15 ÷ 3 = 5이므로 한 변은 5 cm이다.","scoring_points":["세 변의 길이가 같다고 했는가","15 ÷ 3을 썼는가","5 cm라고 답했는가"]},"explanation":["정삼각형은 세 변이 같아요.","15 ÷ 3 = 5.","한 변은 5 cm."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L03_challenge#10','math',4,1,'u4','L03','g4_1_math_u4_L03_challenge','lesson_challenge','M4-1-u4-C5',4,'sa','auto','한 변이 3 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C5","difficulty":4,"kind":"sa","stem":"한 변이 3 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["큰 정삼각형의 한 변은 작은 정삼각형의 변 2개 — 3 × 2 = 6.","6 × 3 = 18.","세 변의 길이의 합은 18 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"seg":[[[61.0,93.942286341],[151.0,93.942286341]],[[151.0,93.942286341],[106.0,171.884572681]],[[106.0,171.884572681],[61.0,93.942286341]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1],[[196.0,171.884572681],[151.0,93.942286341],1],[[151.0,93.942286341],[106.0,16.0],1],[[106.0,16.0],[61.0,93.942286341],1],[[61.0,93.942286341],[16.0,171.884572681],1]],"w":212,"h":188}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변이 5 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["큰 정삼각형의 한 변은 작은 정삼각형의 변 2개 — 5 × 2 = 10.","10 × 3 = 30.","세 변의 길이의 합은 30 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"seg":[[[61.0,93.942286341],[151.0,93.942286341]],[[151.0,93.942286341],[106.0,171.884572681]],[[106.0,171.884572681],[61.0,93.942286341]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1],[[196.0,171.884572681],[151.0,93.942286341],1],[[151.0,93.942286341],[106.0,16.0],1],[[106.0,16.0],[61.0,93.942286341],1],[[61.0,93.942286341],[16.0,171.884572681],1]],"w":212,"h":188}],"tag":false}}