INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#4','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',1,'mc','auto','이등변삼각형의 성질(접어 보고 알아낸 것)로 알맞은 것은 무엇인가요?',ARRAY['M4-1-u4-X19','M4-1-u4-X09','M4-1-u4-X13']::text[],true,'{"seq":4,"concept":"M4-1-u4-C6","difficulty":1,"kind":"mc","stem":"이등변삼각형의 성질(접어 보고 알아낸 것)로 알맞은 것은 무엇인가요?","options":[{"t":"두 각의 크기가 같아요","correct":true},{"t":"세 각의 크기가 모두 달라요","mis":"M4-1-u4-X19"},{"t":"꼭대기 각과 아래 각의 크기가 같아요","mis":"M4-1-u4-X09"},{"t":"한 각은 언제나 60°예요","mis":"M4-1-u4-X13"}],"explanation":["반으로 접으면 두 각이 꼭 포개져요.","포개진다는 것은 크기가 같다는 뜻이에요.","이등변삼각형은 두 각의 크기가 같아요 — 각에는 「크기」를 써요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 이등변삼각형의 성질(접어 보고 알아낸 것)로 알맞은 것은 무엇인가요?","options":[{"t":"두 각의 크기가 같아요","correct":true},{"t":"세 각의 크기가 모두 달라요","mis":"M4-1-u4-X19"},{"t":"두 변의 크기가 같아요","mis":"M4-1-u4-X06"},{"t":"꼭대기 각과 아래 각의 크기가 같아요","mis":"M4-1-u4-X09"}],"explanation":["반으로 접으면 두 각이 꼭 포개져요.","포개진다는 것은 크기가 같다는 뜻이에요.","이등변삼각형은 두 각의 크기가 같아요 — 각에는 「크기」를 써요."],"asset":null},{"stem":"보기를 바꾸었어요. 이등변삼각형의 성질(접어 보고 알아낸 것)로 알맞은 것은 무엇인가요?","options":[{"t":"두 각의 크기가 같아요","correct":true},{"t":"세 각의 길이가 같아요","mis":"M4-1-u4-X06"},{"t":"세 각의 크기가 모두 달라요","mis":"M4-1-u4-X19"},{"t":"꼭대기 각과 아래 각의 크기가 같아요","mis":"M4-1-u4-X09"}],"explanation":["반으로 접으면 두 각이 꼭 포개져요.","포개진다는 것은 크기가 같다는 뜻이에요.","이등변삼각형은 두 각의 크기가 같아요 — 각에는 「크기」를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#5','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 꼭대기 각이 40°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 40°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["아래쪽 두 각의 합: 180 − 40 = 140.","두 각의 크기가 같으니 140 ÷ 2 = 70.","한 각은 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,166.0],[125.19107028,166.0],[70.59553514,16.0]]],"arc":[[[70.59553514,16.0],[16.0,166.0],[125.19107028,166.0]],[[125.19107028,166.0],[70.59553514,16.0],[16.0,166.0]]],"lab":[[[52.042689949,140.762636801],"?"],[[70.59553514,72.0],"40°"]],"tick":[[[125.19107028,166.0],[70.59553514,16.0],1],[[70.59553514,16.0],[16.0,166.0],1]],"w":141,"h":182}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 80°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["아래쪽 두 각의 합: 180 − 80 = 100.","두 각의 크기가 같으니 100 ÷ 2 = 50.","한 각은 50°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,112.532041],[178.0,112.532041],[97.0,16.0]]],"arc":[[[97.0,16.0],[16.0,112.532041],[178.0,112.532041]],[[178.0,112.532041],[97.0,16.0],[16.0,112.532041]]],"lab":[[[66.753236074,88.865418343],"?"],[[97.0,60.0],"80°"]],"tick":[[[178.0,112.532041],[97.0,16.0],1],[[97.0,16.0],[16.0,112.532041],1]],"w":194,"h":129}],"tag":false}},{"stem":"이등변삼각형의 꼭대기 각이 120°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["아래쪽 두 각의 합: 180 − 120 = 60.","두 각의 크기가 같으니 60 ÷ 2 = 30.","한 각은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,70.547129673],[204.9568,70.547129673],[110.4784,16.0]]],"arc":[[[110.4784,16.0],[16.0,70.547129673],[204.9568,70.547129673]],[[204.9568,70.547129673],[110.4784,16.0],[16.0,70.547129673]]],"lab":[[[70.091846272,56.053263147],"?"],[[110.4784,50.0],"120°"]],"tick":[[[204.9568,70.547129673],[110.4784,16.0],1],[[110.4784,16.0],[16.0,70.547129673],1]],"w":221,"h":87}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#6','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',2,'mc','auto','두 각의 크기가 30°, 120°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X06','M4-1-u4-X21']::text[],true,'{"seq":6,"concept":"M4-1-u4-C6","difficulty":2,"kind":"mc","stem":"두 각의 크기가 30°, 120°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"맞아요 — 나머지 한 각이 30°라서 같은 각이 두 개예요","correct":true},{"t":"아니에요 — 크기가 같은 두 각이 없어요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"아니에요 — 둔각이 있어서예요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 30 − 120 = 30 — 세 각 30°, 120°, 30°.","같은 두 각이 있어요 — 이등변삼각형."],"variant_rule":{"alt":[{"stem":"두 각의 크기가 50°, 80°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"맞아요 — 나머지 한 각이 50°라서 같은 각이 두 개예요","correct":true},{"t":"아니에요 — 크기가 같은 두 각이 없어요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"아니에요 — 세 각이 모두 예각이라서예요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 50 − 80 = 50 — 세 각 50°, 80°, 50°.","같은 두 각이 있어요 — 이등변삼각형."],"asset":null},{"stem":"두 각의 크기가 45°, 95°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 40°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 45 − 95 = 40 — 세 각 45°, 95°, 40°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#7','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 한 각이 100°이고 나머지 두 각의 크기가 서로 같아요. 그 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 한 각이 100°이고 나머지 두 각의 크기가 서로 같아요. 그 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["100°는 둔각이라 같은 각이 하나 더 있을 수 없어요.","(180 − 100) ÷ 2 = 40.","한 각은 40°예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 한 각이 130°이고 나머지 두 각의 크기가 서로 같아요. 그 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["130°는 둔각이라 같은 각이 하나 더 있을 수 없어요.","(180 − 130) ÷ 2 = 25.","한 각은 25°예요."],"asset":null},{"stem":"이등변삼각형의 한 각이 140°이고 나머지 두 각의 크기가 서로 같아요. 그 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["140°는 둔각이라 같은 각이 하나 더 있을 수 없어요.","(180 − 140) ÷ 2 = 20.","한 각은 20°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#8','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',2,'mc','auto','세 각이 60°, 80°, 40°인 삼각형이에요. 이 삼각형이 이등변삼각형이 아닌 까닭은 무엇인가요?',ARRAY['M4-1-u4-X03','M4-1-u4-X21','M4-1-u4-X06']::text[],true,'{"seq":8,"concept":"M4-1-u4-C6","difficulty":2,"kind":"mc","stem":"세 각이 60°, 80°, 40°인 삼각형이에요. 이 삼각형이 이등변삼각형이 아닌 까닭은 무엇인가요?","options":[{"t":"크기가 같은 두 각이 없기 때문이에요","correct":true},{"t":"세 각의 크기의 합이 180°가 아니기 때문이에요","mis":"M4-1-u4-X03"},{"t":"세 각이 모두 예각이기 때문이에요","mis":"M4-1-u4-X21"},{"t":"둔각이 하나도 없기 때문이에요","mis":"M4-1-u4-X06"}],"explanation":["이등변삼각형이면 두 각의 크기가 같아야 해요.","60°, 80°, 40° — 같은 각이 없어요.","그래서 이등변삼각형이 아니에요."],"variant_rule":{"alt":[{"stem":"세 각이 50°, 70°, 60°인 삼각형이에요. 이 삼각형이 이등변삼각형이 아닌 까닭은 무엇인가요?","options":[{"t":"크기가 같은 두 각이 없기 때문이에요","correct":true},{"t":"세 각의 크기의 합이 180°가 아니기 때문이에요","mis":"M4-1-u4-X03"},{"t":"세 각이 모두 예각이기 때문이에요","mis":"M4-1-u4-X21"},{"t":"둔각이 하나도 없기 때문이에요","mis":"M4-1-u4-X06"}],"explanation":["이등변삼각형이면 두 각의 크기가 같아야 해요.","50°, 70°, 60° — 같은 각이 없어요.","그래서 이등변삼각형이 아니에요."],"asset":null},{"stem":"세 각이 30°, 110°, 40°인 삼각형이에요. 이 삼각형이 이등변삼각형이 아닌 까닭은 무엇인가요?","options":[{"t":"크기가 같은 두 각이 없기 때문이에요","correct":true},{"t":"세 각의 크기의 합이 180°가 아니기 때문이에요","mis":"M4-1-u4-X03"},{"t":"둔각이 있기 때문이에요","mis":"M4-1-u4-X21"},{"t":"변의 길이를 재지 않았기 때문이에요","mis":"M4-1-u4-X06"}],"explanation":["이등변삼각형이면 두 각의 크기가 같아야 해요.","30°, 110°, 40° — 같은 각이 없어요.","그래서 이등변삼각형이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#9','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',2,'ox','auto','이등변삼각형을 반으로 접으면 크기가 같은 두 각이 꼭 포개져요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X06']::text[],true,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":2,"kind":"ox","stem":"이등변삼각형을 반으로 접으면 크기가 같은 두 각이 꼭 포개져요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"두 각의 크기가 같아서","correct":true},{"t":"두 변의 길이가 달라서","mis":"M4-1-u4-X06"}],"mis":"M4-1-u4-X06","explanation":["접어서 포개지면 크기가 같아요.","이등변삼각형의 성질이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"이등변삼각형에서는 세 각의 크기가 언제나 모두 같아요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"두 각만 같고 나머지 한 각은 다를 수 있어서","correct":true},{"t":"두 변이 같으면 세 각도 모두 같아서","mis":"M4-1-u4-X17"}],"explanation":["세 각이 모두 같은 것은 정삼각형이에요.","이등변삼각형은 두 각이 같아요.","그래서 틀렸어요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각과 아래쪽 한 각의 크기는 언제나 같아요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"크기가 같은 것은 길이가 같은 두 변에 있는 아래쪽 두 각이라서","correct":true},{"t":"이등변삼각형의 각은 모두 같아서","mis":"M4-1-u4-X09"}],"explanation":["같은 두 각은 길이가 같은 두 변에 있어요.","꼭대기 각은 다를 수 있어요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_basic#10','math',4,1,'u4','L04','g4_1_math_u4_L04_basic','lesson_basic','M4-1-u4-C6',3,'error','auto','이등변삼각형의 꼭대기 각이 40°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X10','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C6","difficulty":3,"kind":"error","stem":"이등변삼각형의 꼭대기 각이 40°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「180 − 40 = 140, 아래쪽 한 각은 140°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"준서 — 「(180 − 40) ÷ 2 = 70°예요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 140°예요.","똑같이 둘로 나누면 140 ÷ 2 = 70.","도윤은 2로 나누지 않았어요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 70°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「180 − 70 = 110, 아래쪽 한 각은 110°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"도윤 — 「(180 − 70) ÷ 2 = 55°예요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 110°예요.","똑같이 둘로 나누면 110 ÷ 2 = 55.","예린은 2로 나누지 않았어요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 100°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「180 − 100 = 80, 아래쪽 한 각은 80°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"예린 — 「(180 − 100) ÷ 2 = 40°예요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 80°예요.","똑같이 둘로 나누면 80 ÷ 2 = 40.","은비는 2로 나누지 않았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#1','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',2,'sa','auto','이등변삼각형에서 크기가 같은 두 각이 각각 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형에서 크기가 같은 두 각이 각각 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["세 각의 합은 180°예요.","180 − 25 − 25 = 130.","나머지 한 각은 130°예요."],"asset":{"type":"geo","items":[{"poly":[[[60.935981201,60.05600145],[249.892781201,60.05600145],[155.414381201,16.0]]],"arc":[[[155.414381201,16.0],[60.935981201,60.05600145],[249.892781201,60.05600145]],[[60.935981201,60.05600145],[249.892781201,60.05600145],[155.414381201,16.0]],[[249.892781201,60.05600145],[155.414381201,16.0],[60.935981201,60.05600145]]],"lab":[[[38.0,65.140786065],"25°"],[[272.828762401,65.140786065],"25°"],[[155.414381201,50.0],"?"]],"tick":[[[249.892781201,60.05600145],[155.414381201,16.0],1],[[155.414381201,16.0],[60.935981201,60.05600145],1]],"w":311,"h":89}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 55°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["세 각의 합은 180°예요.","180 − 55 − 55 = 70.","나머지 한 각은 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]]],"arc":[[[91.0,16.0],[16.0,123.111100506],[166.0,123.111100506]],[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]],[[166.0,123.111100506],[91.0,16.0],[16.0,123.111100506]]],"lab":[[[65.672606658,97.253178164],"55°"],[[116.327393342,97.253178164],"55°"],[[91.0,60.0],"?"]],"tick":[[[166.0,123.111100506],[91.0,16.0],1],[[91.0,16.0],[16.0,123.111100506],1]],"w":182,"h":139}],"tag":false}},{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 35°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["세 각의 합은 180°예요.","180 − 35 − 35 = 110.","나머지 한 각은 110°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,87.446846908],[220.073344,87.446846908],[118.036672,16.0]]],"arc":[[[118.036672,16.0],[16.0,87.446846908],[220.073344,87.446846908]],[[16.0,87.446846908],[220.073344,87.446846908],[118.036672,16.0]],[[220.073344,87.446846908],[118.036672,16.0],[16.0,87.446846908]]],"lab":[[[74.34140102,69.051873825],"35°"],[[161.73194298,69.051873825],"35°"],[[118.036672,50.0],"?"]],"tick":[[[220.073344,87.446846908],[118.036672,16.0],1],[[118.036672,16.0],[16.0,87.446846908],1]],"w":236,"h":103}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#2','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',2,'match','auto','알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u4-C6","difficulty":2,"kind":"match","stem":"알맞게 이으세요.","pairs":[{"l":"이등변삼각형의 뜻","r":"두 변의 길이가 같아요"},{"l":"이등변삼각형의 성질","r":"두 각의 크기가 같아요"},{"l":"「길이」를 쓰는 곳","r":"변"}],"mis":"M4-1-u4-X06","explanation":["뜻은 변, 성질은 각이에요.","이등변삼각형의 뜻 → 두 변의 길이가 같아요, 이등변삼각형의 성질 → 두 각의 크기가 같아요, 「길이」를 쓰는 곳 → 변.","길이는 변에, 크기는 각에 써요."],"variant_rule":{"alt":[{"stem":"짝을 바꾸었어요. 알맞게 이으세요.","pairs":[{"l":"뜻(약속)","r":"두 변의 길이가 같은 삼각형을 이등변삼각형이라 해요"},{"l":"성질(알아낸 것)","r":"그래서 두 각의 크기도 같아요"},{"l":"「크기」를 쓰는 곳","r":"각"}],"explanation":["뜻은 변, 성질은 각이에요.","뜻(약속) → 두 변의 길이가 같은 삼각형을 이등변삼각형이라 해요, 성질(알아낸 것) → 그래서 두 각의 크기도 같아요, 「크기」를 쓰는 곳 → 각.","길이는 변에, 크기는 각에 써요."],"asset":null},{"stem":"짝을 바꾸었어요. 알맞게 이으세요.","pairs":[{"l":"접어 보면 포개지는 것","r":"두 각"},{"l":"자로 재어 같은 것","r":"두 변"},{"l":"각을 견줄 때 쓰는 말","r":"크기"}],"explanation":["뜻은 변, 성질은 각이에요.","접어 보면 포개지는 것 → 두 각, 자로 재어 같은 것 → 두 변, 각을 견줄 때 쓰는 말 → 크기.","길이는 변에, 크기는 각에 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#3','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',3,'sa','auto','꼭대기 각이 40°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"꼭대기 각이 40°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["아래쪽 한 각: (180 − 40) ÷ 2 = 70.","그 각과 ?가 일직선을 이루어요: 180 − 70 = 110.","?는 110°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,210.0],[139.749879651,210.0],[77.874939825,40.0]]],"seg":[[[139.749879651,210.0],[209.749879651,210.0]]],"arc":[[[77.874939825,40.0],[16.0,210.0],[139.749879651,210.0]],[[209.749879651,210.0],[139.749879651,210.0],[77.874939825,40.0]],[[16.0,210.0],[77.874939825,40.0],[139.749879651,210.0]]],"tick":[[[16.0,210.0],[77.874939825,40.0],1],[[139.749879651,210.0],[77.874939825,40.0],1]],"lab":[[[77.874939825,26.0],"40°"],[[159.251478486,182.148830494],"?"]],"w":226,"h":226}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭대기 각이 80°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["아래쪽 한 각: (180 − 80) ÷ 2 = 50.","그 각과 ?가 일직선을 이루어요: 180 − 50 = 130.","?는 130°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,105.381519445],[166.0,105.381519445],[91.0,16.0]]],"seg":[[[166.0,105.381519445],[236.0,105.381519445]]],"arc":[[[91.0,16.0],[16.0,105.381519445],[166.0,105.381519445]],[[236.0,105.381519445],[166.0,105.381519445],[91.0,16.0]],[[16.0,105.381519445],[91.0,16.0],[166.0,105.381519445]]],"tick":[[[16.0,105.381519445],[91.0,16.0],1],[[166.0,105.381519445],[91.0,16.0],1]],"lab":[[[91.0,64.0],"80°"],[[180.369020899,74.567054685],"?"]],"w":252,"h":121}],"tag":false}},{"stem":"꼭대기 각이 100°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["아래쪽 한 각: (180 − 100) ÷ 2 = 40.","그 각과 ?가 일직선을 이루어요: 180 − 40 = 140.","?는 140°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,78.932472338],[166.0,78.932472338],[91.0,16.0]]],"seg":[[[166.0,78.932472338],[236.0,78.932472338]]],"arc":[[[91.0,16.0],[16.0,78.932472338],[166.0,78.932472338]],[[236.0,78.932472338],[166.0,78.932472338],[91.0,16.0]],[[16.0,78.932472338],[91.0,16.0],[166.0,78.932472338]]],"tick":[[[16.0,78.932472338],[91.0,16.0],1],[[166.0,78.932472338],[91.0,16.0],1]],"lab":[[[91.0,64.0],"100°"],[[177.628684873,46.982923232],"?"]],"w":252,"h":95}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#4','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',3,'mc','auto','같은 길이 표시가 있는 이등변삼각형이에요. 각 ㄷㄱㄴ과 크기가 같은 각은 어느 것인가요?',ARRAY['M4-1-u4-X09','M4-1-u4-X17','M4-1-u4-X11']::text[],true,'{"seq":4,"concept":"M4-1-u4-C6","difficulty":3,"kind":"mc","stem":"같은 길이 표시가 있는 이등변삼각형이에요. 각 ㄷㄱㄴ과 크기가 같은 각은 어느 것인가요?","options":[{"t":"각 ㄷㄴㄱ","correct":true},{"t":"각 ㄱㄷㄴ","mis":"M4-1-u4-X09"},{"t":"세 각 모두","mis":"M4-1-u4-X17"},{"t":"크기가 같은 각이 없어요","mis":"M4-1-u4-X11"}],"explanation":["길이가 같은 두 변은 변 ㄱㄷ과 변 ㄴㄷ예요.","그 두 변 아래에 있는 각 ㄷㄱㄴ와 각 ㄷㄴㄱ의 크기가 같아요.","답은 각 ㄷㄴㄱ예요."],"asset":{"type":"geo","items":[{"poly":[[[34.0,194.0],[150.470474965,194.0],[92.235237483,34.0]]],"tick":[[[150.470474965,194.0],[92.235237483,34.0],1],[[92.235237483,34.0],[34.0,194.0],1]],"pts":{"ㄱ":[34.0,194.0],"ㄴ":[150.470474965,194.0],"ㄷ":[92.235237483,34.0]},"w":184,"h":228}],"tag":false},"variant_rule":{"alt":[{"stem":"같은 길이 표시가 있는 이등변삼각형이에요. 각 ㅂㄹㅁ과 크기가 같은 각은 어느 것인가요?","options":[{"t":"각 ㅂㅁㄹ","correct":true},{"t":"각 ㄹㅂㅁ","mis":"M4-1-u4-X09"},{"t":"세 각 모두","mis":"M4-1-u4-X17"},{"t":"크기가 같은 각이 없어요","mis":"M4-1-u4-X11"}],"explanation":["길이가 같은 두 변은 변 ㄹㅂ과 변 ㅁㅂ예요.","그 두 변 아래에 있는 각 ㅂㄹㅁ와 각 ㅂㅁㄹ의 크기가 같아요.","답은 각 ㅂㅁㄹ예요."],"asset":{"type":"geo","items":[{"poly":[[[194.0,34.0],[34.0,34.0],[114.0,101.127970494]]],"tick":[[[34.0,34.0],[114.0,101.127970494],1],[[114.0,101.127970494],[194.0,34.0],1]],"pts":{"ㄹ":[194.0,34.0],"ㅁ":[34.0,34.0],"ㅂ":[114.0,101.127970494]},"w":228,"h":135}],"tag":false}},{"stem":"같은 길이 표시가 있는 이등변삼각형이에요. 각 ㅈㅅㅇ과 크기가 같은 각은 어느 것인가요?","options":[{"t":"각 ㅈㅇㅅ","correct":true},{"t":"각 ㅅㅈㅇ","mis":"M4-1-u4-X09"},{"t":"세 각 모두","mis":"M4-1-u4-X17"},{"t":"크기가 같은 각이 없어요","mis":"M4-1-u4-X11"}],"explanation":["길이가 같은 두 변은 변 ㅅㅈ과 변 ㅇㅈ예요.","그 두 변 아래에 있는 각 ㅈㅅㅇ와 각 ㅈㅇㅅ의 크기가 같아요.","답은 각 ㅈㅇㅅ예요."],"asset":{"type":"geo","items":[{"poly":[[[148.251840539,194.0],[148.251840539,34.0],[34.0,114.0]]],"tick":[[[148.251840539,34.0],[34.0,114.0],1],[[34.0,114.0],[148.251840539,194.0],1]],"pts":{"ㅅ":[148.251840539,194.0],"ㅇ":[148.251840539,34.0],"ㅈ":[34.0,114.0]},"w":182,"h":228}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#5','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',3,'mc','auto','이등변삼각형의 한 각이 40°예요. 나머지 두 각이 될 수 있는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M4-1-u4-X09','M4-1-u4-X11']::text[],true,'{"seq":5,"concept":"M4-1-u4-C6","difficulty":3,"kind":"mc","stem":"이등변삼각형의 한 각이 40°예요. 나머지 두 각이 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"(40°, 100°)와 (70°, 70°) 둘 다","correct":true},{"t":"(70°, 70°)뿐","mis":"M4-1-u4-X09"},{"t":"(40°, 100°)뿐","mis":"M4-1-u4-X09"},{"t":"(70°, 70°)와 (110°, 30°) 둘 다","mis":"M4-1-u4-X11"}],"explanation":["40°인 각이 크기가 같은 두 각 가운데 하나일 수도, 다른 한 각일 수도 있어요.","같은 두 각 중 하나면 40°, 40°, 100° — 다른 한 각이면 (180 − 40) ÷ 2 = 70씩.","답은 (40°, 100°)와 (70°, 70°) 둘 다예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 한 각이 50°예요. 나머지 두 각이 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"(50°, 80°)와 (65°, 65°) 둘 다","correct":true},{"t":"(65°, 65°)뿐","mis":"M4-1-u4-X09"},{"t":"(50°, 80°)뿐","mis":"M4-1-u4-X09"},{"t":"(65°, 65°)와 (25°, 105°) 둘 다","mis":"M4-1-u4-X11"}],"explanation":["50°인 각이 크기가 같은 두 각 가운데 하나일 수도, 다른 한 각일 수도 있어요.","같은 두 각 중 하나면 50°, 50°, 80° — 다른 한 각이면 (180 − 50) ÷ 2 = 65씩.","답은 (50°, 80°)와 (65°, 65°) 둘 다예요."],"asset":null},{"stem":"이등변삼각형의 한 각이 70°예요. 나머지 두 각이 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"(70°, 40°)와 (55°, 55°) 둘 다","correct":true},{"t":"(55°, 55°)뿐","mis":"M4-1-u4-X09"},{"t":"(70°, 40°)뿐","mis":"M4-1-u4-X09"},{"t":"(55°, 55°)와 (105°, 5°) 둘 다","mis":"M4-1-u4-X11"}],"explanation":["70°인 각이 크기가 같은 두 각 가운데 하나일 수도, 다른 한 각일 수도 있어요.","같은 두 각 중 하나면 70°, 70°, 40° — 다른 한 각이면 (180 − 70) ÷ 2 = 55씩.","답은 (70°, 40°)와 (55°, 55°) 둘 다예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#6','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',3,'sa','auto','이등변삼각형의 꼭대기 각이 36°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 36°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["아래쪽 두 각의 합: 180 − 36 = 144.","두 각의 크기가 같으니 144 ÷ 2 = 72.","한 각은 72°예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 108°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["아래쪽 두 각의 합: 180 − 108 = 72.","두 각의 크기가 같으니 72 ÷ 2 = 36.","한 각은 36°예요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 150°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["아래쪽 두 각의 합: 180 − 150 = 30.","두 각의 크기가 같으니 30 ÷ 2 = 15.","한 각은 15°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#7','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',3,'error','auto','이등변삼각형의 꼭대기 각이 20°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X10','M4-1-u4-X19']::text[],true,'{"seq":7,"concept":"M4-1-u4-C6","difficulty":3,"kind":"error","stem":"이등변삼각형의 꼭대기 각이 20°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「180 − 20 = 160, 아래쪽 한 각은 160°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"준서 — 「(180 − 20) ÷ 2 = 80°예요.」","mis":"M4-1-u4-X19"},{"t":"예린 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 160°예요.","똑같이 둘로 나누면 160 ÷ 2 = 80.","지호는 2로 나누지 않았어요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 110°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「180 − 110 = 70, 아래쪽 한 각은 70°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"도윤 — 「(180 − 110) ÷ 2 = 35°예요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 70°예요.","똑같이 둘로 나누면 70 ÷ 2 = 35.","준서는 2로 나누지 않았어요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 140°일 때 아래쪽 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「180 − 140 = 40, 아래쪽 한 각은 40°예요.」","correct":true,"mis_target":"M4-1-u4-X10"},{"t":"나래 — 「(180 − 140) ÷ 2 = 20°예요.」","mis":"M4-1-u4-X19"},{"t":"준서 — 「아래쪽 두 각은 크기가 같아요.」","mis":"M4-1-u4-X19"}],"explanation":["아래쪽 두 각의 합이 40°예요.","똑같이 둘로 나누면 40 ÷ 2 = 20.","예린은 2로 나누지 않았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#8','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',4,'essay','teacher','이등변삼각형의 한 각이 100°예요. 나머지 두 각의 크기를 구하는 풀이 과정을 쓰고, 100°인 각이 크기가 같은 두 각 가운데 하나가 될 수 없는 까닭도 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C6","difficulty":4,"kind":"essay","stem":"이등변삼각형의 한 각이 100°예요. 나머지 두 각의 크기를 구하는 풀이 과정을 쓰고, 100°인 각이 크기가 같은 두 각 가운데 하나가 될 수 없는 까닭도 설명해 보세요.","answer_guide":{"answer":"예: 100°인 각이 두 개라면 두 각만 더해도 200°가 되어 180°를 넘는다. 그래서 100°는 다른 한 각이고, 나머지 두 각은 (180° − 100°) ÷ 2 = 40°씩이다.","scoring_points":["두 각 모두 100°이면 180°를 넘는다고 했는가","(180 − 100) ÷ 2를 썼는가","40°, 40°라고 답했는가"]},"explanation":["둔각은 하나만 있을 수 있어요.","(180 − 100) ÷ 2 = 40.","40°, 40°."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#9','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',4,'essay','teacher','「이등변삼각형은 두 각의 크기가 같아요.」 이 성질을 종이로 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":4,"kind":"essay","stem":"「이등변삼각형은 두 각의 크기가 같아요.」 이 성질을 종이로 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 종이로 이등변삼각형을 오린 뒤, 길이가 같은 두 변이 겹치도록 반으로 접는다. 그러면 두 각이 꼭 포개지므로 두 각의 크기가 같음을 알 수 있다(잘라서 겹치거나 본떠 대어 봐도 된다).","scoring_points":["길이가 같은 두 변이 겹치게 접는다고 했는가","두 각이 포개진다고 했는가","포개지면 크기가 같다고 했는가"]},"explanation":["반으로 접어요.","두 각이 포개져요.","포개지면 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L04_challenge#10','math',4,1,'u4','L04','g4_1_math_u4_L04_challenge','lesson_challenge','M4-1-u4-C6',4,'sa','auto','이등변삼각형의 꼭대기 각이 아래쪽 한 각의 2배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C6","difficulty":4,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 2배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 2묶음.","모두 4묶음 = 180°, 한 묶음 = 180 ÷ 4 = 45.","꼭대기 각 = 45 × 2 = 90 — 90°예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 3배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 3묶음.","모두 5묶음 = 180°, 한 묶음 = 180 ÷ 5 = 36.","꼭대기 각 = 36 × 3 = 108 — 108°예요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 4배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 4묶음.","모두 6묶음 = 180°, 한 묶음 = 180 ÷ 6 = 30.","꼭대기 각 = 30 × 4 = 120 — 120°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
