INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#3','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',1,'sa','auto','정삼각형에서 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C7","difficulty":1,"kind":"sa","stem":"정삼각형에서 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["정삼각형은 세 각이 모두 60°예요.","한 각은 60° — 60 + 60 = 120.","답은 120°예요."],"variant_rule":{"alt":[{"stem":"정삼각형에서 세 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["정삼각형은 세 각이 모두 60°예요.","어느 삼각형이든 세 각의 합은 180°.","답은 180°예요."],"asset":null},{"stem":"정삼각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정삼각형은 세 각이 모두 60°예요.","180 ÷ 3 = 60.","답은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#4','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',1,'mc','auto','큰 정삼각형과 작은 정삼각형의 한 각의 크기를 견주면 어떤가요?',ARRAY['M4-1-u4-X12','M4-1-u4-X06']::text[],true,'{"seq":4,"concept":"M4-1-u4-C7","difficulty":1,"kind":"mc","stem":"큰 정삼각형과 작은 정삼각형의 한 각의 크기를 견주면 어떤가요?","options":[{"t":"둘 다 60°로 똑같아요","correct":true},{"t":"큰 정삼각형의 각이 더 커요","mis":"M4-1-u4-X12"},{"t":"작은 정삼각형의 각이 더 커요","mis":"M4-1-u4-X12"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u4-X06"}],"explanation":["각의 크기는 삼각형이 크고 작은 것과 상관없어요.","정삼각형은 언제나 180 ÷ 3 = 60°.","둘 다 60°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"w":202,"h":179},{"poly":[[[16.0,85.282032303],[96.0,85.282032303],[56.0,16.0]]],"tick":[[[16.0,85.282032303],[96.0,85.282032303],1],[[96.0,85.282032303],[56.0,16.0],1],[[56.0,16.0],[16.0,85.282032303],1]],"w":112,"h":101}]},"variant_rule":{"alt":[{"stem":"한 변이 3 cm인 정삼각형과 한 변이 9 cm인 정삼각형의 한 각의 크기를 견주면 어떤가요?","options":[{"t":"둘 다 60°로 똑같아요","correct":true},{"t":"9 cm인 정삼각형의 각이 3배 더 커요","mis":"M4-1-u4-X12"},{"t":"3 cm인 정삼각형의 각이 더 커요","mis":"M4-1-u4-X12"},{"t":"각을 재어 볼 수 없어요","mis":"M4-1-u4-X19"}],"explanation":["각의 크기는 삼각형이 크고 작은 것과 상관없어요.","정삼각형은 언제나 180 ÷ 3 = 60°.","둘 다 60°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"w":202,"h":179},{"poly":[[[16.0,85.282032303],[96.0,85.282032303],[56.0,16.0]]],"tick":[[[16.0,85.282032303],[96.0,85.282032303],1],[[96.0,85.282032303],[56.0,16.0],1],[[56.0,16.0],[16.0,85.282032303],1]],"w":112,"h":101}]}},{"stem":"운동장에 그린 커다란 정삼각형과 공책에 그린 작은 정삼각형의 한 각의 크기를 견주면 어떤가요?","options":[{"t":"둘 다 60°로 똑같아요","correct":true},{"t":"운동장의 정삼각형 각이 더 커요","mis":"M4-1-u4-X12"},{"t":"공책의 정삼각형 각이 더 뾰족해서 작아요","mis":"M4-1-u4-X21"},{"t":"정삼각형마다 한 각이 달라요","mis":"M4-1-u4-X12"}],"explanation":["각의 크기는 삼각형이 크고 작은 것과 상관없어요.","정삼각형은 언제나 180 ÷ 3 = 60°.","둘 다 60°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"w":202,"h":179},{"poly":[[[16.0,85.282032303],[96.0,85.282032303],[56.0,16.0]]],"tick":[[[16.0,85.282032303],[96.0,85.282032303],1],[[96.0,85.282032303],[56.0,16.0],1],[[56.0,16.0],[16.0,85.282032303],1]],"w":112,"h":101}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#5','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',2,'sa','auto','세 변의 길이의 합이 27 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C7","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 27 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","27 ÷ 3 = 9.","한 변은 9 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 21 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","21 ÷ 3 = 7.","한 변은 7 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 33 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","33 ÷ 3 = 11.","한 변은 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#6','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',2,'mc','auto','두 각의 크기가 60°, 60°인 삼각형이에요. 이 삼각형은 정삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X21','M4-1-u4-X04']::text[],true,'{"seq":6,"concept":"M4-1-u4-C7","difficulty":2,"kind":"mc","stem":"두 각의 크기가 60°, 60°인 삼각형이에요. 이 삼각형은 정삼각형인가요?","options":[{"t":"정삼각형이에요 — 나머지 한 각도 60°라서 세 각이 모두 같아요","correct":true},{"t":"나머지 한 각을 몰라 판단할 수 없어요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형이에요","mis":"M4-1-u4-X21"},{"t":"직각삼각형이에요","mis":"M4-1-u4-X04"}],"explanation":["나머지 한 각부터 구해요: 180 − 60 − 60 = 60.","세 각 60°, 60°, 60°.","세 각이 모두 60°여야 정삼각형이에요."],"variant_rule":{"alt":[{"stem":"두 각의 크기가 60°, 70°인 삼각형이에요. 이 삼각형은 정삼각형인가요?","options":[{"t":"정삼각형이 아니에요 — 나머지 한 각이 50°라서 세 각이 모두 같지는 않아요","correct":true},{"t":"정삼각형이에요 — 60°가 있어서예요","mis":"M4-1-u4-X11"},{"t":"나머지 한 각을 몰라 판단할 수 없어요","mis":"M4-1-u4-X11"},{"t":"정삼각형이에요 — 두 각이 같아서예요","mis":"M4-1-u4-X17"}],"explanation":["나머지 한 각부터 구해요: 180 − 60 − 70 = 50.","세 각 60°, 70°, 50°.","세 각이 모두 60°여야 정삼각형이에요."],"asset":null},{"stem":"두 각의 크기가 60°, 50°인 삼각형이에요. 이 삼각형은 정삼각형인가요?","options":[{"t":"정삼각형이 아니에요 — 나머지 한 각이 70°라서 세 각이 모두 같지는 않아요","correct":true},{"t":"정삼각형이에요 — 60°가 있어서예요","mis":"M4-1-u4-X11"},{"t":"나머지 한 각을 몰라 판단할 수 없어요","mis":"M4-1-u4-X11"},{"t":"정삼각형이에요 — 두 각이 같아서예요","mis":"M4-1-u4-X17"}],"explanation":["나머지 한 각부터 구해요: 180 − 60 − 50 = 70.","세 각 60°, 50°, 70°.","세 각이 모두 60°여야 정삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#7','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',2,'sa','auto','정삼각형을 반으로 접었더니 꼭대기 각이 반으로 나뉘었어요. 나뉜 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u4-C7","difficulty":2,"kind":"sa","stem":"정삼각형을 반으로 접었더니 꼭대기 각이 반으로 나뉘었어요. 나뉜 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형의 한 각은 60°예요.","60 ÷ 2 = 30.","답은 30°예요."],"variant_rule":{"alt":[{"stem":"정삼각형 두 개를 한 꼭짓점에서 나란히 붙였어요. 붙인 두 각을 합친 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["정삼각형의 한 각은 60°예요.","60 + 60 = 120.","답은 120°예요."],"asset":null},{"stem":"정삼각형 세 개를 한 꼭짓점에 나란히 모았어요. 모은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["정삼각형의 한 각은 60°예요.","60 × 3 = 180 — 일직선이에요.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#8','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',2,'mc','auto','정삼각형의 한 각이 60°인 까닭은 무엇인가요?',ARRAY['M4-1-u4-X13','M4-1-u4-X03','M4-1-u4-X12']::text[],true,'{"seq":8,"concept":"M4-1-u4-C7","difficulty":2,"kind":"mc","stem":"정삼각형의 한 각이 60°인 까닭은 무엇인가요?","options":[{"t":"세 각의 크기가 모두 같고 합이 180°라서 180 ÷ 3 = 60이기 때문이에요","correct":true},{"t":"한 바퀴 360°를 셋으로 나누었기 때문이에요","mis":"M4-1-u4-X13"},{"t":"삼각형의 세 각의 크기의 합이 60°이기 때문이에요","mis":"M4-1-u4-X03"},{"t":"정삼각형은 크기가 작아서 각도 작기 때문이에요","mis":"M4-1-u4-X12"}],"explanation":["어느 방향으로 접어도 두 각이 포개져 세 각이 모두 같아요.","세 각의 합 180°를 똑같이 셋으로 — 180 ÷ 3 = 60.","그래서 한 각은 60°예요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 정삼각형의 한 각이 60°인 까닭은 무엇인가요?","options":[{"t":"세 각의 크기가 모두 같고 합이 180°라서 180 ÷ 3 = 60이기 때문이에요","correct":true},{"t":"세 변의 길이가 같으면 각은 무조건 60°로 정해 두었기 때문이에요","mis":"M4-1-u4-X06"},{"t":"정삼각형은 크기가 작아서 각도 작기 때문이에요","mis":"M4-1-u4-X12"},{"t":"한 바퀴 360°를 셋으로 나누었기 때문이에요","mis":"M4-1-u4-X13"}],"explanation":["어느 방향으로 접어도 두 각이 포개져 세 각이 모두 같아요.","세 각의 합 180°를 똑같이 셋으로 — 180 ÷ 3 = 60.","그래서 한 각은 60°예요."],"asset":null},{"stem":"보기를 바꾸었어요. 정삼각형의 한 각이 60°인 까닭은 무엇인가요?","options":[{"t":"세 각의 크기가 모두 같고 합이 180°라서 180 ÷ 3 = 60이기 때문이에요","correct":true},{"t":"한 바퀴 360°를 셋으로 나누었기 때문이에요","mis":"M4-1-u4-X13"},{"t":"삼각형의 세 각의 크기의 합이 60°이기 때문이에요","mis":"M4-1-u4-X03"},{"t":"정삼각형은 크기가 작아서 각도 작기 때문이에요","mis":"M4-1-u4-X12"}],"explanation":["어느 방향으로 접어도 두 각이 포개져 세 각이 모두 같아요.","세 각의 합 180°를 똑같이 셋으로 — 180 ÷ 3 = 60.","그래서 한 각은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#9','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',2,'ox','auto','정삼각형은 세 각의 길이가 모두 같아요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X06']::text[],true,'{"seq":9,"concept":"M4-1-u4-C7","difficulty":2,"kind":"ox","stem":"정삼각형은 세 각의 길이가 모두 같아요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"각에는 길이가 아니라 크기를 써서 「세 각의 크기」가 같아서","correct":true},{"t":"각도 변처럼 길이를 재어서","mis":"M4-1-u4-X06"}],"mis":"M4-1-u4-X06","explanation":["길이는 변에, 크기는 각에 써요.","「세 각의 크기가 같아요」가 맞아요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"정삼각형 가운데 둔각이 있는 것도 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"세 각이 모두 60°라서 예각뿐이라서","correct":true},{"t":"크게 그리면 둔각이 생겨서","mis":"M4-1-u4-X12"}],"explanation":["정삼각형은 언제나 60°·60°·60°예요.","둔각이 있을 수 없어요.","그래서 틀렸어요."],"asset":null},{"stem":"변이 긴 정삼각형일수록 한 각이 커요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"크기와 상관없이 한 각은 언제나 60°라서","correct":true},{"t":"변이 길면 벌어진 정도도 커서","mis":"M4-1-u4-X12"}],"explanation":["각의 크기는 벌어진 정도예요.","정삼각형은 모두 60°예요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_basic#10','math',4,1,'u4','L05','g4_1_math_u4_L05_basic','lesson_basic','M4-1-u4-C7',3,'error','auto','정삼각형의 한 각을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X13','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C7","difficulty":3,"kind":"error","stem":"정삼각형의 한 각을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「180 ÷ 2 = 90이라 정삼각형의 한 각은 90°예요.」","correct":true,"mis_target":"M4-1-u4-X13"},{"t":"준서 — 「180 ÷ 3 = 60이라 한 각은 60°예요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「크든 작든 한 각은 언제나 60°예요.」","mis":"M4-1-u4-X19"}],"explanation":["세 각의 크기가 모두 같고 합은 180°예요.","180 ÷ 3 = 60.","도윤이 잘못 말했어요 — 180°를 똑같이 셋으로."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 정삼각형의 한 각을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「360 ÷ 3 = 120이라 정삼각형의 한 각은 120°예요.」","correct":true,"mis_target":"M4-1-u4-X13"},{"t":"도윤 — 「180 ÷ 3 = 60이라 한 각은 60°예요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「크든 작든 한 각은 언제나 60°예요.」","mis":"M4-1-u4-X19"}],"explanation":["세 각의 크기가 모두 같고 합은 180°예요.","180 ÷ 3 = 60.","예린이 잘못 말했어요 — 180°를 똑같이 셋으로."],"asset":null},{"stem":"보기를 바꾸었어요. 정삼각형의 한 각을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「큰 정삼각형은 한 각이 60°보다 커요.」","correct":true,"mis_target":"M4-1-u4-X12"},{"t":"예린 — 「180 ÷ 3 = 60이라 한 각은 60°예요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「크든 작든 한 각은 언제나 60°예요.」","mis":"M4-1-u4-X19"}],"explanation":["세 각의 크기가 모두 같고 합은 180°예요.","180 ÷ 3 = 60.","은비가 잘못 말했어요 — 크든 작든 60°."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#1','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',2,'sa','auto','정삼각형의 한 각과 직각의 크기의 차는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C7","difficulty":2,"kind":"sa","stem":"정삼각형의 한 각과 직각의 크기의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형은 세 각이 모두 60°예요.","90 − 60 = 30.","답은 30°예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 한 각을 똑같이 반으로 나눈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형은 세 각이 모두 60°예요.","60 ÷ 2 = 30.","답은 30°예요."],"asset":null},{"stem":"정삼각형 두 개의 각을 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["정삼각형은 세 각이 모두 60°예요.","180 + 180 = 360.","답은 360°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#2','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',2,'sa','auto','세 변의 길이의 합이 45 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u4-C7","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 45 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","45 ÷ 3 = 15.","한 변은 15 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 39 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","39 ÷ 3 = 13.","한 변은 13 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 57 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["정삼각형은 세 변과 세 각이 모두 같아요.","57 ÷ 3 = 19.","한 변은 19 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#3','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',3,'sa','auto','한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 한 각은 60°예요.","한 바퀴 360° — 360 ÷ 60 = 6.","6개예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 각을 한 점에 나란히 모아 일직선(180°)을 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형의 한 각은 60°예요.","180 ÷ 60 = 3.","3개예요."],"asset":null},{"stem":"정삼각형의 각을 한 점에 나란히 모아 240°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형의 한 각은 60°예요.","240 ÷ 60 = 4.","4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#4','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',3,'sa','auto','정삼각형 한 각에 직각을 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"정삼각형 한 각에 직각을 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["정삼각형의 한 각은 60°예요.","60 + 90 = 150.","답은 150°예요."],"variant_rule":{"alt":[{"stem":"정삼각형 네 개를 한 꼭짓점에 나란히 모았어요. 모은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["240"],"explanation":["정삼각형의 한 각은 60°예요.","60 × 4 = 240.","답은 240°예요."],"asset":null},{"stem":"정삼각형 세 개를 한 꼭짓점에 나란히 모았어요. 모은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["정삼각형의 한 각은 60°예요.","60 × 3 = 180 — 일직선이에요.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#5','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',3,'sa','auto','정삼각형을 꼭대기에서 밑변의 가운데로 반 접어 잘랐어요. 잘린 반쪽 삼각형의 가장 작은 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"정삼각형을 꼭대기에서 밑변의 가운데로 반 접어 잘랐어요. 잘린 반쪽 삼각형의 가장 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["꼭대기 각 60°가 반으로 — 30°.","반쪽 삼각형의 세 각은 30°, 60°, 90°.","답은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"dash":[[[106.0,16.0],[106.0,171.884572681]]],"right":[[[106.0,16.0],[106.0,171.884572681],[196.0,171.884572681]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1]],"w":212,"h":188}],"tag":false},"variant_rule":{"alt":[{"stem":"정삼각형을 꼭대기에서 밑변의 가운데로 반 접어 잘랐어요. 잘린 반쪽 삼각형의 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["접은 선은 밑변과 직각으로 만나요.","반쪽 삼각형의 세 각은 30°, 60°, 90°.","답은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"dash":[[[106.0,16.0],[106.0,171.884572681]]],"right":[[[106.0,16.0],[106.0,171.884572681],[196.0,171.884572681]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1]],"w":212,"h":188}],"tag":false}},{"stem":"정삼각형을 꼭대기에서 밑변의 가운데로 반 접어 잘랐어요. 잘린 반쪽 삼각형에서 직각이 아닌 두 각의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["30 + 60 = 90.","180 − 90 = 90 과 같아요.","답은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"dash":[[[106.0,16.0],[106.0,171.884572681]]],"right":[[[106.0,16.0],[106.0,171.884572681],[196.0,171.884572681]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1]],"w":212,"h":188}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#6','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',3,'mc','auto','정삼각형의 세 각이 될 수 있는 것은 어느 것인가요?',ARRAY['M4-1-u4-X17','M4-1-u4-X16']::text[],true,'{"seq":6,"concept":"M4-1-u4-C7","difficulty":3,"kind":"mc","stem":"정삼각형의 세 각이 될 수 있는 것은 어느 것인가요?","options":[{"t":"60°, 60°, 60°","correct":true},{"t":"90°, 45°, 45°","mis":"M4-1-u4-X17"},{"t":"60°, 90°, 30°","mis":"M4-1-u4-X17"},{"t":"80°, 50°, 50°","mis":"M4-1-u4-X16"}],"explanation":["정삼각형은 세 각의 크기가 모두 같아요.","합이 180°여도 세 각이 같아야 해요.","될 수 있는 것은 60°, 60°, 60°예요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 정삼각형의 세 각이 될 수 있는 것은 어느 것인가요?","options":[{"t":"60°, 60°, 60°","correct":true},{"t":"90°, 45°, 45°","mis":"M4-1-u4-X17"},{"t":"60°, 90°, 30°","mis":"M4-1-u4-X17"},{"t":"50°, 60°, 70°","mis":"M4-1-u4-X11"}],"explanation":["정삼각형은 세 각의 크기가 모두 같아요.","합이 180°여도 세 각이 같아야 해요.","될 수 있는 것은 60°, 60°, 60°예요."],"asset":null},{"stem":"보기를 바꾸었어요. 정삼각형의 세 각이 될 수 있는 것은 어느 것인가요?","options":[{"t":"60°, 60°, 60°","correct":true},{"t":"60°, 60°, 70°","mis":"M4-1-u4-X11"},{"t":"90°, 45°, 45°","mis":"M4-1-u4-X17"},{"t":"60°, 90°, 30°","mis":"M4-1-u4-X17"}],"explanation":["정삼각형은 세 각의 크기가 모두 같아요.","합이 180°여도 세 각이 같아야 해요.","될 수 있는 것은 60°, 60°, 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#7','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',3,'ox','auto','정삼각형은 어느 방향으로 접어도 두 각이 포개져요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X06']::text[],true,'{"seq":7,"concept":"M4-1-u4-C7","difficulty":3,"kind":"ox","stem":"정삼각형은 어느 방향으로 접어도 두 각이 포개져요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"세 각의 크기가 모두 같아서","correct":true},{"t":"세 변의 길이가 모두 달라서","mis":"M4-1-u4-X06"}],"mis":"M4-1-u4-X06","explanation":["세 변이 같아 어느 쪽으로 접어도 맞아요.","그래서 세 각이 모두 같아요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"정삼각형 가운데 둔각이 있는 것도 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"세 각이 모두 60°라서 예각뿐이라서","correct":true},{"t":"크게 그리면 둔각이 생겨서","mis":"M4-1-u4-X12"}],"explanation":["정삼각형은 언제나 60°·60°·60°예요.","둔각이 있을 수 없어요.","그래서 틀렸어요."],"asset":null},{"stem":"변이 긴 정삼각형일수록 한 각이 커요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"크기와 상관없이 한 각은 언제나 60°라서","correct":true},{"t":"변이 길면 벌어진 정도도 커서","mis":"M4-1-u4-X12"}],"explanation":["각의 크기는 벌어진 정도예요.","정삼각형은 모두 60°예요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#8','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',4,'essay','teacher','정삼각형의 한 각이 60°인 까닭을 「접어 보기」와 「세 각의 크기의 합」을 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C7","difficulty":4,"kind":"essay","stem":"정삼각형의 한 각이 60°인 까닭을 「접어 보기」와 「세 각의 크기의 합」을 이용하여 설명해 보세요.","answer_guide":{"answer":"예: 정삼각형은 어느 방향으로 접어도 두 각이 포개지므로 세 각의 크기가 모두 같다. 세 각의 합은 180°이므로 한 각은 180° ÷ 3 = 60°이다.","scoring_points":["접으면 각이 포개져 세 각이 같다고 했는가","세 각의 합 180°를 썼는가","180 ÷ 3 = 60을 썼는가"]},"explanation":["세 각이 모두 같아요.","합은 180°.","180 ÷ 3 = 60."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#9','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',4,'essay','teacher','서아는 「한 변이 10 cm인 정삼각형은 한 변이 5 cm인 정삼각형보다 한 각이 2배 커요.」라고 말했어요. 서아의 말이 맞는지 쓰고 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C7","difficulty":4,"kind":"essay","stem":"서아는 「한 변이 10 cm인 정삼각형은 한 변이 5 cm인 정삼각형보다 한 각이 2배 커요.」라고 말했어요. 서아의 말이 맞는지 쓰고 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀리다. 각의 크기는 변의 길이와 상관없이 두 변이 벌어진 정도이다. 정삼각형은 크기와 상관없이 세 각이 모두 같고 합이 180°이므로 두 정삼각형 모두 한 각은 60°이다.","scoring_points":["틀리다고 답했는가","각의 크기는 변의 길이와 상관없다고 했는가","두 정삼각형 모두 60°라고 했는가"]},"explanation":["각은 벌어진 정도.","정삼각형은 언제나 60°.","서아의 말은 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L05_challenge#10','math',4,1,'u4','L05','g4_1_math_u4_L05_challenge','lesson_challenge','M4-1-u4-C7',4,'sa','auto','정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄷㄱㄹ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C7","difficulty":4,"kind":"sa","stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄷㄱㄹ은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["삼각형 ㄱㄷㄹ의 각 ㄱㄷㄹ = 180 − 60 = 120.","(180 − 120) ÷ 2 = 30.","각 ㄷㄱㄹ은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false},"variant_rule":{"alt":[{"stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄱㄹㄷ은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["각 ㄱㄷㄹ = 180 − 60 = 120, 삼각형 ㄱㄷㄹ 은 이등변삼각형.","(180 − 120) ÷ 2 = 30.","각 ㄱㄹㄷ은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false}},{"stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄴㄱㄹ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["각 ㄷㄱㄹ = (180 − 120) ÷ 2 = 30.","60 + 30 = 90.","각 ㄴㄱㄹ은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#1','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',1,'mc','auto','한 각이 직각이고 두 변의 길이가 같은 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X14','M4-1-u4-X04','M4-1-u4-X21']::text[],true,'{"seq":1,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"한 각이 직각이고 두 변의 길이가 같은 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"직각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 이등변삼각형","답은 「직각삼각형, 이등변삼각형」이에요."],"variant_rule":{"alt":[{"stem":"세 각이 70°, 70°, 40°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형","답은 「예각삼각형, 이등변삼각형」이에요."],"asset":null},{"stem":"세 각이 100°, 40°, 40°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"둔각삼각형, 이등변삼각형","correct":true},{"t":"둔각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 둔각삼각형, 변으로 → 이등변삼각형","답은 「둔각삼각형, 이등변삼각형」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
