INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#4','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',1,'mc','auto','하나의 삼각형을 여러 이름으로 부를 수 있는 까닭은 무엇인가요?',ARRAY['M4-1-u4-X15','M4-1-u4-X14']::text[],true,'{"seq":4,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"하나의 삼각형을 여러 이름으로 부를 수 있는 까닭은 무엇인가요?","options":[{"t":"각의 크기와 변의 길이, 두 가지 잣대로 나눌 수 있기 때문이에요","correct":true},{"t":"각으로 붙이는 이름이 여러 개이기 때문이에요","mis":"M4-1-u4-X15"},{"t":"삼각형의 이름을 마음대로 지어도 되기 때문이에요","mis":"M4-1-u4-X14"},{"t":"삼각형은 변이 3개이기 때문이에요","mis":"M4-1-u4-X14"}],"explanation":["각의 크기로 나누면 예각·직각·둔각삼각형이에요.","변의 길이로 나누면 이등변삼각형·정삼각형이에요.","서로 다른 잣대라서 이름을 따로따로 붙여요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 하나의 삼각형을 여러 이름으로 부를 수 있는 까닭은 무엇인가요?","options":[{"t":"각의 크기와 변의 길이, 두 가지 잣대로 나눌 수 있기 때문이에요","correct":true},{"t":"삼각형마다 크기가 다르기 때문이에요","mis":"M4-1-u4-X21"},{"t":"삼각형은 변이 3개이기 때문이에요","mis":"M4-1-u4-X14"},{"t":"각으로 붙이는 이름이 여러 개이기 때문이에요","mis":"M4-1-u4-X15"}],"explanation":["각의 크기로 나누면 예각·직각·둔각삼각형이에요.","변의 길이로 나누면 이등변삼각형·정삼각형이에요.","서로 다른 잣대라서 이름을 따로따로 붙여요."],"asset":null},{"stem":"보기를 바꾸었어요. 하나의 삼각형을 여러 이름으로 부를 수 있는 까닭은 무엇인가요?","options":[{"t":"각의 크기와 변의 길이, 두 가지 잣대로 나눌 수 있기 때문이에요","correct":true},{"t":"각으로 붙이는 이름이 여러 개이기 때문이에요","mis":"M4-1-u4-X15"},{"t":"삼각형의 이름을 마음대로 지어도 되기 때문이에요","mis":"M4-1-u4-X14"},{"t":"삼각형은 변이 3개이기 때문이에요","mis":"M4-1-u4-X14"}],"explanation":["각의 크기로 나누면 예각·직각·둔각삼각형이에요.","변의 길이로 나누면 이등변삼각형·정삼각형이에요.","서로 다른 잣대라서 이름을 따로따로 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#5','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',2,'mc','auto','세 각이 45°, 45°, 90°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X14','M4-1-u4-X04','M4-1-u4-X21']::text[],true,'{"seq":5,"concept":"M4-1-u4-C8","difficulty":2,"kind":"mc","stem":"세 각이 45°, 45°, 90°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"직각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 이등변삼각형","답은 「직각삼각형, 이등변삼각형」이에요."],"variant_rule":{"alt":[{"stem":"세 각이 30°, 30°, 120°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"둔각삼각형, 이등변삼각형","correct":true},{"t":"둔각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 둔각삼각형, 변으로 → 이등변삼각형","답은 「둔각삼각형, 이등변삼각형」이에요."],"asset":null},{"stem":"세 각이 60°, 60°, 60°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형, 이등변삼각형, 정삼각형","correct":true},{"t":"예각삼각형, 정삼각형","mis":"M4-1-u4-X16"},{"t":"예각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"직각삼각형, 이등변삼각형, 정삼각형","mis":"M4-1-u4-X04"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형 · 정삼각형","답은 「예각삼각형, 이등변삼각형, 정삼각형」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#6','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',2,'sa','auto','세 각이 30°, 75°, 75°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u4-C8","difficulty":2,"kind":"sa","stem":"세 각이 30°, 75°, 75°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각으로 이름 하나: 예각삼각형.","변으로: 이등변삼각형.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"세 각이 20°, 80°, 80°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각으로 이름 하나: 예각삼각형.","변으로: 이등변삼각형.","모두 2개예요."],"asset":null},{"stem":"세 각이 45°, 90°, 45°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각으로 이름 하나: 직각삼각형.","변으로: 이등변삼각형.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#7','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',2,'mc','auto','예각삼각형이면서 둔각삼각형인 삼각형이 있을까요?',ARRAY['M4-1-u4-X15','M4-1-u4-X21','M4-1-u4-X06']::text[],true,'{"seq":7,"concept":"M4-1-u4-C8","difficulty":2,"kind":"mc","stem":"예각삼각형이면서 둔각삼각형인 삼각형이 있을까요?","options":[{"t":"없어요 — 각으로 붙이는 이름은 하나뿐이에요","correct":true},{"t":"있어요 — 예각이 2개, 둔각이 1개이면 돼요","mis":"M4-1-u4-X15"},{"t":"있어요 — 삼각형의 크기에 따라 달라져요","mis":"M4-1-u4-X21"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u4-X06"}],"explanation":["각으로는 반드시 하나의 이름, 변으로는 붙을 수도 안 붙을 수도 있어요.","각 이름끼리는 함께 붙지 않고, 각 이름과 변 이름은 함께 붙을 수 있어요.","답은 「없어요 — 각으로 붙이는 이름은 하나뿐이에요」예요."],"variant_rule":{"alt":[{"stem":"직각삼각형이면서 둔각삼각형인 삼각형이 있을까요?","options":[{"t":"없어요 — 직각과 둔각을 함께 가질 수 없어요","correct":true},{"t":"있어요 — 직각 1개, 둔각 1개이면 돼요","mis":"M4-1-u4-X02"},{"t":"있어요 — 이등변삼각형이면 돼요","mis":"M4-1-u4-X15"},{"t":"세 각을 재어 봐야 알 수 있어요","mis":"M4-1-u4-X11"}],"explanation":["각으로는 반드시 하나의 이름, 변으로는 붙을 수도 안 붙을 수도 있어요.","각 이름끼리는 함께 붙지 않고, 각 이름과 변 이름은 함께 붙을 수 있어요.","답은 「없어요 — 직각과 둔각을 함께 가질 수 없어요」예요."],"asset":null},{"stem":"직각삼각형이면서 이등변삼각형인 삼각형이 있을까요?","options":[{"t":"있어요 — 세 각이 90°, 45°, 45°이면 돼요","correct":true},{"t":"없어요 — 각으로 붙이는 이름이 하나뿐이라서요","mis":"M4-1-u4-X14"},{"t":"없어요 — 직각이 있으면 두 변이 같을 수 없어요","mis":"M4-1-u4-X21"},{"t":"있어요 — 직각이 2개이면 돼요","mis":"M4-1-u4-X02"}],"explanation":["각으로는 반드시 하나의 이름, 변으로는 붙을 수도 안 붙을 수도 있어요.","각 이름끼리는 함께 붙지 않고, 각 이름과 변 이름은 함께 붙을 수 있어요.","답은 「있어요 — 세 각이 90°, 45°, 45°이면 돼요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#8','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',2,'mc','auto','다리에서 찾은 삼각형의 세 각은 70°, 70°, 40°예요. 이 삼각형이 예각삼각형이면서 이등변삼각형인 까닭은 무엇인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X14','M4-1-u4-X19']::text[],true,'{"seq":8,"concept":"M4-1-u4-C8","difficulty":2,"kind":"mc","stem":"다리에서 찾은 삼각형의 세 각은 70°, 70°, 40°예요. 이 삼각형이 예각삼각형이면서 이등변삼각형인 까닭은 무엇인가요?","options":[{"t":"세 각이 모두 예각이고, 두 변의 길이가 같기 때문이에요","correct":true},{"t":"예각이 하나 있고 변이 3개이기 때문이에요","mis":"M4-1-u4-X01"},{"t":"각이 3개이고 변도 3개이기 때문이에요","mis":"M4-1-u4-X14"},{"t":"세 변의 길이가 모두 다르기 때문이에요","mis":"M4-1-u4-X19"}],"explanation":["각으로: 세 각이 모두 예각 → 예각삼각형.","변으로: 크기가 같은 두 각 → 두 변의 길이가 같아요 → 이등변삼각형.","두 잣대로 이름이 둘이에요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,186.0],[139.749879651,186.0],[77.874939825,16.0]]],"arc":[[[77.874939825,16.0],[16.0,186.0],[139.749879651,186.0]],[[16.0,186.0],[139.749879651,186.0],[77.874939825,16.0]],[[139.749879651,186.0],[77.874939825,16.0],[16.0,186.0]]],"lab":[[[52.042689949,160.762636801],"70°"],[[103.707189702,160.762636801],"70°"],[[77.874939825,72.0],"40°"]],"tick":[[[139.749879651,186.0],[77.874939825,16.0],1],[[77.874939825,16.0],[16.0,186.0],1]],"w":156,"h":202}],"tag":false},"variant_rule":{"alt":[{"stem":"다리에서 찾은 삼각형의 세 각은 120°, 30°, 30°예요. 이 삼각형이 둔각삼각형이면서 이등변삼각형인 까닭은 무엇인가요?","options":[{"t":"한 각이 둔각이고, 두 변의 길이가 같기 때문이에요","correct":true},{"t":"예각이 하나 있고 변이 3개이기 때문이에요","mis":"M4-1-u4-X01"},{"t":"각이 3개이고 변도 3개이기 때문이에요","mis":"M4-1-u4-X14"},{"t":"세 변의 길이가 모두 다르기 때문이에요","mis":"M4-1-u4-X19"}],"explanation":["각으로: 한 각이 둔각 → 둔각삼각형.","변으로: 크기가 같은 두 각 → 두 변의 길이가 같아요 → 이등변삼각형.","두 잣대로 이름이 둘이에요."],"asset":{"type":"geo","items":[{"poly":[[[87.38368,139.640160591],[230.15104,139.640160591],[16.0,16.0]]],"arc":[[[16.0,16.0],[87.38368,139.640160591],[230.15104,139.640160591]],[[87.38368,139.640160591],[230.15104,139.640160591],[16.0,16.0]],[[230.15104,139.640160591],[16.0,16.0],[87.38368,139.640160591]]],"lab":[[[104.38368,110.195296863],"120°"],[[161.969036337,121.370847771],"30°"],[[65.912690843,65.912690843],"30°"]],"tick":[[[87.38368,139.640160591],[230.15104,139.640160591],1],[[16.0,16.0],[87.38368,139.640160591],1]],"w":246,"h":156}],"tag":false}},{"stem":"다리에서 찾은 삼각형의 세 각은 45°, 90°, 45°예요. 이 삼각형이 직각삼각형이면서 이등변삼각형인 까닭은 무엇인가요?","options":[{"t":"한 각이 직각이고, 두 변의 길이가 같기 때문이에요","correct":true},{"t":"예각이 하나 있고 변이 3개이기 때문이에요","mis":"M4-1-u4-X01"},{"t":"각이 3개이고 변도 3개이기 때문이에요","mis":"M4-1-u4-X14"},{"t":"세 변의 길이가 모두 다르기 때문이에요","mis":"M4-1-u4-X19"}],"explanation":["각으로: 한 각이 직각 → 직각삼각형.","변으로: 크기가 같은 두 각 → 두 변의 길이가 같아요 → 이등변삼각형.","두 잣대로 이름이 둘이에요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,186.0],[186.0,186.0],[186.0,16.0]]],"arc":[[[186.0,16.0],[16.0,186.0],[186.0,186.0]],[[186.0,186.0],[186.0,16.0],[16.0,186.0]]],"lab":[[[67.737253821,164.569727788],"45°"],[[154.887301628,154.887301628],"90°"],[[164.569727788,67.737253821],"45°"]],"right":[[[16.0,186.0],[186.0,186.0],[186.0,16.0]]],"tick":[[[16.0,186.0],[186.0,186.0],1],[[186.0,186.0],[186.0,16.0],1]],"w":203,"h":202}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#9','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C9',2,'ox','auto','정삼각형은 이등변삼각형이라고 할 수 있어요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X16']::text[],true,'{"seq":9,"concept":"M4-1-u4-C9","difficulty":2,"kind":"ox","stem":"정삼각형은 이등변삼각형이라고 할 수 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"세 변의 길이가 같으면 두 변의 길이도 같아서","correct":true},{"t":"세 변이 같으면 「두 변」이 같다는 말에 맞지 않아서","mis":"M4-1-u4-X16"}],"mis":"M4-1-u4-X16","explanation":["이등변삼각형은 「두 변의 길이가 같은 삼각형」이에요.","정삼각형은 어느 두 변을 골라도 같아요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"이등변삼각형은 모두 정삼각형이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"두 변만 같고 나머지 한 변은 다를 수 있어서","correct":true},{"t":"두 변이 같으면 세 변도 같아서","mis":"M4-1-u4-X17"}],"explanation":["이등변삼각형 가운데 세 변이 모두 같은 것만 정삼각형이에요.","5 cm, 5 cm, 3 cm 처럼 다를 수 있어요.","그래서 틀렸어요."],"asset":null},{"stem":"정삼각형은 언제나 예각삼각형이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"세 각이 모두 60°로 예각이라서","correct":true},{"t":"크기에 따라 둔각삼각형이 될 수도 있어서","mis":"M4-1-u4-X17"}],"explanation":["정삼각형의 세 각은 60°예요.","60°는 예각이에요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_basic#10','math',4,1,'u4','L06','g4_1_math_u4_L06_basic','lesson_basic','M4-1-u4-C8',3,'error','auto','세 각이 80°, 50°, 50°인 삼각형의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X14','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C8","difficulty":3,"kind":"error","stem":"세 각이 80°, 50°, 50°인 삼각형의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「이 삼각형은 이등변삼각형이라서 다른 이름은 붙일 수 없어요.」","correct":true,"mis_target":"M4-1-u4-X14"},{"t":"준서 — 「각으로 보면 예각삼각형이에요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「이름은 모두 2개예요.」","mis":"M4-1-u4-X19"}],"explanation":["각으로 한 번, 변으로 한 번 봐요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형.","도윤이 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"세 각이 100°, 30°, 50°인 삼각형의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「이 삼각형은 둔각삼각형이라서 이등변삼각형이기도 해요.」","correct":true,"mis_target":"M4-1-u4-X11"},{"t":"도윤 — 「각으로 보면 둔각삼각형이에요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「이름은 모두 1개예요.」","mis":"M4-1-u4-X19"}],"explanation":["각으로 한 번, 변으로 한 번 봐요.","각으로 → 둔각삼각형, 변으로 → 없음.","예린이 잘못 말했어요."],"asset":null},{"stem":"세 각이 90°, 45°, 45°인 삼각형의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「이 삼각형은 이등변삼각형이라서 다른 이름은 붙일 수 없어요.」","correct":true,"mis_target":"M4-1-u4-X14"},{"t":"예린 — 「각으로 보면 직각삼각형이에요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「이름은 모두 2개예요.」","mis":"M4-1-u4-X19"}],"explanation":["각으로 한 번, 변으로 한 번 봐요.","각으로 → 직각삼각형, 변으로 → 이등변삼각형.","은비가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#1','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',2,'match','auto','세 각과 붙일 수 있는 이름을 알맞게 이으세요(「삼각형」은 줄였어요).','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C8","difficulty":2,"kind":"match","stem":"세 각과 붙일 수 있는 이름을 알맞게 이으세요(「삼각형」은 줄였어요).","pairs":[{"l":"90°, 45°, 45°","r":"직각·이등변"},{"l":"60°, 60°, 60°","r":"예각·이등변·정"},{"l":"100°, 50°, 30°","r":"둔각 하나뿐"}],"mis":"M4-1-u4-X14","explanation":["각으로 이름을 먼저, 그다음 같은 각이 있는지 봐요.","90°, 45°, 45° → 직각·이등변, 60°, 60°, 60° → 예각·이등변·정, 100°, 50°, 30° → 둔각 하나뿐.","같은 두 각이 있으면 이등변삼각형이기도 해요."],"variant_rule":{"alt":[{"stem":"짝을 바꾸었어요. 세 각과 붙일 수 있는 이름을 알맞게 이으세요(「삼각형」은 줄였어요).","pairs":[{"l":"120°, 30°, 30°","r":"둔각·이등변"},{"l":"90°, 60°, 30°","r":"직각 하나뿐"},{"l":"70°, 70°, 40°","r":"예각·이등변"}],"explanation":["각으로 이름을 먼저, 그다음 같은 각이 있는지 봐요.","120°, 30°, 30° → 둔각·이등변, 90°, 60°, 30° → 직각 하나뿐, 70°, 70°, 40° → 예각·이등변.","같은 두 각이 있으면 이등변삼각형이기도 해요."],"asset":null},{"stem":"짝을 바꾸었어요. 세 각과 붙일 수 있는 이름을 알맞게 이으세요(「삼각형」은 줄였어요).","pairs":[{"l":"80°, 50°, 50°","r":"예각·이등변"},{"l":"35°, 55°, 90°","r":"직각 하나뿐"},{"l":"40°, 40°, 100°","r":"둔각·이등변"}],"explanation":["각으로 이름을 먼저, 그다음 같은 각이 있는지 봐요.","80°, 50°, 50° → 예각·이등변, 35°, 55°, 90° → 직각 하나뿐, 40°, 40°, 100° → 둔각·이등변.","같은 두 각이 있으면 이등변삼각형이기도 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#2','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C9',2,'mc','auto','정삼각형은 각의 크기로 보면 어떤 삼각형인가요?',ARRAY['M4-1-u4-X17','M4-1-u4-X15']::text[],true,'{"seq":2,"concept":"M4-1-u4-C9","difficulty":2,"kind":"mc","stem":"정삼각형은 각의 크기로 보면 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"직각삼각형","mis":"M4-1-u4-X17"},{"t":"둔각삼각형","mis":"M4-1-u4-X17"},{"t":"각으로는 이름을 붙일 수 없어요","mis":"M4-1-u4-X15"}],"explanation":["정삼각형은 세 변과 세 각(60°)이 모두 같아요.","세 각이 모두 60° — 모두 예각.","답은 예각삼각형이에요."],"variant_rule":{"alt":[{"stem":"정삼각형은 변의 길이로 보면 어떤 이름을 모두 붙일 수 있나요?","options":[{"t":"정삼각형, 이등변삼각형","correct":true},{"t":"정삼각형 하나뿐이에요","mis":"M4-1-u4-X16"},{"t":"이등변삼각형 하나뿐이에요","mis":"M4-1-u4-X17"},{"t":"예각삼각형, 직각삼각형","mis":"M4-1-u4-X15"}],"explanation":["정삼각형은 세 변과 세 각(60°)이 모두 같아요.","세 변이 같으니 두 변도 같아요.","답은 정삼각형, 이등변삼각형이에요."],"asset":null},{"stem":"이름을 가장 많이 붙일 수 있는 삼각형은 어느 것인가요?","options":[{"t":"정삼각형","correct":true},{"t":"직각삼각형","mis":"M4-1-u4-X14"},{"t":"세 변의 길이가 모두 다른 둔각삼각형","mis":"M4-1-u4-X14"},{"t":"모든 삼각형은 이름이 하나예요","mis":"M4-1-u4-X14"}],"explanation":["정삼각형은 세 변과 세 각(60°)이 모두 같아요.","정삼각형은 예각삼각형·이등변삼각형·정삼각형 — 3개예요.","답은 정삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#3','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',3,'mc','auto','예각삼각형이면서 이등변삼각형은 어느 것인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X14']::text[],true,'{"seq":3,"concept":"M4-1-u4-C8","difficulty":3,"kind":"mc","stem":"예각삼각형이면서 이등변삼각형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u4-X01"},{"t":"㉰","mis":"M4-1-u4-X01"},{"t":"㉱","mis":"M4-1-u4-X14"}],"explanation":["먼저 각으로 예각삼각형인지 봐요.","그다음 같은 길이 표시(크기가 같은 두 각)가 있는지 봐요.","답은 ㉯예요."],"asset":{"type":"geo","items":[{"poly":[[[60.692356039,109.007238521],[137.359022706,109.007238521],[175.692356039,42.611957564]]],"arc":[[[175.692356039,42.611957564],[60.692356039,109.007238521],[137.359022706,109.007238521]],[[60.692356039,109.007238521],[137.359022706,109.007238521],[175.692356039,42.611957564]],[[137.359022706,109.007238521],[175.692356039,42.611957564],[60.692356039,109.007238521]]],"lab":[[[38.0,115.087636996],"30°"],[[150.870920726,132.4105324],"120°"],[[192.304313603,26.0],"30°"]],"tick":[[[60.692356039,109.007238521],[137.359022706,109.007238521],1],[[137.359022706,109.007238521],[175.692356039,42.611957564],1]],"w":230,"h":156},{"poly":[[[16.0,148.098172758],[150.136,148.098172758],[126.84352804,16.0]]],"arc":[[[126.84352804,16.0],[16.0,148.098172758],[150.136,148.098172758]],[[16.0,148.098172758],[150.136,148.098172758],[126.84352804,16.0]],[[150.136,148.098172758],[126.84352804,16.0],[16.0,148.098172758]]],"lab":[[[66.753236074,124.431550101],"50°"],[[116.430044503,119.815517932],"80°"],[[112.349661515,70.091846272],"50°"]],"tick":[[[16.0,148.098172758],[150.136,148.098172758],1],[[150.136,148.098172758],[126.84352804,16.0],1]],"w":166,"h":164},{"poly":[[[16.0,94.793277474],[139.883003153,139.883003153],[184.972728832,16.0]]],"arc":[[[184.972728832