ive=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#4','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',3,'sa','auto','세 변이 모두 6 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"세 변이 모두 6 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["변으로: 정삼각형·이등변삼각형.","각으로: 예각삼각형 (세 각 모두 60°).","모두 3개예요."],"variant_rule":{"alt":[{"stem":"두 변의 길이가 같고 가장 큰 각이 100°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변으로: 이등변삼각형.","각으로: 둔각삼각형 (가장 큰 각 100°).","모두 2개예요."],"asset":null},{"stem":"세 변의 길이가 모두 다르고 가장 큰 각이 90°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 직각삼각형 (가장 큰 각 90°).","모두 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#5','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C9',3,'ox','auto','정삼각형이면서 직각삼각형인 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X17']::text[],true,'{"seq":5,"concept":"M4-1-u4-C9","difficulty":3,"kind":"ox","stem":"정삼각형이면서 직각삼각형인 삼각형이 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"정삼각형의 세 각은 모두 60°라 직각이 없어서","correct":true},{"t":"크게 그리면 직각이 생겨서","mis":"M4-1-u4-X17"}],"mis":"M4-1-u4-X17","explanation":["정삼각형은 60°·60°·60°예요.","직각(90°)이 있을 수 없어요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"이등변삼각형은 모두 정삼각형이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"두 변만 같고 나머지 한 변은 다를 수 있어서","correct":true},{"t":"두 변이 같으면 세 변도 같아서","mis":"M4-1-u4-X17"}],"explanation":["이등변삼각형 가운데 세 변이 모두 같은 것만 정삼각형이에요.","5 cm, 5 cm, 3 cm 처럼 다를 수 있어요.","그래서 틀렸어요."],"asset":null},{"stem":"정삼각형은 이등변삼각형이라고 할 수 있어요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"세 변의 길이가 같으면 두 변의 길이도 같아서","correct":true},{"t":"세 변이 같으면 「두 변」이 같다는 말에 맞지 않아서","mis":"M4-1-u4-X16"}],"explanation":["이등변삼각형은 「두 변의 길이가 같은 삼각형」이에요.","정삼각형은 어느 두 변을 골라도 같아요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#6','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',3,'sa','auto','둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 120°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 120°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["둔각은 하나뿐 — 120°가 아닌 두 각이 크기가 같아요.","(180 − 120) ÷ 2 = 30.","한 각은 30°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 100°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["둔각은 하나뿐 — 100°가 아닌 두 각이 크기가 같아요.","(180 − 100) ÷ 2 = 40.","한 각은 40°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 140°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["둔각은 하나뿐 — 140°가 아닌 두 각이 크기가 같아요.","(180 − 140) ÷ 2 = 20.","한 각은 20°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#7','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C9',3,'sa','auto','이등변삼각형이라고 할 수 있는 것은 모두 몇 개인가요? 숫자로 쓰세요(정삼각형도 생각해요).','{}'::text[],true,'{"seq":7,"concept":"M4-1-u4-C9","difficulty":3,"kind":"sa","stem":"이등변삼각형이라고 할 수 있는 것은 모두 몇 개인가요? 숫자로 쓰세요(정삼각형도 생각해요).","answer":["4"],"explanation":["두 변의 길이가 같으면 이등변삼각형이에요.","정삼각형도 두 변의 길이가 같으니 이등변삼각형이에요 — 정삼각형 1개, 이등변삼각형 3개.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[29.510129589,68.028536457],[111.510129589,68.028536457],[80.760129589,22.830284893]]],"lab":[[[70.510129589,82.028536457],"6 cm"],[[120.014979075,29.183088167],"4 cm"],[[38.0,26.0],"5 cm"]],"w":158,"h":106},{"poly":[[[16.0,73.154551923],[75.04,73.154551923],[98.0,18.761905362]]],"lab":[[[45.52,87.154551923],"3 cm"],[[114.695763074,57.851665735],"3 cm"],[[43.761208823,26.0],"5 cm"]],"w":153,"h":111},{"poly":[[[75.756583362,65.518622587],[126.373867313,65.518622587],[44.373867313,25.80420999]]],"lab":[[[101.065225338,79.518622587],"5 cm"],[[94.896325834,26.0],"9 cm"],[[38.0,63.097572486],"5 cm"]],"w":142,"h":104},{"poly":[[[43.124355653,87.01408311],[125.124355653,87.01408311],[84.124355653,16.0]]],"lab":[[[84.124355653,101.01408311],"6 cm"],[[130.248711306,36.712812921],"6 cm"],[[38.0,36.712812921],"6 cm"]],"w":168,"h":125},{"poly":[[[54.095214688,63.853039829],[136.095214688,63.853039829],[73.954589688,27.983760151]]],"lab":[[[95.095214688,77.853039829],"8 cm"],[[116.522351079,26.0],"7 cm"],[[38.0,31.50946018],"4 cm"]],"w":155,"h":102},{"poly":[[[36.6779998,65.712383075],[118.6779998,65.712383075],[77.6779998,23.884016565]]],"lab":[[[77.6779998,79.712383075],"7 cm"],[[117.3559996,26.0],"5 cm"],[[38.0,26.0],"5 cm"]],"w":155,"h":104}]},"variant_rule":{"alt":[{"stem":"그림을 바꾸었어요. 이등변삼각형이라고 할 수 있는 것은 모두 몇 개인가요? 숫자로 쓰세요(정삼각형도 생각해요).","answer":["5"],"explanation":["두 변의 길이가 같으면 이등변삼각형이에요.","정삼각형도 두 변의 길이가 같으니 이등변삼각형이에요 — 정삼각형 1개, 이등변삼각형 4개.","모두 5개예요."],"asset":{"type":"geo","items":[{"poly":[[[125.124355653,40.0],[43.124355653,40.0],[84.124355653,111.01408311]]],"lab":[[[84.124355653,26.0],"5 cm"],[[38.0,90.301270189],"5 cm"],[[130.248711306,90.301270189],"5 cm"]],"w":168,"h":127},{"poly":[[[54.053026388,98.0],[108.005065374,98.0],[81.029045881,16.0]]],"lab":[[[81.029045881,112.0],"5 cm"],[[124.058091762,47.281712602],"8 cm"],[[38.0,47.281712602],"8 cm"]],"w":162,"h":136},{"poly":[[[58.088215471,71.458553747],[140.088215471,71.458553747],[76.310437693,19.91832614]]],"lab":[[[99.088215471,85.458553747],"6 cm"],[[124.109988748,26.0],"6 cm"],[[38.0,35.364919027],"4 cm"]],"w":162,"h":109},{"poly":[[[78.913612296,82.266006923],[137.485040868,82.266006923],[55.485040868,16.0]]],"lab":[[[108.199326582,96.266006923],"5 cm"],[[112.395703034,29.444563518],"9 cm"],[[38.0,59.456524377],"6 cm"]],"w":153,"h":120},{"poly":[[[75.756583362,65.518622587],[126.373867313,65.518622587],[44.373867313,25.80420999]]],"lab":[[[101.065225338,79.518622587],"5 cm"],[[94.896325834,26.0],"9 cm"],[[38.0,63.097572486],"5 cm"]],"w":142,"h":104},{"poly":[[[16.0,65.723975612],[98.0,65.723975612],[87.75,26.025896314]]],"lab":[[[57.0,79.723975612],"8 cm"],[[123.305441712,38.017829698],"4 cm"],[[40.878529144,26.0],"8 cm"]],"w":161,"h":104}]}},{"stem":"그림을 바꾸었어요. 이등변삼각형이라고 할 수 있는 것은 모두 몇 개인가요? 숫자로 쓰세요(정삼각형도 생각해요).","answer":["5"],"explanation":["두 변의 길이가 같으면 이등변삼각형이에요.","정삼각형도 두 변의 길이가 같으니 이등변삼각형이에요 — 정삼각형 2개, 이등변삼각형 3개.","모두 5개예요."],"asset":{"type":"geo","items":[{"poly":[[[46.555101786,69.593002187],[128.555101786,69.593002187],[78.351020153,20.403248985]]],"lab":[[[87.555101786,83.593002187],"7 cm"],[[122.067346471,26.0],"6 cm"],[[38.0,29.191835052],"5 cm"]],"w":160,"h":108},{"poly":[[[43.124355653,87.01408311],[125.124355653,87.01408311],[84.124355653,16.0]]],"lab":[[[84.124355653,101.01408311],"6 cm"],[[130.248711306,36.712812921],"6 cm"],[[38.0,36.712812921],"6 cm"]],"w":168,"h":125},{"poly":[[[57.844287232,98.0],[100.188905151,98.0],[79.016596191,16.0]]],"lab":[[[79.016596191,112.0],"3 cm"],[[120.033192383,49.142893736],"6 cm"],[[38.0,49.142893736],"6 cm"]],"w":158,"h":136},{"poly":[[[125.124355653,40.0],[43.124355653,40.0],[84.124355653,111.01408311]]],"lab":[[[84.124355653,26.0],"5 cm"],[[38.0,90.301270189],"5 cm"],[[130.248711306,90.301270189],"5 cm"]],"w":168,"h":127},{"poly":[[[69.16999972,97.98359836],[151.16999972,97.98359836],[70.80999972,16.0]]],"lab":[[[110.16999972,111.98359836],"5 cm"],[[130.16799952,38.19359936],"7 cm"],[[38.0,56.351871187],"5 cm"]],"w":168,"h":136},{"poly":[[[52.703637568,98.0],[110.686393625,98.0],[81.695015596,16.0]]],"lab":[[[81.695015596,112.0],"4 cm"],[[125.390031193,46.676479084],"6 cm"],[[38.0,46.676479084],"6 cm"]],"w":163,"h":136}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#8','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C9',4,'essay','teacher','「정삼각형은 이등변삼각형이 아니에요.」라는 말이 맞는지 쓰고, 이등변삼각형의 뜻을 이용하여 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C9","difficulty":4,"kind":"essay","stem":"「정삼각형은 이등변삼각형이 아니에요.」라는 말이 맞는지 쓰고, 이등변삼각형의 뜻을 이용하여 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀리다. 이등변삼각형은 두 변의 길이가 같은 삼각형이다. 정삼각형은 세 변의 길이가 모두 같으므로 어느 두 변을 골라도 길이가 같다. 그래서 정삼각형은 이등변삼각형이라고도 할 수 있다.","scoring_points":["틀리다고 답했는가","이등변삼각형의 뜻(두 변의 길이가 같음)을 썼는가","정삼각형도 두 변의 길이가 같다고 했는가"]},"explanation":["이등변삼각형의 뜻부터.","세 변이 같으면 두 변도 같아요.","정삼각형은 이등변삼각형이기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#9','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',4,'essay','teacher','세 각이 30°, 30°, 120°인 삼각형에 붙일 수 있는 이름을 모두 쓰고, 각각 어떤 잣대로 붙였는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C8","difficulty":4,"kind":"essay","stem":"세 각이 30°, 30°, 120°인 삼각형에 붙일 수 있는 이름을 모두 쓰고, 각각 어떤 잣대로 붙였는지 설명해 보세요.","answer_guide":{"answer":"예: 둔각삼각형, 이등변삼각형이다. 각의 크기로 보면 한 각(120°)이 둔각이라 둔각삼각형이고, 변의 길이로 보면 크기가 같은 두 각이 있어 두 변의 길이가 같으므로 이등변삼각형이다.","scoring_points":["둔각삼각형을 썼는가","이등변삼각형을 썼는가","각과 변 두 잣대로 설명했는가"]},"explanation":["각으로: 120° 둔각 → 둔각삼각형.","변으로: 같은 두 각 → 이등변삼각형.","이름이 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L06_challenge#10','math',4,1,'u4','L06','g4_1_math_u4_L06_challenge','lesson_challenge','M4-1-u4-C8',4,'sa','auto','직각삼각형이면서 이등변삼각형인 삼각형이에요. 직각이 아닌 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C8","difficulty":4,"kind":"sa","stem":"직각삼각형이면서 이등변삼각형인 삼각형이에요. 직각이 아닌 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["직각이 아닌 두 각이 크기가 같아요.","(180 − 90) ÷ 2 = 45.","답은 45°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형에서 크기가 같은 두 각이 각각 25°예요. 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["크기가 같은 두 각은 예각이에요.","180 − 25 − 25 = 130.","답은 130°예요."],"asset":null},{"stem":"예각삼각형이면서 이등변삼각형인 삼각형의 꼭대기 각이 50°예요. 아래쪽 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["아래쪽 두 각이 크기가 같아요.","(180 − 50) ÷ 2 = 65.","답은 65°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#1','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',1,'sa','auto','색종이를 대각선으로 한 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C10","difficulty":1,"kind":"sa","stem":"색종이를 대각선으로 한 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②.","모두 2개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"lab":[[[154.666666667,81.333333333],"①"],[[81.333333333,154.666666667],"②"]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이의 대각선 두 개를 모두 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"lab":[[[118.0,44.666666667],"①"],[[191.333333333,118.0],"②"],[[118.0,191.333333333],"③"],[[44.666666667,118.0],"④"]],"w":236,"h":236}],"tag":false}},{"stem":"색종이 위쪽 변의 가운데 점에서 아래쪽 두 모서리로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③.","모두 3개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[118,8],[8,228]],[[118,8],[228,8],[228,228]],[[118,8],[228,228],[8,228]]],"lab":[[[44.666666667,81.333333333],"①"],[[191.333333333,81.333333333],"②"],[[118.0,154.666666667],"③"]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#2','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',1,'mc','auto','색종이를 대각선으로 한 번 잘랐어요. 생기는 두 조각의 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X20','M4-1-u4-X14']::text[],true,'{"seq":2,"concept":"M4-1-u4-C10","difficulty":1,"kind":"mc","stem":"색종이를 대각선으로 한 번 잘랐어요. 생기는 두 조각의 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"직각삼각형, 세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X14"}],"explanation":["색종이의 모서리 직각이 조각에 그대로 남아요 — 직각삼각형.","정사각형의 두 변은 길이가 같아요 — 이등변삼각형.","답은 「직각삼각형, 이등변삼각형」이에요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이의 대각선 두 개를 모두 잘랐어요. 생기는 네 조각의 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"직각삼각형, 세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X14"}],"explanation":["색종이의 모서리 직각이 조각에 그대로 남아요 — 직각삼각형.","정사각형의 두 변은 길이가 같아요 — 이등변삼각형.","답은 「직각삼각형, 이등변삼각형」이에요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 반으로 접은 뒤 접힌 선을 따라 대각선으로 잘랐어요. 생기는 조각의 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X20"},{"t":"직각삼각형, 세 변의 길이가 모두 다른 삼각형","mis":"M4-1-u4-X14"}],"explanation":["색종이의 모서리 직각이 조각에 그대로 남아요 — 직각삼각형.","정사각형의 두 변은 길이가 같아요 — 이등변삼각형.","답은 「직각삼각형, 이등변삼각형」이에요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#3','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',1,'sa','auto','색종이를 대각선으로 자른 조각이에요. 직각이 아닌 한 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C10","difficulty":1,"kind":"sa","stem":"색종이를 대각선으로 자른 조각이에요. 직각이 아닌 한 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["정사각형의 직각이 대각선으로 반 — 90 ÷ 2 = 45.","또는 (180 − 90) ÷ 2 = 45.","답은 45°예요."],"asset":{"type":"geo","items":[{"poly":[[[16,16],[216,16],[216,216]]],"right":[[[16,16],[216,16],[216,216]]],"arc":[[[216,216],[16,16],[216,16]]],"lab":[[[64,34],"?"]],"w":232,"h":232}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이의 대각선 두 개를 모두 잘랐어요. 색종이 가운데에 모인 한 조각의 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["가운데에 네 조각의 각이 모여 한 바퀴 — 360 ÷ 4 = 90.","조각은 직각삼각형이에요.","답은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 대각선으로 자른 조각 두 개의 각을 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["조각 하나의 세 각의 합은 180°.","180 + 180 = 360.","답은 360°예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#4','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',1,'mc','auto','색종이를 잘라 직각삼각형을 쉽게 만들 수 있는 까닭은 무엇인가요?',ARRAY['M4-1-u4-X18','M4-1-u4-X21']::text[],true,'{"seq":4,"concept":"M4-1-u4-C10","difficulty":1,"kind":"mc","stem":"색종이를 잘라 직각삼각형을 쉽게 만들 수 있는 까닭은 무엇인가요?","options":[{"t":"색종이의 네 모서리가 모두 직각이기 때문이에요","correct":true},{"t":"색종이를 자르면 언제나 직각삼각형만 생기기 때문이에요","mis":"M4-1-u4-X18"},{"t":"색종이가 종이라서 잘 잘리기 때문이에요","mis":"M4-1-u4-X21"},{"t":"색종이의 색이 진하기 때문이에요","mis":"M4-1-u4-X21"}],"explanation":["색종이는 네 각이 모두 직각인 사각형이에요.","모서리의 직각을 살려 자르면 직각삼각형이 생겨요.","그래서 직각삼각형은 쉽게 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 색종이를 잘라 직각삼각형을 쉽게 만들 수 있는 까닭은 무엇인가요?","options":[{"t":"색종이의 네 모서리가 모두 직각이기 때문이에요","correct":true},{"t":"색종이가 넓어서 조각을 많이 만들 수 있기 때문이에요","mis":"M4-1-u4-X18"},{"t":"색종이의 색이 진하기 때문이에요","mis":"M4-1-u4-X21"},{"t":"색종이를 자르면 언제나 직각삼각형만 생기기 때문이에요","mis":"M4-1-u4-X18"}],"explanation":["색종이는 네 각이 모두 직각인 사각형이에요.","모서리의 직각을 살려 자르면 직각삼각형이 생겨요.","그래서 직각삼각형은 쉽게 만들 수 있어요."],"asset":null},{"stem":"보기를 바꾸었어요. 색종이를 잘라 직각삼각형을 쉽게 만들 수 있는 까닭은 무엇인가요?","options":[{"t":"색종이의 네 모서리가 모두 직각이기 때문이에요","correct":true},{"t":"색종이를 자르면 언제나 직각삼각형만 생기기 때문이에요","mis":"M4-1-u4-X18"},{"t":"색종이가 종이라서 잘 잘리기 때문이에요","mis":"M4-1-u4-X21"},{"t":"색종이의 색이 진하기 때문이에요","mis":"M4-1-u4-X21"}],"explanation":["색종이는 네 각이 모두 직각인 사각형이에요.","모서리의 직각을 살려 자르면 직각삼각형이 생겨요.","그래서 직각삼각형은 쉽게 만들 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#5','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',2,'mc','auto','친구가 색종이를 잘랐어요. 조각은 모두 삼각형이고 예각·직각·둔각삼각형이 다 있지만 색종이 가운데가 잘리지 않고 남았어요. 무엇이 잘못되었나요?',ARRAY['M4-1-u4-X18']::text[],true,'{"seq":5,"concept":"M4-1-u4-C10","difficulty":2,"kind":"mc","stem":"친구가 색종이를 잘랐어요. 조각은 모두 삼각형이고 예각·직각·둔각삼각형이 다 있지만 색종이 가운데가 잘리지 않고 남았어요. 무엇이 잘못되었나요?","options":[{"t":"색종이를 남김없이 모두 잘라야 하는데 그러지 않았어요","correct":true},{"t":"잘못된 것이 없어요 — 조건을 다 지켰어요","mis":"M4-1-u4-X18"},{"t":"삼각형의 수가 너무 적어요","mis":"M4-1-u4-X18"},{"t":"둔각삼각형을 하나 더 만들어야 해요","mis":"M4-1-u4-X18"}],"explanation":["조건 세 가지: 남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두.","하나라도 빠지면 조건을 다 지킨 것이 아니에요.","「색종이를 남김없이 모두 잘라야 하는데 그러지 않았어요」예요."],"variant_rule":{"alt":[{"stem":"친구가 색종이를 잘랐어요. 색종이를 남김없이 잘랐고 예각·직각·둔각삼각형이 다 있지만 사각형 조각이 하나 있어요. 무엇이 잘못되었나요?","options":[{"t":"잘린 조각이 모두 삼각형이어야 하는데 사각형이 있어요","correct":true},{"t":"잘못된 것이 없어요 — 조건을 다 지켰어요","mis":"M4-1-u4-X18"},{"t":"삼각형의 수가 너무 적어요","mis":"M4-1-u4-X18"},{"t":"둔각삼각형을 하나 더 만들어야 해요","mis":"M4-1-u4-X18"}],"explanation":["조건 세 가지: 남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두.","하나라도 빠지면 조건을 다 지킨 것이 아니에요.","「잘린 조각이 모두 삼각형이어야 하는데 사각형이 있어요」예요."],"asset":null},{"stem":"친구가 색종이를 잘랐어요. 색종이를 남김없이 잘랐고 조각은 모두 삼각형이지만 모두 직각삼각형이에요. 무엇이 잘못되었나요?","options":[{"t":"예각삼각형과 둔각삼각형이 없어요","correct":true},{"t":"잘못된 것이 없어요 — 조건을 다 지켰어요","mis":"M4-1-u4-X18"},{"t":"삼각형의 수가 너무 적어요","mis":"M4-1-u4-X18"},{"t":"조각을 다시 모으면 색종이가 되지 않아요","mis":"M4-1-u4-X18"}],"explanation":["조건 세 가지: 남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두.","하나라도 빠지면 조건을 다 지킨 것이 아니에요.","「예각삼각형과 둔각삼각형이 없어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_code