INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#8','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',2,'mc','auto','두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?',ARRAY['M4-1-u4-X18','M4-1-u4-X19']::text[],true,'{"seq":8,"concept":"M4-1-u4-C10","difficulty":2,"kind":"mc","stem":"두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉮는 둔각삼각형이 없어요.","조건을 모두 만족한 것은 ㉯예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[8,96],[96,228]],[[8,96],[8,8],[228,8]],[[8,96],[228,8],[96,228]],[[96,228],[228,8],[228,228]]],"right":[[[96,228],[8,228],[8,96]],[[8,96],[8,8],[228,8]],[[228,8],[228,228],[96,228]]],"w":236,"h":236},{"poly":[[[8,228],[8,8],[96,52]],[[8,8],[228,8],[96,52]],[[228,8],[228,228],[96,52]],[[228,228],[8,228],[96,52]]],"right":[[[8,8],[96,52],[8,228]]],"w":236,"h":236}]},"variant_rule":{"alt":[{"stem":"그림을 바꾸었어요. 두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉮는 사각형 조각이 있어요.","조건을 모두 만족한 것은 ㉯예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[118,8],[118,228],[8,228]],[[118,8],[228,8],[228,228]],[[118,8],[228,228],[118,228]]],"right":[[[118,8],[228,8],[228,228]],[[228,228],[118,228],[118,8]]],"w":236,"h":236},{"poly":[[[52,184],[8,8],[228,8]],[[8,228],[228,8],[228,228]],[[8,228],[8,8],[52,184]]],"right":[[[228,8],[228,228],[8,228]]],"w":236,"h":236}]}},{"stem":"그림을 바꾸었어요. 두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉯는 직각삼각형만 있어요.","조건을 모두 만족한 것은 ㉮예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[8,8],[52,96]],[[8,8],[228,8],[52,96]],[[228,228],[8,228],[52,96]],[[228,8],[228,228],[52,96]]],"right":[[[228,8],[52,96],[8,8]]],"w":236,"h":236},{"poly":[[[228,8],[228,228],[8,228]],[[228,8],[8,228],[8,8]]],"right":[[[228,8],[228,228],[8,228]],[[8,228],[8,8],[228,8]]],"w":236,"h":236}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#9','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',2,'ox','auto','잘린 조각을 다시 모으면 원래 색종이가 돼요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X18']::text[],true,'{"seq":9,"concept":"M4-1-u4-C10","difficulty":2,"kind":"ox","stem":"잘린 조각을 다시 모으면 원래 색종이가 돼요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"남김없이 잘랐으니 조각을 모두 모으면 처음 색종이라서","correct":true},{"t":"자르면 색종이가 줄어들어서","mis":"M4-1-u4-X18"}],"mis":"M4-1-u4-X18","explanation":["조각은 색종이를 나눈 것이에요.","모두 모으면 처음 모양이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"조건에 맞게 자르는 방법은 하나뿐이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"가르는 자리를 바꾸면 여러 가지로 자를 수 있어서","correct":true},{"t":"정해진 선을 따라야만 해서","mis":"M4-1-u4-X18"}],"explanation":["조건 세 가지만 지키면 어떻게 잘라도 돼요.","자르는 방법은 여러 가지예요.","그래서 틀렸어요."],"asset":null},{"stem":"색종이를 대각선으로 한 번만 잘라도 예각·직각·둔각삼각형이 모두 생겨요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"대각선으로 한 번 자르면 직각삼각형 두 개만 생겨서","correct":true},{"t":"대각선은 색종이를 셋으로 나누어서","mis":"M4-1-u4-X20"}],"explanation":["대각선 조각은 직각이등변삼각형이에요.","예각·둔각삼각형이 없어요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_basic#10','math',4,1,'u4','L07','g4_1_math_u4_L07_basic','lesson_basic','M4-1-u4-C10',3,'error','auto','색종이 자르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u4-X20','M4-1-u4-X19']::text[],true,'{"seq":10,"concept":"M4-1-u4-C10","difficulty":3,"kind":"error","stem":"색종이 자르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「대각선으로 자른 조각의 모서리 각은 90°예요.」","correct":true,"mis_target":"M4-1-u4-X20"},{"t":"준서 — 「모서리의 직각을 살리면 직각삼각형이 생겨요.」","mis":"M4-1-u4-X19"},{"t":"지호 — 「자르기 전에 선을 먼저 그어 봐요.」","mis":"M4-1-u4-X19"}],"explanation":["조건과 조각의 모양을 다시 봐요.","대각선 조각의 직각이 아닌 각은 45°예요.","도윤이 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"보기를 바꾸었어요. 색종이 자르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「조각이 모두 삼각형이면 가운데가 남아도 괜찮아요.」","correct":true,"mis_target":"M4-1-u4-X18"},{"t":"도윤 — 「모서리의 직각을 살리면 직각삼각형이 생겨요.」","mis":"M4-1-u4-X19"},{"t":"하람 — 「자르기 전에 선을 먼저 그어 봐요.」","mis":"M4-1-u4-X19"}],"explanation":["조건과 조각의 모양을 다시 봐요.","색종이를 남김없이 잘라야 해요.","예린이 잘못 말했어요."],"asset":null},{"stem":"보기를 바꾸었어요. 색종이 자르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「대각선 두 개를 자르면 조각이 2개예요.」","correct":true,"mis_target":"M4-1-u4-X20"},{"t":"예린 — 「모서리의 직각을 살리면 직각삼각형이 생겨요.」","mis":"M4-1-u4-X19"},{"t":"나래 — 「자르기 전에 선을 먼저 그어 봐요.」","mis":"M4-1-u4-X19"}],"explanation":["조건과 조각의 모양을 다시 봐요.","대각선 두 개면 조각이 4개예요.","은비가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
