INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#4','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',3,'sa','auto','색종이를 잘랐더니 조각이 모두 삼각형이고 4개였어요. 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C10","difficulty":3,"kind":"sa","stem":"색종이를 잘랐더니 조각이 모두 삼각형이고 4개였어요. 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","180 × 4 = 720.","모두 720°예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[52,96]],[[228,8],[228,228],[52,96]],[[228,228],[8,228],[52,96]],[[8,228],[8,8],[52,96]]],"lab":[[[96.0,37.333333333],"①"],[[169.333333333,110.666666667],"②"],[[96.0,184.0],"③"],[[22.666666667,110.666666667],"④"]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이를 잘랐더니 조각이 모두 삼각형이고 3개였어요. 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","180 × 3 = 540.","모두 540°예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,228],[8,228]],[[8,8],[228,8],[74,74]],[[74,74],[228,8],[228,228]]],"lab":[[[81.333333333,154.666666667],"①"],[[103.333333333,30.0],"②"],[[176.666666667,103.333333333],"③"]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 잘랐더니 조각이 모두 삼각형이고 2개였어요. 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","180 × 2 = 360.","모두 360°예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"lab":[[[154.666666667,81.333333333],"①"],[[81.333333333,154.666666667],"②"]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EX