INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#6','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',3,'mc','auto','두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?',ARRAY['M4-1-u4-X18','M4-1-u4-X19']::text[],true,'{"seq":6,"concept":"M4-1-u4-C10","difficulty":3,"kind":"mc","stem":"두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉯는 둔각삼각형이 없어요.","조건을 모두 만족한 것은 ㉮예요."],"asset":{"type":"geo","items":[{"poly":[[[96,96],[8,228],[8,8]],[[228,228],[8,8],[228,8]],[[228,228],[8,228],[96,96]]],"right":[[[8,8],[228,8],[228,228]]],"w":236,"h":236},{"poly":[[[8,228],[8,118],[228,228]],[[8,118],[8,8],[228,8]],[[8,118],[228,8],[228,228]]],"right":[[[228,228],[8,228],[8,118]],[[8,118],[8,8],[228,8]]],"w":236,"h":236}]},"variant_rule":{"alt":[{"stem":"그림을 바꾸었어요. 두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉯는 직각삼각형만 있어요.","조건을 모두 만족한 것은 ㉮예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[162,162]],[[162,162],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"right":[[[228,228],[8,228],[8,8]]],"w":236,"h":236},{"poly":[[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]],[[8,8],[228,8],[118,118]]],"right":[[[228,228],[118,118],[228,8]],[[8,228],[118,118],[228,228]],[[8,8],[118,118],[8,228]],[[228,8],[118,118],[8,8]]],"w":236,"h":236}]}},{"stem":"그림을 바꾸었어요. 두 친구가 색종이를 잘랐어요. 조건(남김없이 · 모두 삼각형 · 예각·직각·둔각삼각형 모두)을 모두 만족한 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u4-X18"},{"t":"둘 다 만족해요","mis":"M4-1-u4-X18"},{"t":"둘 다 만족하지 못해요","mis":"M4-1-u4-X19"}],"explanation":["조건 세 가지를 하나씩 확인해요.","㉯는 둔각삼각형이 없어요.","조건을 모두 만족한 것은 ㉮예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[8,8],[52,96]],[[228,8],[228,228],[52,96]],[[8,8],[228,8],[52,96]],[[228,228],[8,228],[52,96]]],"right":[[[228,8],[52,96],[8,8]]],"w":236,"h":236},{"poly":[[[228,8],[228,118],[8,8]],[[228,118],[228,228],[8,228]],[[228,118],[8,228],[8,8]]],"right":[[[8,8],[228,8],[228,118]],[[228,118],[228,228],[8,228]]],"w":236,"h":236}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#7','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',3,'ox','auto','자르기 전에 색종이에 선을 먼저 그어 보면 조건을 확인하기 쉬워요. 맞으면 O, 틀리면 X를 고르세요.',ARRAY['M4-1-u4-X18']::text[],true,'{"seq":7,"concept":"M4-1-u4-C10","difficulty":3,"kind":"ox","stem":"자르기 전에 색종이에 선을 먼저 그어 보면 조건을 확인하기 쉬워요. 맞으면 O, 틀리면 X를 고르세요.","answer":"O","reason_options":[{"t":"자르기 전에 조각의 모양을 미리 볼 수 있어서","correct":true},{"t":"선을 그으면 색종이가 더 튼튼해져서","mis":"M4-1-u4-X18"}],"mis":"M4-1-u4-X18","explanation":["선을 그어 계획을 세워요.","조건을 미리 확인할 수 있어요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"색종이를 대각선으로 한 번만 잘라도 예각·직각·둔각삼각형이 모두 생겨요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"대각선으로 한 번 자르면 직각삼각형 두 개만 생겨서","correct":true},{"t":"대각선은 색종이를 셋으로 나누어서","mis":"M4-1-u4-X20"}],"explanation":["대각선 조각은 직각이등변삼각형이에요.","예각·둔각삼각형이 없어요.","그래서 틀렸어요."],"asset":null},{"stem":"조건에 맞게 자르는 방법은 하나뿐이에요. 맞으면 O, 틀리면 X를 고르세요.","answer":"X","reason_options":[{"t":"가르는 자리를 바꾸면 여러 가지로 자를 수 있어서","correct":true},{"t":"정해진 선을 따라야만 해서","mis":"M4-1-u4-X18"}],"explanation":["조건 세 가지만 지키면 어떻게 잘라도 돼요.","자르는 방법은 여러 가지예요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#8','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',4,'essay','teacher','색종이 한 장을 잘라 예각삼각형·직각삼각형·둔각삼각형을 모두 만들려고 해요. 지켜야 할 조건 세 가지를 쓰고, 직각삼각형을 쉽게 만드는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u4-C10","difficulty":4,"kind":"essay","stem":"색종이 한 장을 잘라 예각삼각형·직각삼각형·둔각삼각형을 모두 만들려고 해요. 지켜야 할 조건 세 가지를 쓰고, 직각삼각형을 쉽게 만드는 방법을 설명해 보세요.","answer_guide":{"answer":"예: ① 색종이를 남김없이 모두 자른다 ② 잘린 조각이 모두 삼각형이어야 한다 ③ 예각·직각·둔각삼각형이 모두 있어야 한다. 색종이의 네 모서리가 직각이므로 모서리의 직각을 살려 자르면 직각삼각형이 쉽게 생긴다.","scoring_points":["조건 세 가지를 모두 썼는가","색종이 모서리가 직각이라고 했는가","모서리를 살려 직각삼각형을 만든다고 했는가"]},"explanation":["남김없이 · 모두 삼각형 · 세 종류.","모서리는 직각.","모서리를 살려 직각삼각형."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#9','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',4,'essay','teacher','색종이를 대각선으로 한 번 잘랐더니 직각삼각형 두 개만 생겼어요. 예각삼각형과 둔각삼각형도 생기게 하려면 어떻게 더 자르면 좋을지 한 가지 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u4-C10","difficulty":4,"kind":"essay","stem":"색종이를 대각선으로 한 번 잘랐더니 직각삼각형 두 개만 생겼어요. 예각삼각형과 둔각삼각형도 생기게 하려면 어떻게 더 자르면 좋을지 한 가지 방법을 설명해 보세요.","answer_guide":{"answer":"예: 직각삼각형 하나를 직각인 꼭짓점에서 마주 보는 긴 변(대각선) 위의 한 점까지 곧게 자르되, 그 점을 대각선의 가운데가 아닌 곳으로 정한다. 그러면 한쪽은 둔각삼각형, 다른 쪽은 예각삼각형이 되어 처음의 직각삼각형과 함께 세 종류가 모두 생긴다.","scoring_points":["직각삼각형 하나를 한 번 더 자른다고 했는가","직각인 꼭짓점에서 대각선 위 가운데가 아닌 점으로 자른다고 했는가","예각삼각형과 둔각삼각형이 생긴다고 했는가"]},"explanation":["한 조각을 더 갈라요.","가르는 자리를 옮기면 모양이 달라져요.","예각·둔각삼각형이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_L07_challenge#10','math',4,1,'u4','L07','g4_1_math_u4_L07_challenge','lesson_challenge','M4-1-u4-C10',4,'sa','auto','색종이를 잘라 삼각형 조각 4개를 만들었어요. 그중 1개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C10","difficulty":4,"kind":"sa","stem":"색종이를 잘라 삼각형 조각 4개를 만들었어요. 그중 1개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 4 + 1 = 5.","180 × 5 = 900 — 900°예요."],"variant_rule":{"alt":[{"stem":"색종이를 잘라 삼각형 조각 3개를 만들었어요. 그중 2개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 3 + 2 = 5.","180 × 5 = 900 — 900°예요."],"asset":null},{"stem":"색종이를 잘라 삼각형 조각 4개를 만들었어요. 그중 2개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["1080"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 4 + 2 = 6.","180 × 6 = 1080 — 1080°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#1','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C1',1,'sa','auto','삼각형의 두 각이 80°, 20°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형의 두 각이 80°, 20°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 80 − 20 = 80.","나머지 한 각은 80°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,115.647611747],[307.350125693,115.647611747],[33.570562514,16.0]]],"arc":[[[33.570562514,16.0],[16.0,115.647611747],[307.350125693,115.647611747]],[[16.0,115.647611747],[307.350125693,115.647611747],[33.570562514,16.0]],[[307.350125693,115.647611747],[33.570562514,16.0],[16.0,115.647611747]]],"lab":[[[49.705955497,87.364956921],"80°"],[[330.486072111,119.727103325],"20°"],[[55.570562514,54.105117767],"?"]],"tick":[[[16.0,115.647611747],[307.350125693,115.647611747],1],[[307.350125693,115.647611747],[33.570562514,16.0],1]],"w":368,"h":144}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 85°, 30°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 85 − 30 = 65.","나머지 한 각은 65°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,116.904653577],[199.6,116.904653577],[24.828013285,16.0]]],"arc":[[[24.828013285,16.0],[16.0,116.904653577],[199.6,116.904653577]],[[16.0,116.904653577],[199.6,116.904653577],[24.828013285,16.0]],[[199.6,116.904653577],[24.828013285,16.0],[16.0,116.904653577]]],"lab":[[[48.44020282,87.178684442],"85°"],[[131.417996337,98.635340757],"30°"],[[45.144952267,55.02847666],"?"]],"w":216,"h":133}],"tag":false}},{"stem":"삼각형의 두 각이 85°, 20°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 85 − 20 = 75.","나머지 한 각은 75°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,111.157623409],[285.7686349,111.157623409],[24.325213296,16.0]]],"arc":[[[24.325213296,16.0],[16.0,111.157623409],[285.7686349,111.157623409]],[[16.0,111.157623409],[285.7686349,111.157623409],[24.325213296,16.0]],[[285.7686349,111.157623409],[24.325213296,16.0],[16.0,111.157623409]]],"lab":[[[48.44020282,81.431654274],"85°"],[[308.904581319,115.237114986],"20°"],[[47.966396064,53.109223616],"?"]],"w":347,"h":139}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#2','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C2',1,'mc','auto','세 각이 55°, 80°, 45°인 삼각형이에요. 어떤 삼각형인가요?',ARRAY['M4-1-u4-X21','M4-1-u4-X11']::text[],true,'{"seq":2,"concept":"M4-1-u4-C2","difficulty":1,"kind":"mc","stem":"세 각이 55°, 80°, 45°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 80° — 예각.","예각삼각형이에요."],"variant_rule":{"alt":[{"stem":"세 각이 20°, 60°, 100°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 100° — 둔각.","둔각삼각형이에요."],"asset":null},{"stem":"세 각이 55°, 90°, 35°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#3','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C6',1,'sa','auto','이등변삼각형에서 크기가 같은 두 각이 각각 45°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C6","difficulty":1,"kind":"sa","stem":"이등변삼각형에서 크기가 같은 두 각이 각각 45°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["세 각의 합은 180°예요.","180 − 45 − 45 = 90.","나머지 한 각은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,103.48],[190.96,103.48],[103.48,16.0]]],"arc":[[[103.48,16.0],[16.0,103.48],[190.96,103.48]],[[16.0,103.48],[190.96,103.48],[103.48,16.0]],[[190.96,103.48],[103.48,16.0],[16.0,103.48]]],"lab":[[[67.737253821,82.049727788],"45°"],[[139.222746179,82.049727788],"45°"],[[103.48,60.0],"?"]],"tick":[[[190.96,103.48],[103.48,16.0],1],[[103.48,16.0],[16.0,103.48],1]],"w":207,"h":119}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 70°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["세 각의 합은 180°예요.","180 − 70 − 70 = 40.","나머지 한 각은 40°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,178.0],[133.926355902,178.0],[74.963177951,16.0]]],"arc":[[[74.963177951,16.0],[16.0,178.0],[133.926355902,178.0]],[[16.0,178.0],[133.926355902,178.0],[74.963177951,16.0]],[[133.926355902,178.0],[74.963177951,16.0],[16.0,178.0]]],"lab":[[[52.042689949,152.762636801],"70°"],[[97.883665954,152.762636801],"70°"],[[74.963177951,72.0],"?"]],"tick":[[[133.926355902,178.0],[74.963177951,16.0],1],[[74.963177951,16.0],[16.0,178.0],1]],"w":150,"h":194}],"tag":false}},{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["세 각의 합은 180°예요.","180 − 25 − 25 = 130.","나머지 한 각은 130°예요."],"asset":{"type":"geo","items":[{"poly":[[[60.935981201,60.05600145],[249.892781201,60.05600145],[155.414381201,16.0]]],"arc":[[[155.414381201,16.0],[60.935981201,60.05600145],[249.892781201,60.05600145]],[[60.935981201,60.05600145],[249.892781201,60.05600145],[155.414381201,16.0]],[[249.892781201,60.05600145],[155.414381201,16.0],[60.935981201,60.05600145]]],"lab":[[[38.0,65.140786065],"25°"],[[272.828762401,65.140786065],"25°"],[[155.414381201,50.0],"?"]],"tick":[[[249.892781201,60.05600145],[155.414381201,16.0],1],[[155.414381201,16.0],[60.935981201,60.05600145],1]],"w":311,"h":89}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#4','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C5',1,'sa','auto','세 변의 길이의 합이 12 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C5","difficulty":1,"kind":"sa","stem":"세 변의 길이의 합이 12 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","12 ÷ 3 = 4.","한 변은 4 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 57 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","57 ÷ 3 = 19.","한 변은 19 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 24 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","24 ÷ 3 = 8.","한 변은 8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#5','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C7',1,'sa','auto','정삼각형에서 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C7","difficulty":1,"kind":"sa","stem":"정삼각형에서 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["정삼각형은 세 각이 모두 60°예요.","한 각은 60° — 60 + 60 = 120.","답은 120°예요."],"variant_rule":{"alt":[{"stem":"정삼각형에서 세 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["정삼각형은 세 각이 모두 60°예요.","어느 삼각형이든 세 각의 합은 180°.","답은 180°예요."],"asset":null},{"stem":"정삼각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정삼각형은 세 각이 모두 60°예요.","180 ÷ 3 = 60.","답은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
