INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#7','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C8',1,'mc','auto','세 각이 120°, 25°, 35°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X21','M4-1-u4-X11']::text[],true,'{"seq":7,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"세 각이 120°, 25°, 35°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"둔각삼각형 하나뿐이에요","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 둔각삼각형, 변으로 → 붙일 이름 없음","답은 「둔각삼각형 하나뿐이에요」예요."],"variant_rule":{"alt":[{"stem":"세 각이 40°, 60°, 80°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형 하나뿐이에요","correct":true},{"t":"직각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 붙일 이름 없음","답은 「예각삼각형 하나뿐이에요」예요."],"asset":null},{"stem":"세 각이 70°, 55°, 55°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형","답은 「예각삼각형, 이등변삼각형」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#8','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C10',1,'sa','auto','색종이를 대각선으로 한 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u4-C10","difficulty":1,"kind":"sa","stem":"색종이를 대각선으로 한 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②.","모두 2개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"lab":[[[154.666666667,81.333333333],"①"],[[81.333333333,154.666666667],"②"]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이의 대각선 두 개를 모두 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"lab":[[[118.0,44.666666667],"①"],[[191.333333333,118.0],"②"],[[118.0,191.333333333],"③"],[[44.666666667,118.0],"④"]],"w":236,"h":236}],"tag":false}},{"stem":"색종이 위쪽 변의 가운데 점에서 아래쪽 두 모서리로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③.","모두 3개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[118,8],[8,228]],[[118,8],[228,8],[228,228]],[[118,8],[228,228],[8,228]]],"lab":[[[44.666666667,81.333333333],"①"],[[191.333333333,81.333333333],"②"],[[118.0,154.666666667],"③"]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#9','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 꼭대기 각이 120°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 120°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["아래쪽 두 각의 합: 180 − 120 = 60.","두 각의 크기가 같으니 60 ÷ 2 = 30.","한 각은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,70.547129673],[204.9568,70.547129673],[110.4784,16.0]]],"arc":[[[110.4784,16.0],[16.0,70.547129673],[204.9568,70.547129673]],[[204.9568,70.547129673],[110.4784,16.0],[16.0,70.547129673]]],"lab":[[[70.091846272,56.053263147],"?"],[[110.4784,50.0],"120°"]],"tick":[[[204.9568,70.547129673],[110.4784,16.0],1],[[110.4784,16.0],[16.0,70.547129673],1]],"w":221,"h":87}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 80°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["아래쪽 두 각의 합: 180 − 80 = 100.","두 각의 크기가 같으니 100 ÷ 2 = 50.","한 각은 50°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,112.532041],[178.0,112.532041],[97.0,16.0]]],"arc":[[[97.0,16.0],[16.0,112.532041],[178.0,112.532041]],[[178.0,112.532041],[97.0,16.0],[16.0,112.532041]]],"lab":[[[66.753236074,88.865418343],"?"],[[97.0,60.0],"80°"]],"tick":[[[178.0,112.532041],[97.0,16.0],1],[[97.0,16.0],[16.0,112.532041],1]],"w":194,"h":129}],"tag":false}},{"stem":"이등변삼각형의 꼭대기 각이 100°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["아래쪽 두 각의 합: 180 − 100 = 80.","두 각의 크기가 같으니 80 ÷ 2 = 40.","한 각은 40°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,95.276790594],[204.9568,95.276790594],[110.4784,16.0]]],"arc":[[[110.4784,16.0],[16.0,95.276790594],[204.9568,95.276790594]],[[204.9568,95.276790594],[110.4784,16.0],[16.0,95.2767