INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#10','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C4',2,'sa','auto','세 변의 길이의 합이 30 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C4","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 30 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["길이가 같은 변이 두 개예요.","30 − 8 − 8 = 14.","나머지 한 변은 14 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,69.389477708],[186.0,69.389477708],[101.0,22.360394218]]],"tick":[[[186.0,69.389477708],[101.0,22.360394218],1],[[101.0,22.360394218],[16.0,69.389477708],1]],"lab":[[[101.0,83.389477708],"?"],[[154.496470856,26.0],"8 cm"],[[47.503529144,26.0],"8 cm"]],"w":202,"h":107}],"tag":false},"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 43 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 11 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["길이가 같은 변이 두 개예요.","43 − 11 − 11 = 21.","나머지 한 변은 21 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,57.755948195],[186.0,57.755948195],[101.0,31.21393512]]],"tick":[[[186.0,57.755948195],[101.0,31.21393512],1],[[101.0,31.21393512],[16.0,57.755948195],1]],"lab":[[[101.0,71.755948195],"?"],[[149.272088978,26.0],"11 cm"],[[52.727911022,26.0],"11 cm"]],"w":202,"h":96}],"tag":false}},{"stem":"세 변의 길이의 합이 26 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 10 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["길이가 같은 변이 두 개예요.","26 − 10 − 10 = 6.","나머지 한 변은 6 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[41.003885483,186.0],[147.928938829,186.0],[94.466412156,16.0]]],"tick":[[[147.928938829,186.0],[94.466412156,16.0],1],[[94.466412156,16.0],[41.003885483,186.0],1]],"lab":[[[94.466412156,200.0],"?"],[[150.932824312,91.648728312],"10 cm"],[[38.0,91.648728312],"10 cm"]],"w":189,"h":224}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#11','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C2',2,'mc','auto','삼각형의 두 각이 75°, 15°예요. 이 삼각형은 어떤 삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X04']::text[],true,'{"seq":11,"concept":"M4-1-u4-C2","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 75°, 15°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"}],"explanation":["나머지 한 각부터 구해요: 180 − 75 − 15 = 90.","세 각 75°, 15°, 90° — 가장 큰 각은 90°.","직각삼각형이에요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 80°, 25°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 80 − 25 = 75.","세 각 80°, 25°, 75° — 가장 큰 각은 80°.","예각삼각형이에요."],"asset":null},{"stem":"삼각형의 두 각이 80°, 45°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 80 − 45 = 55.","세 각 80°, 45°, 55° — 가장 큰 각은 80°.","예각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
