INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#13','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C6',2,'mc','auto','두 각의 크기가 105°, 20°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X06','M4-1-u4-X21']::text[],true,'{"seq":13,"concept":"M4-1-u4-C6","difficulty":2,"kind":"mc","stem":"두 각의 크기가 105°, 20°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 55°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 105 − 20 = 55 — 세 각 105°, 20°, 55°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"variant_rule":{"alt":[{"stem":"두 각의 크기가 65°, 100°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 15°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 65 − 100 = 15 — 세 각 65°, 100°, 15°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"asset":null},{"stem":"두 각의 크기가 60°, 100°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 20°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 60 − 100 = 20 — 세 각 60°, 100°, 20°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload