INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#15','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C8',2,'sa','auto','세 각이 160°, 10°, 10°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u4-C8","difficulty":2,"kind":"sa","stem":"세 각이 160°, 10°, 10°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각으로 이름 하나: 둔각삼각형.","변으로: 이등변삼각형.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"세 각이 65°, 90°, 25°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각으로 이름 하나: 직각삼각형.","변으로: 붙일 이름 없음(세 변의 길이가 모두 달라요).","모두 1개예요."],"asset":null},{"stem":"세 각이 55°, 55°, 70°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각으로 이름 하나: 예각삼각형.","변으로: 이등변삼각형.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#16','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C10',2,'mc','auto','색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 몇 번인가요?',ARRAY['M4-1-u4-X20','M4-1-u4-X01']::text[],true,'{"seq":16,"concept":"M4-1-u4-C10","difficulty":2,"kind":"mc","stem":"색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 몇 번인가요?","options":[{"t":"②번","correct":true},{"t":"①번","mis":"M4-1-u4-X20"},{"t":"③번","mis":"M4-1-u4-X01"},{"t":"④번","mis":"M4-1-u4-X01"}],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 둔각, ③ 예각, ④ 예각.","둔각삼각형 조각은 ②번이에요."],"asset":{"type":"geo","items":[{"poly":[[[228,8],[228,228],[140,184]],[[228,228],[8,228],[140,184]],[[8,8],[228,8],[140,184]],[[8,228],[8,8],[140,184]]],"lab":[[[198.666666667,140.0],"①"],[[125.333333333,213.333333333],"②"],[[125.333333333,66.666666667],"③"],[[52.0,140.0],"④"]],"right":[[[228,228],[140,184],[228,8]]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이를 그림처럼 잘랐어요. 직각삼각형 조각은 몇 번인가요?","options":[{"t":"①번","correct":true},{"t":"②번","mis":"M4-1-u4-X01"},{"t":"③번","mis":"M4-1-u4-X01"},{"t":"그런 조각이 없어요","mis":"M4-1-u4-X18"}],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 둔각, ③ 예각.","직각삼각형 조각은 ①번이에요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[228,8],[228,228]],[[8,228],[8,8],[96,140]],[[96,140],[8,8],[228,8]]],"lab":[[[154.666666667,154.666666667],"①"],[[37.333333333,125.333333333],"②"],[[110.666666667,52.0],"③"]],"right":[[[228,8],[228,228],[8,228]]],"w":236,"h":236}],"tag":false}},{"stem":"그림을 바꾸었어요. 색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 몇 번인가요?","options":[{"t":"①번","correct":true},{"t":"②번","mis":"M4-1-u4-X01"},{"t":"③번","mis":"M4-1-u4-X20"},{"t":"그런 조각이 없어요","mis":"M4-1-u4-X18"}],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 둔각, ② 예각, ③ 직각.","둔각삼각형 조각은 ①번이에요."],"asset":{"type":"geo","items":[{"poly":[[[74,162],[228,228],[8,228]],[[2