INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#17','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C4',3,'sa','auto','이등변삼각형의 두 변의 길이가 4 cm, 12 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-1-u4-C4","difficulty":3,"kind":"sa","stem":"이등변삼각형의 두 변의 길이가 4 cm, 12 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["같은 두 변이 4 cm이면 4 cm, 4 cm, 12 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 12 cm — 12 cm, 12 cm, 4 cm.","12 + 12 + 4 = 28 — 28 cm예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 두 변의 길이가 8 cm, 3 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 8 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 8 cm — 8 cm, 8 cm, 3 cm.","8 + 8 + 3 = 19 — 19 cm예요."],"asset":null},{"stem":"이등변삼각형의 두 변의 길이가 2 cm, 8 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["같은 두 변이 2 cm이면 2 cm, 2 cm, 8 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 8 cm — 8 cm, 8 cm, 2 cm.","8 + 8 + 2 = 18 — 18 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#18','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C6',3,'sa','auto','꼭대기 각이 130°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"꼭대기 각이 130°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["155"],"explanation":["아래쪽 한 각: (180 − 130) ÷ 2 = 25.","그 각과 ?가 일직선을 이루어요: 180 − 25 = 155.","?는 155°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,59.194064242],[166.0,59.194064242],[91.0,24.22098988]]],"seg":[[[166.0,59.194064242],[236.0,59.194064242]]],"arc":[[[91.0,24.22098988],[16.0,59.194064242],[166.0,59.194064242]],[[236.0,59.194064242],[166.0,59.194064242],[91.0,24.22098988]],[[16.0,59.194064242],[91.0,24.22098988],[166.0,59.194064242]]],"tick":[[[16.0,59.194064242],[91.0,24.22098988],1],[[166.0,59.194064242],[91.0,24.22098988],1]],"lab":[[[91.0,72.22098988],"130°"],[[173.358946874,26.0],"?"]],"w":252,"h":96}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭대기 각이 80°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["아래쪽 한 각: (180 − 80) ÷ 2 = 50.","그 각과 ?가 일직선을 이루어요: 180 − 50 = 130.","?는 130°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,105.381519445],[166.0,105.381519445],[91.0,16.0]]],"seg":[[[166.0,105.381519445],[236.0,105.381519445]]],"arc":[[[91.0,16.0],[16.0,105.381519445],[166.0,105.381519445]],[[236.0,105.381519445],[166.0,105.381519445],[91.0,16.0]],[[16.0,105.381519445],[91.0,16.0],[166.0,105.381519445]]],"tick":[[[16.0,105.381519445],[91.0,16.0],1],[[166.0,105.381519445],[91.0,16.0],1]],"lab":[[[91.0,64.0],"80°"],[[180.369020899,74.567054685],"?"]],"w":252,"h":121}],"tag":false}},{"stem":"꼭대기 각이 110°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["145"],"explanation":["아래쪽 한 각: (180 − 110) ÷ 2 = 35.","그 각과 ?가 일직선을 이루어요: 180 − 35 = 145.","?는 145°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,68.515565366],[166.0,68.515565366],[91.0,16.0]]],"seg":[[[166.0,68.515565366],[236.0,68.515565366]]],"arc":[[[91.0,16.0],[16.0,68.515565366],[166.0,68.515565366]],[[236.0,68.515565366],[166.0,68.515565366],[91.0,16.0]],[[16.0,68.515565366],[91.0,16.0],[166.0,68.515565366]]],"tick":[[[16.0,68.515565366],[91.0,16.0],1],[[166.0,68.515565366],[91.0,16.0],1]],"lab":[[[91.0,64.0],"110°"],[[176.223997183,36.08918904],"?"]],"w":252,"h":88}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#19','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C7',3,'sa','auto','한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 한 각은 60°예요.","한 바퀴 360° — 360 ÷ 60 = 6.","6개예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 각을 한 점에 나란히 모아 일직선(180°)을 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형의 한 각은 60°예요.","180 ÷ 60 = 3.","3개예요."],"asset":null},{"stem":"정삼각형의 각을 한 점에 나란히 모아 240°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형의 한 각은 60°예요.","240 ÷ 60 = 4.","4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#20','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C8',3,'sa','auto','세 변의 길이가 모두 다르고 가장 큰 각이 100°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"세 변의 길이가 모두 다르고 가장 큰 각이 100°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 둔각삼각형 (가장 큰 각 100°).","모두 1개예요."],"variant_rule":{"alt":[{"stem":"두 변의 길이가 같고 가장 큰 각이 140°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변으로: 이등변삼각형.","각으로: 둔각삼각형 (가장 큰 각 140°).","모두 2개예요."],"asset":null},{"stem":"세 변이 모두 12 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["변으로: 정삼각형·이등변삼각형.","각으로: 예각삼각형 (세 각 모두 60°).","모두 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#21','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C8',3,'sa','auto','둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 92°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 92°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["둔각은 하나뿐 — 92°가 아닌 두 각이 크기가 같아요.","(180 − 92) ÷ 2 = 44.","한 각은 44°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 140°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["둔각은 하나뿐 — 140°가 아닌 두 각이 크기가 같아요.","(180 − 140) ÷ 2 = 20.","한 각은 20°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 110°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["둔각은 하나뿐 — 110°가 아닌 두 각이 크기가 같아요.","(180 − 110) ÷ 2 = 35.","한 각은 35°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#22','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C10',3,'sa','auto','색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u4-C10","difficulty":3,"kind":"sa","stem":"색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 예각, ② 둔각, ③ 예각, ④ 직각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[228,8],[228,228],[52,140]],[[8,228],[8,8],[52,140]],[[8,8],[228,8],[52,140]],[[228,228],[8,228],[52,140]]],"lab":[[[169.333333333,125.333333333],"①"],[[22.666666667,125.333333333],"②"],[[96.0,52.0],"③"],[[96.0,198.666666667],"④"]],"right":[[[8,228],[52,140],[228,228]]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"그림을 바꾸었어요. 색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 예각, ② 둔각, ③ 직각, ④ 예각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[8,8],[184,96]],[[228,8],[228,228],[184,96]],[[8,8],[228,8],[184,96]],[[228,228],[8,228],[184,96]]],"lab":[[[66.666666667,110.666666667],"①"],[[213.333333333,110.666666667],"②"],[[140.0,37.333333333],"③"],[[140.0,184.0],"④"]],"right":[[[228,8],[184,96],[8,8]]],"w":236,"h":236}],"tag":false}},{"stem":"그림을 바꾸었어요. 색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 예각, ③ 둔각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[228,228],[8,8],[228,8]],[[228,228],[8,228],[74,74]],[[74,74],[8,228],[8,8]]],"lab":[[[154.666666667,81.333333333],"①"],[[103.333333333,176.666666667],"②"],[[30.0,103.333333333],"③"]],"right":[[[8,8],[228,8],[228,228]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#23','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C6',4,'sa','auto','이등변삼각형의 꼭대기 각이 아래쪽 한 각의 2배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u4-C6","difficulty":4,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 2배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 2묶음.","모두 4묶음 = 180°, 한 묶음 = 180 ÷ 4 = 45.","꼭대기 각 = 45 × 2 = 90 — 90°예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 3배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 3묶음.","모두 5묶음 = 180°, 한 묶음 = 180 ÷ 5 = 36.","꼭대기 각 = 36 × 3 = 108 — 108°예요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 4배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 4묶음.","모두 6묶음 = 180°, 한 묶음 = 180 ÷ 6 = 30.","꼭대기 각 = 30 × 4 = 120 — 120°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#24','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C8',4,'sa','auto','직각삼각형이면서 이등변삼각형인 삼각형이에요. 직각이 아닌 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u4-C8","difficulty":4,"kind":"sa","stem":"직각삼각형이면서 이등변삼각형인 삼각형이에요. 직각이 아닌 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["직각이 아닌 두 각이 크기가 같아요.","(180 − 90) ÷ 2 = 45.","답은 45°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형에서 크기가 같은 두 각이 각각 25°예요. 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["크기가 같은 두 각은 예각이에요.","180 − 25 − 25 = 130.","답은 130°예요."],"asset":null},{"stem":"예각삼각형이면서 이등변삼각형인 삼각형의 꼭대기 각이 50°예요. 아래쪽 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["아래쪽 두 각이 크기가 같아요.","(180 − 50) ÷ 2 = 65.","답은 65°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_a#25','math',4,1,'u4','','g4_1_math_u4_review_a','unit_review','M4-1-u4-C2',4,'essay','teacher','삼각형의 두 각이 45°, 50°예요. 나머지 한 각을 구하고, 이 삼각형이 각의 크기로 보아 어떤 삼각형인지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u4-C2","difficulty":4,"kind":"essay","stem":"삼각형의 두 각이 45°, 50°예요. 나머지 한 각을 구하고, 이 삼각형이 각의 크기로 보아 어떤 삼각형인지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 180° − 45° − 50° = 85°이다. 세 각 45°, 50°, 85°가 모두 예각이므로 예각삼각형이다.","scoring_points":["85°를 구했는가","세 각이 모두 예각이라고 했는가","예각삼각형이라고 답했는가"]},"explanation":["180 − 45 − 50 = 85.","세 각 모두 90°보다 작아요.","예각삼각형."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#1','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C1',1,'sa','auto','삼각형의 두 각이 95°, 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형의 두 각이 95°, 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 95 − 25 = 60.","나머지 한 각은 60°예요."],"asset":{"type":"geo","items":[{"poly":[[[24.736641558,115.860269954],[230.15104,115.860269954],[16.0,16.0]]],"arc":[[[16.0,16.0],[24.736641558,115.860269954],[230.15104,115.860269954]],[[24.736641558,115.860269954],[230.15104,115.860269954],[16.0,16.0]],[[230.15104,115.860269954],[16.0,16.0],[24.736641558,115.860269954]]],"lab":[[[54.462610693,83.420067134],"95°"],[[253.087021201,120.945054569],"25°"],[[41.237363199,52.042689949],"?"]],"w":291,"h":145}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 65°, 40°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 65 − 40 = 75.","나머지 한 각은 75°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,118.5293848],[186.0,118.5293848],[63.810237318,16.0]]],"arc":[[[63.810237318,16.0],[16.0,118.5293848],[186.0,118.5293848]],[[16.0,118.5293848],[186.0,118.5293848],[63.810237318,16.0]],[[186.0,118.5293848],[63.810237318,16.0],[16.0,118.5293848]]],"lab":[[[53.109223616,94.888202033],"65°"],[[133.377213236,99.376256774],"40°"],[[73.333580331,58.957024313],"?"]],"w":202,"h":135}],"tag":false}},{"stem":"삼각형의 두 각이 65°, 75°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 65 − 75 = 40.","나머지 한 각은 40°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,186.0],[140.8236646,186.0],[95.272301886,16.0]]],"arc":[[[95.272301886,16.0],[16.0,186.0],[140.8236646,186.0]],[[16.0