INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#4','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C5',1,'sa','auto','세 변의 길이의 합이 15 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C5","difficulty":1,"kind":"sa","stem":"세 변의 길이의 합이 15 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","15 ÷ 3 = 5.","한 변은 5 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 27 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","27 ÷ 3 = 9.","한 변은 9 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 36 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","36 ÷ 3 = 12.","한 변은 12 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#5','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C7',1,'sa','auto','정삼각형의 한 각과 직각의 크기의 차는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C7","difficulty":1,"kind":"sa","stem":"정삼각형의 한 각과 직각의 크기의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형은 세 각이 모두 60°예요.","90 − 60 = 30.","답은 30°예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 한 각을 똑같이 반으로 나눈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형은 세 각이 모두 60°예요.","60 ÷ 2 = 30.","답은 30°예요."],"asset":null},{"stem":"정삼각형 두 개의 각을 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["정삼각형은 세 각이 모두 60°예요.","180 + 180 = 360.","답은 360°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
