INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#7','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C8',1,'mc','auto','세 각이 90°, 50°, 40°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X04','M4-1-u4-X21','M4-1-u4-X11']::text[],true,'{"seq":7,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"세 각이 90°, 50°, 40°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형 하나뿐이에요","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 붙일 이름 없음","답은 「직각삼각형 하나뿐이에요」예요."],"variant_rule":{"alt":[{"stem":"세 각이 90°, 45°, 45°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"직각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 이등변삼각형","답은 「직각삼각형, 이등변삼각형」이에요."],"asset":null},{"stem":"세 각이 55°, 80°, 45°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형 하나뿐이에요","correct":true},{"t":"직각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 붙일 이름 없음","답은 「예각삼각형 하나뿐이에요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#8','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C10',1,'sa','auto','색종이의 대각선 두 개를 모두 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u4-C10","difficulty":1,"kind":"sa","stem":"색종이의 대각선 두 개를 모두 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"lab":[[[118.0,44.666666667],"①"],[[191.333333333,118.0],"②"],[[118.0,191.333333333],"③"],[[44.666666667,118.0],"④"]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이 위쪽 변의 가운데 점에서 아래쪽 두 모서리로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③.","모두 3개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[118,8],[8,228]],[[118,8],[228,8],[228,228]],[[118,8],[228,228],[8,228]]],"lab":[[[44.666666667,81.333333333],"①"],[[191.333333333,81.333333333],"②"],[[118.0,154.666666667],"③"]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 그림처럼 세 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[140,8],[8,96]],[[140,8],[228,8],[228,228]],[[140,8],[228,228],[8,96]],[[8,96],[228,228],[8,228]]],"lab":[[[52.0,37.333333333],"①"],[[198.666666667,81.333333333],"②"],[[125.333333333,110.666666667],"③"],[[81.333333333,184.0],"④"]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=E