INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#9','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 꼭대기 각이 90°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 90°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["아래쪽 두 각의 합: 180 − 90 = 90.","두 각의 크기가 같으니 90 ÷ 2 = 45.","한 각은 45°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,103.48],[190.96,103.48],[103.48,16.0]]],"arc":[[[103.48,16.0],[16.0,103.48],[190.96,103.48]]],"lab":[[[67.737253821,82.049727788],"?"],[[103.48,60.0],"90°"]],"right":[[[190.96,103.48],[103.48,16.0],[16.0,103.48]]],"tick":[[[190.96,103.48],[103.48,16.0],1],[[103.48,16.0],[16.0,103.48],1]],"w":207,"h":119}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 50°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["아래쪽 두 각의 합: 180 − 50 = 130.","두 각의 크기가 같으니 130 ÷ 2 = 65.","한 각은 65°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,166.0],[155.892297446,166.0],[85.946148723,16.0]]],"arc":[[[85.946148723,16.0],[16.0,166.0],[155.892297446,166.0]],[[155.892297446,166.0],[85.946148723,16.0],[16.0,166.0]]],"lab":[[[53.109223616,142.358817233],"?"],[[85.946148723,72.0],"50°"]],"tick":[[[155.892297446,166.0],[85.946148723,16.0],1],[[85.946148723,16.0],[16.0,166.0],1]],"w":172,"h":182}],"tag":false}},{"stem":"이등변삼각형의 꼭대기 각이 40°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["아래쪽 두 각의 합: 180 − 40 = 140.","두 각의 크기가 같으니 140 ÷ 2 = 70.","한 각은 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,166.0],[125.19107028,166.0],[70.59553514,16.0]]],"arc":[[[70.59553514,16.0],[16.0,166.0],[125.19107028,166.0]],[[125.19107028,166.0],[70.59553514,16.0],[16.0,166.0]]],"lab":[[[52.042689949,140.762636