INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#10','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C4',2,'sa','auto','세 변의 길이의 합이 25 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C4","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 25 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["길이가 같은 변이 두 개예요.","25 − 8 − 8 = 9.","나머지 한 변은 9 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[19.379849486,140.938256356],[189.379849486,140.938256356],[104.379849486,16.0]]],"tick":[[[189.379849486,140.938256356],[104.379849486,16.0],1],[[104.379849486,16.0],[19.379849486,140.938256356],1]],"lab":[[[104.379849486,154.938256356],"?"],[[170.759698972,62.22280567],"8 cm"],[[38.0,62.22280567],"8 cm"]],"w":209,"h":179}],"tag":false},"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 19 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 6 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["길이가 같은 변이 두 개예요.","19 − 6 − 6 = 7.","나머지 한 변은 7 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[18.746260069,134.35393133],[188.746260069,134.35393133],[103.746260069,16.0]]],"tick":[[[188.746260069,134.35393133],[103.746260069,16.0],1],[[103.746260069,16.0],[18.746260069,134.35393133],1]],"lab":[[[103.746260069,148.35393133],"?"],[[169.492520138,58.481853947],"6 cm"],[[38.0,58.481853947],"6 cm"]],"w":207,"h":172}],"tag":false}},{"stem":"세 변의 길이의 합이 31 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 14 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["길이가 같은 변이 두 개예요.","31 − 14 − 14 = 3.","나머지 한 변은 3 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[60.552907851,186.0],[97.192389464,186.0],[78.872648657,16.0]]],"tick":[[[97.192389464,186.0],[78.872648657,16.0],1],[[78.872648657,16.0],[60.552907851,186.0],1]],"lab":[[[78