INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#11','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C2',2,'mc','auto','삼각형의 두 각이 25°, 30°예요. 이 삼각형은 어떤 삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X01','M4-1-u4-X21']::text[],true,'{"seq":11,"concept":"M4-1-u4-C2","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 25°, 30°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 25 − 30 = 125.","세 각 25°, 30°, 125° — 가장 큰 각은 125°.","둔각삼각형이에요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 100°, 25°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 100 − 25 = 55.","세 각 100°, 25°, 55° — 가장 큰 각은 100°.","둔각삼각형이에요."],"asset":null},{"stem":"삼각형의 두 각이 90°, 45°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"}],"explanation":["나머지 한 각부터 구해요: 180 − 90 − 45 = 45.","세 각 90°, 45°, 45° — 가장 큰 각은 90°.","직각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
