INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#17','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C4',3,'sa','auto','이등변삼각형의 두 변의 길이가 6 cm, 2 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-1-u4-C4","difficulty":3,"kind":"sa","stem":"이등변삼각형의 두 변의 길이가 6 cm, 2 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["같은 두 변이 2 cm이면 2 cm, 2 cm, 6 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 6 cm — 6 cm, 6 cm, 2 cm.","6 + 6 + 2 = 14 — 14 cm예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 두 변의 길이가 10 cm, 2 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["같은 두 변이 2 cm이면 2 cm, 2 cm, 10 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 10 cm — 10 cm, 10 cm, 2 cm.","10 + 10 + 2 = 22 — 22 cm예요."],"asset":null},{"stem":"이등변삼각형의 두 변의 길이가 6 cm, 3 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 6 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 6 cm — 6 cm, 6 cm, 3 cm.","6 + 6 + 3 = 15 — 15 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#18','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C6',3,'sa','auto','꼭대기 각이 90°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"꼭대기 각이 90°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["아래쪽 한 각: (180 − 90) ÷ 2 = 45.","그 각과 ?가 일직선을 이루어요: 180 − 45 = 135.","?는 135°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,91.0],[166.0,91.0],[91.0,16.0]]],"seg":[[[166.0,91.0],[236.0,91.0]]],"arc":[[[91.0,16.0],[16.0,91.0],[166.0,91.0]],[[236.0,91.0],[166.0,91.0],[91.0,16.0]],[[16.0,91.0],[91.0,16.0],[166.0,91.0]]],"tick":[[[16.0,91.0],[91.0,16.0],1],[[166.0,91.0],[91.0,16.0],1]],"lab":[[[91.0,64.0],"90°"],[[179.0112367,59.588095895],"?"]],"w":252,"h":107}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭대기 각이 20°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["아래쪽 한 각: (180 − 20) ÷ 2 = 80.","그 각과 ?가 일직선을 이루어요: 180 − 80 = 100.","?는 100°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,210.0],[75.951173441,210.0],[45.97558672,40.0]]],"seg":[[[75.951173441,210.0],[145.951173441,210.0]]],"arc":[[[45.97558672,40.0],[16.0,210.0],[75.951173441,210.0]],[[145.951173441,210.0],[75.951173441,210.0],[45.97558672,40.0]],[[16.0,210.0],[45.97558672,40.0],[75.951173441,210.0]]],"tick":[[[16.0,210.0],[45.97558672,40.0],1],[[75.951173441,210.0],[45.97558672,40.0],1]],"lab":[[[45.97558672,26.0],"20°"],[[97.80595217,183.954488934],"?"]],"w":162,"h":226}],"tag":false}},{"stem":"꼭대기 각이 100°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["아래쪽 한 각: (180 − 100) ÷ 2 = 40.","그 각과 ?가 일직선을 이루어요: 180 − 40 = 140.","?는 140°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,78.932472338],[166.0,78.932472338],[91.0,16.0]]],"seg":[[[166.0,78.932472338],[236.0,78.932472338]]],"arc":[[[91.0,16.0],[16.0,78.932472338],[166.0,78.932472338]],[[236.0,78.932472338],[166.0,78.932472338],[91.0,16.0]],[[16.0,78.932472338],[91.0,16.0],[166.0,78.932472338]]],"tick":[[[16.0,78.932472338],[91.0,16.0],1],[[166.0,78.932472338],[91.0,16.0],1]],"lab":[[[91.0,64.0],"100°"],[[177.628684873,46.982923232],"?"]],"w":252,"h":95}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#19','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C7',3,'sa','auto','정삼각형의 각을 한 점에 나란히 모아 일직선(180°)을 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"정삼각형의 각을 한 점에 나란히 모아 일직선(180°)을 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형의 한 각은 60°예요.","180 ÷ 60 = 3.","3개예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 각을 한 점에 나란히 모아 240°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형의 한 각은 60°예요.","240 ÷ 60 = 4.","4개예요."],"asset":null},{"stem":"정삼각형의 각을 한 점에 나란히 모아 300°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형의 한 각은 60°예요.","300 ÷ 60 = 5.","5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#20','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C8',3,'sa','auto','두 변의 길이가 같고 가장 큰 각이 100°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"두 변의 길이가 같고 가장 큰 각이 100°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변으로: 이등변삼각형.","각으로: 둔각삼각형 (가장 큰 각 100°).","모두 2개예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이가 모두 다르고 가장 큰 각이 85°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 예각삼각형 (가장 큰 각 85°).","모두 1개예요."],"asset":null},{"stem":"세 변이 모두 9 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["변으로: 정삼각형·이등변삼각형.","각으로: 예각삼각형 (세 각 모두 60°).","모두 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#21','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C8',3,'sa','auto','둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 114°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 114°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["둔각은 하나뿐 — 114°가 아닌 두 각이 크기가 같아요.","(180 − 114) ÷ 2 = 33.","한 각은 33°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 138°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["둔각은 하나뿐 — 138°가 아닌 두 각이 크기가 같아요.","(180 − 138) ÷ 2 = 21.","한 각은 21°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 154°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["둔각은 하나뿐 — 154°가 아닌 두 각이 크기가 같아요.","(180 − 154) ÷ 2 = 13.","한 각은 13°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
