INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#23','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C1',4,'sa','auto','삼각형의 한 각이 30°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 2배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u4-C1","difficulty":4,"kind":"sa","stem":"삼각형의 한 각이 30°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 2배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["나머지 두 각의 합: 180 − 30 = 150.","작은 각 = 150 ÷ 3 = 50, 큰 각 = 50 × 2 = 100.","세 각 30°, 50°, 100° — 가장 큰 각은 100°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 80°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 4배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["나머지 두 각의 합: 180 − 80 = 100.","작은 각 = 100 ÷ 5 = 20, 큰 각 = 20 × 4 = 80.","세 각 80°, 20°, 80° — 가장 큰 각은 80°예요."],"asset":null},{"stem":"삼각형의 한 각이 40°예요. 나머지 두 각 가운데 한 각은 다른 한 각의 3배예요. 세 각 가운데 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["나머지 두 각의 합: 180 − 40 = 140.","작은 각 = 140 ÷ 4 = 35, 큰 각 = 35 × 3 = 105.","세 각 40°, 35°, 105° — 가장 큰 각은 105°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#24','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C7',4,'sa','auto','정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄷㄱㄹ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u4-C7","difficulty":4,"kind":"sa","stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄷㄱㄹ은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["삼각형 ㄱㄷㄹ의 각 ㄱㄷㄹ = 180 − 60 = 120.","(180 − 120) ÷ 2 = 30.","각 ㄷㄱㄹ은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false},"variant_rule":{"alt":[{"stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄱㄹㄷ은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["각 ㄱㄷㄹ = 180 − 60 = 120, 삼각형 ㄱㄷㄹ 은 이등변삼각형.","(180 − 120) ÷ 2 = 30.","각 ㄱㄹㄷ은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false}},{"stem":"정삼각형 ㄱㄴㄷ의 변 ㄴㄷ을 늘여 변 ㄷㄹ의 길이가 변 ㄷㄱ과 같도록 점 ㄹ을 찍었어요. 각 ㄴㄱㄹ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["각 ㄷㄱㄹ = (180 − 120) ÷ 2 = 30.","60 + 30 = 90.","각 ㄴㄱㄹ은 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[111.0,40.0],[36.0,169.903810568],[186.0,169.903810568]]],"seg":[[[186.0,169.903810568],[336.0,169.903810568]],[[111.0,40.0],[336.0,169.903810568]]],"tick":[[[111.0,40.0],[36.0,169.903810568],1],[[36.0,169.903810568],[186.0,169.903810568],1],[[186.0,169.903810568],[111.0,40.0],1],[[186.0,169.903810568],[336.0,169.903810568],1]],"pts":{"ㄱ":[111.0,40.0],"ㄴ":[36.0,169.903810568],"ㄷ":[186.0,169.903810568],"ㄹ":[336.0,169.903810568]},"w":372,"h":206}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_b#25','math',4,1,'u4','','g4_1_math_u4_review_b','unit_review','M4-1-u4-C6',4,'essay','teacher','이등변삼각형의 꼭대기 각이 70°예요. 아래쪽 한 각을 구하는 풀이 과정을 쓰고, 이 삼각형에 붙일 수 있는 이름을 모두 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u4-C6","difficulty":4,"kind":"essay","stem":"이등변삼각형의 꼭대기 각이 70°예요. 아래쪽 한 각을 구하는 풀이 과정을 쓰고, 이 삼각형에 붙일 수 있는 이름을 모두 써 보세요.","answer_guide":{"answer":"예: 아래쪽 두 각의 합은 180° − 70° = 110°이고 크기가 같으므로 110° ÷ 2 = 55°이다. 세 각 70°, 55°, 55°가 모두 예각이므로 예각삼각형이고 이등변삼각형이다.","scoring_points":["110 ÷ 2 = 55를 구했는가","예각삼각형을 썼는가","이등변삼각형을 썼는가"]},"explanation":["180 − 70 = 110.","110 ÷ 2 = 55.","예각삼각형 · 이등변삼각형."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#1','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C1',1,'sa','auto','삼각형의 두 각이 105°, 45°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형의 두 각이 105°, 45°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 105 − 45 = 30.","나머지 한 각은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[61.551362713,186.0],[186.0,186.0],[16.0,16.0]]],"arc":[[[16.0,16.0],[61.551362713,186.0],[186.0,186.0]],[[61.551362713,186.0],[186.0,186.0],[16.0,16.0]],[[186.0,186.0],[16.0,16.0],[61.551362713,186.0]]],"lab":[[[82.2492513,159.02598643],"105°"],[[134.262746179,164.569727788],"45°"],[[44.0,64.497422612],"?"]],"w":202,"h":202}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 80°, 80°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 80 − 80 = 20.","나머지 한 각은 20°예요."],"asset":{"type":"geo","items":[{"poly":[[[55.99657155,213.401754251],[115.947744991,213.401754251],[85.972158271,43.401754251]]],"arc":[[[85.972158271,43.401754251],[55.99657155,213.401754251],[115.947744991,213.401754251]],[[55.99657155,213.401754251],[115.947744991,213.401754251],[85.972158271,43.401754251]],[[115.947744991,213.401754251],[85.972158271,43.401754251],[55.99657155,213.401754251]]],"lab":[[[38.0,228.502670801],"80°"],[[133.944316541,228.502670801],"80°"],[[85.972158271,26.0],"?"]],"tick":[[[115.947744991,213.401754251],[85.972158271,43.401754251],1],[[85.972158271,43.401754251],[55.99657155,213.401754251],1]],"w":172,"h":253}],"tag":false}},{"stem":"삼각형의 두 각이 60°, 75°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 60 − 75 = 45.","나머지 한 각은 45°예요."],"asset":{"type":"geo","it