INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#2','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C2',1,'mc','auto','세 각이 35°, 90°, 55°인 삼각형이에요. 어떤 삼각형인가요?',ARRAY['M4-1-u4-X04','M4-1-u4-X11']::text[],true,'{"seq":2,"concept":"M4-1-u4-C2","difficulty":1,"kind":"mc","stem":"세 각이 35°, 90°, 55°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"variant_rule":{"alt":[{"stem":"세 각이 90°, 70°, 20°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"asset":null},{"stem":"세 각이 25°, 115°, 40°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 115° — 둔각.","둔각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#3','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C6',1,'sa','auto','이등변삼각형에서 크기가 같은 두 각이 각각 50°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C6","difficulty":1,"kind":"sa","stem":"이등변삼각형에서 크기가 같은 두 각이 각각 50°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["세 각의 합은 180°예요.","180 − 50 − 50 = 80.","나머지 한 각은 80°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,112.532041],[178.0,112.532041],[97.0,16.0]]],"arc":[[[97.0,16.0],[16.0,112.532041],[178.0,112.532041]],[[16.0,112.532041],[178.0,112.532041],[97.0,16.0]],[[178.0,112.532041],[97.0,16.0],[16.0,112.532041]]],"lab":[[[66.753236074,88.865418343],"50°"],[[127.246763926,88.865418343],"50°"],[[97.0,60.0],"?"]],"tick":[[[178.0,112.532041],[97.0,16.0],1],[[97.0,16.0],[16.0,112.532041],1]],"w":194,"h":129}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 20°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["세 각의 합은 180°예요.","180 − 20 − 20 = 140.","나머지 한 각은 140°예요."],"asset":{"type":"geo","items":[{"poly":[[[61.135946419,59.31812643],[299.16709486,59.31812643],[180.151520639,16.0]]],"arc":[[[180.151520639,16.0],[61.135946419,59.31812643],[299.16709486,59.31812643]],[[61.135946419,59.31812643],[299.16709486,59.31812643],[180.151520639,16.0]],[[299.16709486,59.31812643],[180.151520639,16.0],[61.135946419,59.31812643]]],"lab":[[[38.0,63.397618008],"20°"],[[322.303041279,63.397618008],"20°"],[[180.151520639,50.0],"?"]],"tick":[[[299.16709486,59.31812643],[180.151520639,16.0],1],[[180.151520639,16.0],[61.135946419,59.31812643],1]],"w":360,"h":87}],"tag":false}},{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 65°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["세 각의 합은 180°예요.","180 − 65 − 65 = 50.","나머지 한 각은 50°예요."],"a