INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#7','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C8',1,'mc','auto','세 각이 20°, 125°, 35°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X01','M4-1-u4-X21','M4-1-u4-X11']::text[],true,'{"seq":7,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"세 각이 20°, 125°, 35°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"둔각삼각형 하나뿐이에요","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 둔각삼각형, 변으로 → 붙일 이름 없음","답은 「둔각삼각형 하나뿐이에요」예요."],"variant_rule":{"alt":[{"stem":"세 각이 10°, 160°, 10°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"둔각삼각형, 이등변삼각형","correct":true},{"t":"둔각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 둔각삼각형, 변으로 → 이등변삼각형","답은 「둔각삼각형, 이등변삼각형」이에요."],"asset":null},{"stem":"세 각이 45°, 45°, 90°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형, 이등변삼각형","correct":true},{"t":"직각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"예각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 이등변삼각형","답은 「직각삼각형, 이등변삼각형」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
