INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#9','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 꼭대기 각이 30°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 30°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["아래쪽 두 각의 합: 180 − 30 = 150.","두 각의 크기가 같으니 150 ÷ 2 = 75.","한 각은 75°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,166.0],[96.384757729,166.0],[56.192378865,16.0]]],"arc":[[[56.192378865,16.0],[16.0,166.0],[96.384757729,166.0]],[[96.384757729,166.0],[56.192378865,16.0],[16.0,166.0]]],"lab":[[[50.907546973,139.214497124],"?"],[[56.192378865,86.587204325],"30°"]],"tick":[[[96.384757729,166.0],[56.192378865,16.0],1],[[56.192378865,16.0],[16.0,166.0],1]],"w":112,"h":182}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 110°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["아래쪽 두 각의 합: 180 − 110 = 70.","두 각의 크기가 같으니 70 ÷ 2 = 35.","한 각은 35°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,82.154487878],[204.9568,82.154487878],[110.4784,16.0]]],"arc":[[[110.4784,16.0],[16.0,82.154487878],[204.9568,82.154487878]],[[204.9568,82.154487878],[110.4784,16.0],[16.0,82.154487878]]],"lab":[[[69.408149242,65.314963106],"?"],[[110.4784,50.0],"110°"]],"tick":[[[204.9568,82.154487878],[110.4784,16.0],1],[[110.4784,16.0],[16.0,82.154487878],1]],"w":221,"h":98}],"tag":false}},{"stem":"이등변삼각형의 꼭대기 각이 130°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["아래쪽 두 각의 합: 180 − 130 = 50.","두 각의 크기가 같으니 50 ÷ 2 = 25.","한 각은 25°예요."],"asset":{"type":"geo","items":[{"poly":[[[54.989263192,60.05600145],[243.946063192,60.05600145],[149.467663192,16.0]]],"arc":[[[149.467663192,16.0],[54.989263192,60.05600145],[243.94