INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#10','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C4',2,'sa','auto','세 변의 길이의 합이 23 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C4","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 23 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 8 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["길이가 같은 변이 두 개예요.","23 − 8 − 8 = 7.","나머지 한 변은 7 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[23.788386461,186.0],[189.209821613,186.0],[106.499104037,16.0]]],"tick":[[[189.209821613,186.0],[106.499104037,16.0],1],[[106.499104037,16.0],[23.788386461,186.0],1]],"lab":[[[106.499104037,200.0],"?"],[[174.998208073,87.793655016],"8 cm"],[[38.0,87.793655016],"8 cm"]],"w":213,"h":224}],"tag":false},"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 13 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 5 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["길이가 같은 변이 두 개예요.","13 − 5 − 5 = 3.","나머지 한 변은 3 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[41.003885483,186.0],[147.928938829,186.0],[94.466412156,16.0]]],"tick":[[[147.928938829,186.0],[94.466412156,16.0],1],[[94.466412156,16.0],[41.003885483,186.0],1]],"lab":[[[94.466412156,200.0],"?"],[[150.932824312,91.648728312],"5 cm"],[[38.0,91.648728312],"5 cm"]],"w":189,"h":224}],"tag":false}},{"stem":"세 변의 길이의 합이 58 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 15 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["길이가 같은 변이 두 개예요.","58 − 15 − 15 = 28.","나머지 한 변은 28 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,61.445872987],[186.0,61.445872987],[101.0,28.750229515]]],"tick":[[[186.0,61.445872987],[101.0,28.750229515],1],[[101.0,28.750229515],[16.0,61.445872987],1]],"lab":[[[101.0,75.445872987],"?"],[[150.84615382,26.0],"15 cm"],[[51.15384618,26.0],