INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#13','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C6',2,'mc','auto','두 각의 크기가 80°, 70°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X06','M4-1-u4-X21']::text[],true,'{"seq":13,"concept":"M4-1-u4-C6","difficulty":2,"kind":"mc","stem":"두 각의 크기가 80°, 70°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 30°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 80 − 70 = 30 — 세 각 80°, 70°, 30°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"variant_rule":{"alt":[{"stem":"두 각의 크기가 30°, 115°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 35°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 30 − 115 = 35 — 세 각 30°, 115°, 35°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"asset":null},{"stem":"두 각의 크기가 55°, 35°인 삼각형이에요. 이 삼각형은 이등변삼각형인가요?","options":[{"t":"아니에요 — 나머지 한 각이 90°라서 크기가 같은 두 각이 없어요","correct":true},{"t":"맞아요 — 두 각을 더하면 같은 각이 생겨요","mis":"M4-1-u4-X11"},{"t":"알 수 없어요 — 자로 변의 길이를 재야 해요","mis":"M4-1-u4-X06"},{"t":"맞아요 — 삼각형은 모두 이등변삼각형이에요","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요.","180 − 55 − 35 = 90 — 세 각 55°, 35°, 90°.","같은 두 각이 없어요 — 이등변삼각형이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#14','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C5',2,'sa','auto','한 변이 10 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M4-1-u4-C5","difficulty":2,"kind":"sa","stem":"한 변이 10 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["세 변이 모두 10 cm예요.","10 × 3 = 30.","세 변의 길이의 합은 30 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"10 cm"]],"w":202,"h":201}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변이 22 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["세 변이 모두 22 cm예요.","22 × 3 = 66.","세 변의 길이의 합은 66 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"22 cm"]],"w":202,"h":201}],"tag":false}},{"stem":"한 변이 26 cm인 정삼각형이에요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["78"],"explanation":["세 변이 모두 26 cm예요.","26 × 3 = 78.","세 변의 길이의 합은 78 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,163.224318643],[186.0,163.224318643],[101.0,16.0]]],"tick":[[[16.0,163.224318643],[186.0,163.224318643],1],[[186.0,163.224318643],[101.0,16.0],1],[[101.0,16.0],[16.0,163.224318643],1]],"lab":[[[101.0,177.224318643],"26 cm"]],"w":202,"h":201}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem,