INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#15','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C8',2,'sa','auto','세 각이 55°, 35°, 90°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u4-C8","difficulty":2,"kind":"sa","stem":"세 각이 55°, 35°, 90°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각으로 이름 하나: 직각삼각형.","변으로: 붙일 이름 없음(세 변의 길이가 모두 달라요).","모두 1개예요."],"variant_rule":{"alt":[{"stem":"세 각이 60°, 20°, 100°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각으로 이름 하나: 둔각삼각형.","변으로: 붙일 이름 없음(세 변의 길이가 모두 달라요).","모두 1개예요."],"asset":null},{"stem":"세 각이 60°, 55°, 65°인 삼각형이에요. 붙일 수 있는 이름은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각으로 이름 하나: 예각삼각형.","변으로: 붙일 이름 없음(세 변의 길이가 모두 달라요).","모두 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
