INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#17','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C4',3,'sa','auto','이등변삼각형의 두 변의 길이가 13 cm, 5 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-1-u4-C4","difficulty":3,"kind":"sa","stem":"이등변삼각형의 두 변의 길이가 13 cm, 5 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["같은 두 변이 5 cm이면 5 cm, 5 cm, 13 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 13 cm — 13 cm, 13 cm, 5 cm.","13 + 13 + 5 = 31 — 31 cm예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 두 변의 길이가 3 cm, 7 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 7 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 7 cm — 7 cm, 7 cm, 3 cm.","7 + 7 + 3 = 17 — 17 cm예요."],"asset":null},{"stem":"이등변삼각형의 두 변의 길이가 4 cm, 11 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["같은 두 변이 4 cm이면 4 cm, 4 cm, 11 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 11 cm — 11 cm, 11 cm, 4 cm.","11 + 11 + 4 = 26 — 26 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#18','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C6',3,'sa','auto','꼭대기 각이 120°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"꼭대기 각이 120°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["아래쪽 한 각: (180 − 120) ÷ 2 = 30.","그 각과 ?가 일직선을 이루어요: 180 − 30 = 150.","?는 150°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,59.301270189],[166.0,59.301270189],[91.0,16.0]]],"seg":[[[166.0,59.301270189],[236.0,59.301270189]]],"arc":[[[91.0,16.0],[16.0,59.301270189],[166.0,59.301270189]],[[236.0,59.301270189],[166.0,59.301270189],[91.0,16.0]],[[16.0,59.301270189],[91.0,16.0],[166.0,59.301270189]]],"tick":[[[16.0,59.301270189],[91.0,16.0],1],[[166.0,59.301270189],[91.0,16.0],1]],"lab":[[[91.0,64.0],"120°"],[[174.799847533,26.459792095],"?"]],"w":252,"h":88}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭대기 각이 40°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["아래쪽 한 각: (180 − 40) ÷ 2 = 70.","그 각과 ?가 일직선을 이루어요: 180 − 70 = 110.","?는 110°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,210.0],[139.749879651,210.0],[77.874939825,40.0]]],"seg":[[[139.749879651,210.0],[209.749879651,210.0]]],"arc":[[[77.874939825,40.0],[16.0,210.0],[139.749879651,210.0]],[[209.749879651,210.0],[139.749879651,210.0],[77.874939825,40.0]],[[16.0,210.0],[77.874939825,40.0],[139.749879651,210.0]]],"tick":[[[16.0,210.0],[77.874939825,40.0],1],[[139.749879651,210.0],[77.874939825,40.0],1]],"lab":[[[77.874939825,26.0],"40°"],[[159.251478486,182.148830494],"?"]],"w":226,"h":226}],"tag":false}},{"stem":"꼭대기 각이 30°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["아래쪽 한 각: (180 − 30) ÷ 2 = 75.","그 각과 ?가 일직선을 이루어요: 180 − 75 = 105.","?는 105°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,210.0],[107.102725427,210.0],[61.551362713,40.0]]],"seg":[[[107.102725427,210.0],[177.102725427,210.0]]],"arc":[[[61.551362713,40.0],[16.0,210.0],[107.102725427,210.0]],[[177.102725427,210.0],[107.102725427,210.0],[61.551362713,40.0]],[[16.0,210.0],[61.551362713,40.0],[107.102725427,210.0]]],"tick":[[[16.0,210.0],[61.551362713,40.0],1],[[107.102725427,210.0],[61.551362713,40.0],1]],"lab":[[[61.551362713,26.0],"30°"],[[127.800614013,183.02598643],"?"]],"w":193,"h":226}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#19','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C7',3,'sa','auto','정삼각형의 각을 한 점에 나란히 모아 240°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"정삼각형의 각을 한 점에 나란히 모아 240°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형의 한 각은 60°예요.","240 ÷ 60 = 4.","4개예요."],"variant_rule":{"alt":[{"stem":"정삼각형의 각을 한 점에 나란히 모아 300°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형의 한 각은 60°예요.","300 ÷ 60 = 5.","5개예요."],"asset":null},{"stem":"한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 한 각은 60°예요.","한 바퀴 360° — 360 ÷ 60 = 6.","6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#20','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C8',3,'sa','auto','세 변의 길이가 모두 다르고 가장 큰 각이 130°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"세 변의 길이가 모두 다르고 가장 큰 각이 130°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 둔각삼각형 (가장 큰 각 130°).","모두 1개예요."],"variant_rule":{"alt":[{"stem":"두 변의 길이가 같고 가장 큰 각이 70°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변으로: 이등변삼각형.","각으로: 예각삼각형 (가장 큰 각 70°).","모두 2개예요."],"asset":null},{"stem":"세 변의 길이가 모두 다르고 가장 큰 각이 65°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 예각삼각형 (가장 큰 각 65°).","모두 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#21','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C8',3,'sa','auto','둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 156°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 156°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["둔각은 하나뿐 — 156°가 아닌 두 각이 크기가 같아요.","(180 − 156) ÷ 2 = 12.","한 각은 12°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 132°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["둔각은 하나뿐 — 132°가 아닌 두 각이 크기가 같아요.","(180 − 132) ÷ 2 = 24.","한 각은 24°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 136°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["둔각은 하나뿐 — 136°가 아닌 두 각이 크기가 같아요.","(180 − 136) ÷ 2 = 22.","한 각은 22°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#22','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C10',3,'sa','auto','색종이를 그림처럼 잘랐어요. 직각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u4-C10","difficulty":3,"kind":"sa","stem":"색종이를 그림처럼 잘랐어요. 직각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 둔각, ③ 예각.","직각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,228],[8,228]],[[8,8],[228,8],[96,96]],[[96,96],[228,8],[228,228]]],"lab":[[[81.333333333,154.666666667],"①"],[[110.666666667,37.333333333],"②"],[[184.0,110.666666667],"③"]],"right":[[[228,228],[8,228],[8,8]]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 둔각, ③ 예각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[228,8],[228,228]],[[8,228],[8,8],[96,140]],[[96,140],[8,8],[228,8]]],"lab":[[[154.666666667,154.666666667],"①"],[[37.333333333,125.333333333],"②"],[[110.666666667,52.0],"③"]],"right":[[[228,8],[228,228],[8,228]]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 예각, ② 둔각, ③ 예각, ④ 직각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,228],[8,8],[140,184]],[[228,228],[8,228],[140,184]],[[8,8],[228,8],[140,184]],[[228,8],[228,228],[140,184]]],"lab":[[[52.0,140.0],"①"],[[125.333333333,213.333333333],"②"],[[125.333333333,66.666666667],"③"],[[198.666666667,140.0],"④"]],"right":[[[228,228],[140,184],[228,8]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#23','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C10',4,'sa','auto','색종이를 잘라 삼각형 조각 3개를 만들었어요. 그중 1개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u4-C10","difficulty":4,"kind":"sa","stem":"색종이를 잘라 삼각형 조각 3개를 만들었어요. 그중 1개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 3 + 1 = 4.","180 × 4 = 720 — 720°예요."],"variant_rule":{"alt":[{"stem":"색종이를 잘라 삼각형 조각 5개를 만들었어요. 그중 2개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["1260"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 5 + 2 = 7.","180 × 7 = 1260 — 1260°예요."],"asset":null},{"stem":"색종이를 잘라 삼각형 조각 2개를 만들었어요. 그중 2개의 조각을 꼭짓점에서 마주 보는 변까지 곧게 한 번씩 더 잘랐어요. 이제 모든 조각의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["한 조각을 꼭짓점에서 마주 보는 변으로 자르면 삼각형 2개가 돼요 — 조각이 1개씩 늘어요.","조각 수: 2 + 2 = 4.","180 × 4 = 720 — 720°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#24','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C8',4,'sa','auto','직각삼각형이면서 이등변삼각형인 삼각형의 세 각 가운데 가장 작은 각과 가장 큰 각의 차는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u4-C8","difficulty":4,"kind":"sa","stem":"직각삼각형이면서 이등변삼각형인 삼각형의 세 각 가운데 가장 작은 각과 가장 큰 각의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["세 각은 90°, 45°, 45°예요.","90 − 45 = 45.","답은 45°예요."],"variant_rule":{"alt":[{"stem":"직각삼각형이면서 이등변삼각형인 삼각형이에요. 직각이 아닌 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["직각이 아닌 두 각이 크기가 같아요.","(180 − 90) ÷ 2 = 45.","답은 45°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형에서 크기가 같은 두 각이 각각 25°예요. 가장 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["크기가 같은 두 각은 예각이에요.","180 − 25 − 25 = 130.","답은 130°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_c#25','math',4,1,'u4','','g4_1_math_u4_review_c','unit_review','M4-1-u4-C9',4,'essay','teacher','정삼각형에 붙일 수 있는 이름을 모두 쓰고, 각각 그렇게 부를 수 있는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u4-C9","difficulty":4,"kind":"essay","stem":"정삼각형에 붙일 수 있는 이름을 모두 쓰고, 각각 그렇게 부를 수 있는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 정삼각형, 이등변삼각형, 예각삼각형이다. 세 변의 길이가 같으니 정삼각형, 두 변의 길이도 같으니 이등변삼각형, 세 각이 모두 60°로 예각이니 예각삼각형이다.","scoring_points":["세 이름을 모두 썼는가","변의 길이로 정·이등변을 설명했는가","60°로 예각삼각형을 설명했는가"]},"explanation":["변으로: 정삼각형 · 이등변삼각형.","각으로: 60°·60°·60° → 예각삼각형.","이름이 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#1','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C1',1,'sa','auto','삼각형의 두 각이 110°, 40°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u4-C1","difficulty":1,"kind":"sa","stem":"삼각형의 두 각이 110°, 40°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 110 − 40 = 30.","나머지 한 각은 30°예요."],"asset":{"type":"geo","items":[{"poly":[[[72.072778321,170.058692284],[199.6,170.058692284],[16.0,16.0]]],"arc":[[[16.0,16.0],[72.072778321,170.058692284],[199.6,170.058692284]],[[72.072778321,170.058692284],[199.6,170.058692284],[16.0,16.0]],[[199.6,170.058692284],[16.0,16.0],[72.072778321,170.058692284]]],"lab":[[[91.574377157,142.207522778],"110°"],[[146.977213236,150.905564258],"40°"],[[48.120280436,61.87251448],"?"]],"w":216,"h":186}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 55°, 25°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 55 − 25 = 100.","나머지 한 각은 100°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,103.806975597],[265.785773056,103.806975597],[77.48310622,16.0]]],"arc":[[[77.48310622,16.0],[16.0,103.806975597],[265.785773056,103.806975597]],[[16.0,103.806975597],[265.785773056,103.806975597],[77.48310622,16.0]],[[265.785773056,103.806975597],[77.48310622,16.0],[16.0,103.806975597]]],"lab":[[[65.672606658,77.949053255],"55°"],[[288.721754257,108.891760211],"25°"],[[86.282953754,48.841478094],"?"]],"w":327,"h":133}],"tag":false}},{"stem":"삼각형의 두 각이 30°, 100°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","180 − 30 − 100 = 50.","나머지 한 각은 50°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,122.001509423],[180.909073893,122.001509423],[199.6,16.0]]],"arc":[[[199.6,16.0],[16.0,122.001509423],[180.909073893,122.001509423]],[[16.0,122.001509423],[180.909073893,122.001509423],[199.6,16.0]],[[180.909073893,122.001509423],[199.6,16.0],[16.0,122.001509423]]],"lab":[[[84.182003663,103.732196603],"30°"],[[159.054295164,95.955998357],"100°"],[[167.479719564,61.87251448],"?"]],"w":216,"h":138}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#2','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C2',1,'mc','auto','세 각이 30°, 90°, 60°인 삼각형이에요. 어떤 삼각형인가요?',ARRAY['M4-1-u4-X04','M4-1-u4-X11']::text[],true,'{"seq":2,"concept":"M4-1-u4-C2","difficulty":1,"kind":"mc","stem":"세 각이 30°, 90°, 60°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"variant_rule":{"alt":[{"stem":"세 각이 90°, 60°, 30°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"asset":null},{"stem":"세 각이 35°, 55°, 90°인 삼각형이에요. 어떤 삼각형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X04"},{"t":"각의 크기만으로는 알 수 없어요","mis":"M4-1-u4-X11"}],"explanation":["가장 큰 각이 예각·직각·둔각 중 무엇인지 봐요.","가장 큰 각은 90° — 직각.","직각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#3','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C6',1,'sa','auto','이등변삼각형에서 크기가 같은 두 각이 각각 85°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u4-C6","difficulty":1,"kind":"sa","stem":"이등변삼각형에서 크기가 같은 두 각이 각각 85°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세 각의 합은 180°예요.","180 − 85 − 85 = 10.","나머지 한 각은 10°예요."],"asset":{"type":"geo","items":[{"poly":[[[55.320750073,193.401754251],[81.567349131,193.401754251],[68.444049602,43.401754251]]],"arc":[[[68.444049602,43.401754251],[55.320750073,193.401754251],[81.567349131,193.401754251]],[[55.320750073,193.401754251],[81.567349131,193.401754251],[68.444049602,43.401754251]],[[81.567349131,193.401754251],[68.444049602,43.401754251],[55.320750073,193.401754251]]],"lab":[[[38.0,209.2732975],"85°"],[[98.888099204,209.2732975],"85°"],[[68.444049602,26.0],"?"]],"tick":[[[81.567349131,193.401754251],[68.444049602,43.401754251],1],[[68.444049602,43.401754251],[55.320750073,193.401754251],1]],"w":137,"h":233}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 55°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["세 각의 합은 180°예요.","180 − 55 − 55 = 70.","나머지 한 각은 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]]],"arc":[[[91.0,16.0],[16.0,123.111100506],[166.0,123.111100506]],[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]],[[166.0,123.111100506],[91.0,16.0],[16.0,123.111100506]]],"lab":[[[65.672606658,97.253178164],"55°"],[[116.327393342,97.253178164],"55°"],[[91.0,60.0],"?"]],"tick":[[[166.0,123.111100506],[91.0,16.0],1],[[91.0,16.0],[16.0,123.111100506],1]],"w":182,"h":139}],"tag":false}},{"stem":"이등변삼각형에서 크기가 같은 두 각이 각각 35°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["세 각의 합은 180°예요.","180 − 35 − 35 = 110.","나머지 한 각은 110°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,87.446846908],[220.073344,87.446846908],[118.036672,16.0]]],"arc":[[[118.036672,16.0],[16.0,87.446846908],[220.073344,87.446846908]],[[16.0,87.446846908],[220.073344,87.446846908],[118.036672,16.0]],[[220.073344,87.446846908],[118.036672,16.0],[16.0,87.446846908]]],"lab":[[[74.34140102,69.051873825],"35°"],[[161.73194298,69.051873825],"35°"],[[118.036672,50.0],"?"]],"tick":[[[220.073344,87.446846908],[118.036672,16.0],1],[[118.036672,16.0],[16.0,87.446846908],1]],"w":236,"h":103}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#4','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C5',1,'sa','auto','세 변의 길이의 합이 42 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u4-C5","difficulty":1,"kind":"sa","stem":"세 변의 길이의 합이 42 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","42 ÷ 3 = 14.","한 변은 14 cm예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 6 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","6 ÷ 3 = 2.","한 변은 2 cm예요."],"asset":null},{"stem":"세 변의 길이의 합이 60 cm인 정삼각형이에요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","60 ÷ 3 = 20.","한 변은 20 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#5','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C7',1,'sa','auto','정삼각형의 한 각을 똑같이 반으로 나눈 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u4-C7","difficulty":1,"kind":"sa","stem":"정삼각형의 한 각을 똑같이 반으로 나눈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["정삼각형은 세 각이 모두 60°예요.","60 ÷ 2 = 30.","답은 30°예요."],"variant_rule":{"alt":[{"stem":"정삼각형에서 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["정삼각형은 세 각이 모두 60°예요.","한 각은 60° — 60 + 60 = 120.","답은 120°예요."],"asset":null},{"stem":"정삼각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정삼각형은 세 각이 모두 60°예요.","180 ÷ 3 = 60.","답은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
