INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#7','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C8',1,'mc','auto','세 각이 90°, 25°, 65°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?',ARRAY['M4-1-u4-X04','M4-1-u4-X21','M4-1-u4-X11']::text[],true,'{"seq":7,"concept":"M4-1-u4-C8","difficulty":1,"kind":"mc","stem":"세 각이 90°, 25°, 65°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"직각삼각형 하나뿐이에요","correct":true},{"t":"예각삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X11"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 직각삼각형, 변으로 → 붙일 이름 없음","답은 「직각삼각형 하나뿐이에요」예요."],"variant_rule":{"alt":[{"stem":"세 각이 20°, 80°, 80°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형","답은 「예각삼각형, 이등변삼각형」이에요."],"asset":null},{"stem":"세 각이 70°, 70°, 40°인 삼각형이에요. 이름을 모두 고른 것은 무엇인가요?","options":[{"t":"예각삼각형, 이등변삼각형","correct":true},{"t":"예각삼각형 하나뿐이에요","mis":"M4-1-u4-X14"},{"t":"직각삼각형, 이등변삼각형","mis":"M4-1-u4-X04"},{"t":"둔각삼각형, 이등변삼각형","mis":"M4-1-u4-X21"}],"explanation":["각으로 한 번, 변으로 한 번 이름을 붙여요.","각으로 → 예각삼각형, 변으로 → 이등변삼각형","답은 「예각삼각형, 이등변삼각형」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#8','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C10',1,'sa','auto','색종이 안의 한 점에서 네 모서리로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u4-C10","difficulty":1,"kind":"sa","stem":"색종이 안의 한 점에서 네 모서리로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[52,96]],[[228,8],[228,228],[52,96]],[[228,228],[8,228],[52,96]],[[8,228],[8,8],[52,96]]],"lab":[[[96.0,37.333333333],"①"],[[169.333333333,110.666666667],"②"],[[96.0,184.0],"③"],[[22.666666667,110.666666667],"④"]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이를 대각선으로 한 번 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②.","모두 2개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[228,228]],[[8,8],[228,228],[8,228]]],"lab":[[[154.666666667,81.333333333],"①"],[[81.333333333,154.666666667],"②"]],"w":236,"h":236}],"tag":false}},{"stem":"색종이의 대각선 두 개를 모두 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["잘린 조각을 하나씩 세어요.","조각 번호 ①②③④.","모두 4개예요."],"asset":{"type":"geo","items":[{"poly":[[[8,8],[228,8],[118,118]],[[228,8],[228,228],[118,118]],[[228,228],[8,228],[118,118]],[[8,228],[8,8],[118,118]]],"lab":[[[118.0,44.666666667],"①"],[[191.333333333,118.0],"②"],[[118.0,191.333333333],"③"],[[44.666666667,118.0],"④"]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#9','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C6',2,'sa','auto','이등변삼각형의 꼭대기 각이 20°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u4-C6","difficulty":2,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 20°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["아래쪽 두 각의 합: 180 − 20 = 160.","두 각의 크기가 같으니 160 ÷ 2 = 80.","한 각은 80°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,253.566199685],[87.967273181,253.566199685],[51.983636591,49.492855685]]],"arc":[[[51.983636591,49.492855685],[16.0,253.566199685],[87.967273181,253.566199685]],[[87.967273181,253.566199685],[51.983636591,49.492855685],[16.0,253.566199685]]],"lab":[[[49.705955497,225.283544858],"?"],[[51.983636591,26.0],"20°"]],"tick":[[[87.967273181,253.566199685],[51.983636591,49.492855685],1],[[51.983636591,49.492855685],[16.0,253.566199685],1]],"w":104,"h":270}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 70°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["아래쪽 두 각의 합: 180 − 70 = 110.","두 각의 크기가 같으니 110 ÷ 2 = 55.","한 각은 55°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]]],"arc":[[[91.0,16.0],[16.0,123.111100506],[166.0,123.111100506]],[[166.0,123.111100506],[91.0,16.0],[16.0,123.111100506]]],"lab":[[[65.672606658,97.253178164],"?"],[[91.0,60.0],"70°"]],"tick":[[[166.0,123.111100506],[91.0,16.0],1],[[91.0,16.0],[16.0,123.111100506],1]],"w":182,"h":139}],"tag":false}},{"stem":"이등변삼각형의 꼭대기 각이 140°예요. 아래쪽 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["아래쪽 두 각의 합: 180 − 140 = 40.","두 각의 크기가 같으니 40 ÷ 2 = 20.","한 각은 20°예요."],"asset":{"type":"geo","items":[{"poly":[[[55.137382502,59.31812643],[293.168530944,59.31812643],[174.152956723,16.