INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#10','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C4',2,'sa','auto','세 변의 길이의 합이 35 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 14 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u4-C4","difficulty":2,"kind":"sa","stem":"세 변의 길이의 합이 35 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 14 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["길이가 같은 변이 두 개예요.","35 − 14 − 14 = 7.","나머지 한 변은 7 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[46.483536083,186.0],[134.271158597,186.0],[90.37734734,16.0]]],"tick":[[[134.271158597,186.0],[90.37734734,16.0],1],[[90.37734734,16.0],[46.483536083,186.0],1]],"lab":[[[90.37734734,200.0],"?"],[[142.75469468,93.142893736],"14 cm"],[[38.0,93.142893736],"14 cm"]],"w":181,"h":224}],"tag":false},"variant_rule":{"alt":[{"stem":"세 변의 길이의 합이 18 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 5 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["길이가 같은 변이 두 개예요.","18 − 5 − 5 = 8.","나머지 한 변은 8 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,79.75],[186.0,79.75],[101.0,16.0]]],"tick":[[[186.0,79.75],[101.0,16.0],1],[[101.0,16.0],[16.0,79.75],1]],"lab":[[[101.0,93.75],"?"],[[158.38,28.035],"5 cm"],[[43.62,28.035],"5 cm"]],"w":202,"h":118}],"tag":false}},{"stem":"세 변의 길이의 합이 14 cm인 이등변삼각형이에요. 길이가 같은 두 변이 각각 5 cm일 때, 나머지 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["길이가 같은 변이 두 개예요.","14 − 5 − 5 = 4.","나머지 한 변은 4 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[28.854170606,186.0],[177.242335966,186.0],[103.048253286,16.0]]],"tick":[[[177.242335966,186.0],[103.048253286,16.0],1],[[103.048253286,16.0],[28.854170606,186.0],1]],"lab":[[[103.048253286,200.0],"?"],[[168.096506572,88.801090999],"5 cm"],[[38.0,88.801090999],"5 cm"]],"w":206,"h":224}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) 