INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#11','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C2',2,'mc','auto','삼각형의 두 각이 60°, 75°예요. 이 삼각형은 어떤 삼각형인가요?',ARRAY['M4-1-u4-X11','M4-1-u4-X21']::text[],true,'{"seq":11,"concept":"M4-1-u4-C2","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 60°, 75°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 60 − 75 = 45.","세 각 60°, 75°, 45° — 가장 큰 각은 75°.","예각삼각형이에요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 130°, 30°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"둔각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"예각삼각형","mis":"M4-1-u4-X01"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 130 − 30 = 20.","세 각 130°, 30°, 20° — 가장 큰 각은 130°.","둔각삼각형이에요."],"asset":null},{"stem":"삼각형의 두 각이 65°, 65°예요. 이 삼각형은 어떤 삼각형인가요?","options":[{"t":"예각삼각형","correct":true},{"t":"알 수 없어요 — 한 각을 몰라요","mis":"M4-1-u4-X11"},{"t":"둔각삼각형","mis":"M4-1-u4-X21"},{"t":"직각삼각형","mis":"M4-1-u4-X21"}],"explanation":["나머지 한 각부터 구해요: 180 − 65 − 65 = 50.","세 각 65°, 65°, 50° — 가장 큰 각은 65°.","예각삼각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
