[52,140]],[[228,228],[8,228],[52,140]],[[228,8],[228,228],[52,140]]],"lab":[[[22.666666667,125.333333333],"①"],[[96.0,52.0],"②"],[[96.0,198.666666667],"③"],[[169.333333333,125.333333333],"④"]],"right":[[[8,228],[52,140],[228,228]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#17','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C4',3,'sa','auto','이등변삼각형의 두 변의 길이가 3 cm, 12 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-1-u4-C4","difficulty":3,"kind":"sa","stem":"이등변삼각형의 두 변의 길이가 3 cm, 12 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 12 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 12 cm — 12 cm, 12 cm, 3 cm.","12 + 12 + 3 = 27 — 27 cm예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 두 변의 길이가 3 cm, 9 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["같은 두 변이 3 cm이면 3 cm, 3 cm, 9 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 9 cm — 9 cm, 9 cm, 3 cm.","9 + 9 + 3 = 21 — 21 cm예요."],"asset":null},{"stem":"이등변삼각형의 두 변의 길이가 8 cm, 4 cm예요. 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["같은 두 변이 4 cm이면 4 cm, 4 cm, 8 cm — 짧은 두 변의 합이 가장 긴 변보다 짧아 삼각형이 안 돼요.","같은 두 변은 8 cm — 8 cm, 8 cm, 4 cm.","8 + 8 + 4 = 20 — 20 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#18','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C6',3,'sa','auto','꼭대기 각이 70°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-1-u4-C6","difficulty":3,"kind":"sa","stem":"꼭대기 각이 70°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["아래쪽 한 각: (180 − 70) ÷ 2 = 55.","그 각과 ?가 일직선을 이루어요: 180 − 55 = 125.","?는 125°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,123.111100506],[166.0,123.111100506],[91.0,16.0]]],"seg":[[[166.0,123.111100506],[236.0,123.111100506]]],"arc":[[[91.0,16.0],[16.0,123.111100506],[166.0,123.111100506]],[[236.0,123.111100506],[166.0,123.111100506],[91.0,16.0]],[[16.0,123.111100506],[91.0,16.0],[166.0,123.111100506]]],"tick":[[[16.0,123.111100506],[91.0,16.0],1],[[166.0,123.111100506],[91.0,16.0],1]],"lab":[[[91.0,64.0],"70°"],[[181.69945285,92.952732178],"?"]],"w":252,"h":139}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭대기 각이 60°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["아래쪽 한 각: (180 − 60) ÷ 2 = 60.","그 각과 ?가 일직선을 이루어요: 180 − 60 = 120.","?는 120°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,145.903810568],[166.0,145.903810568],[91.0,16.0]]],"seg":[[[166.0,145.903810568],[236.0,145.903810568]]],"arc":[[[91.0,16.0],[16.0,145.903810568],[166.0,145.903810568]],[[236.0,145.903810568],[166.0,145.903810568],[91.0,16.0]],[[16.0,145.903810568],[91.0,16.0],[166.0,145.903810568]]],"tick":[[[16.0,145.903810568],[91.0,16.0],1],[[166.0,145.903810568],[91.0,16.0],1]],"lab":[[[91.0,64.0],"60°"],[[183.0,116.458946839],"?"]],"w":252,"h":162}],"tag":false}},{"stem":"꼭대기 각이 140°인 이등변삼각형의 밑변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["160"],"explanation":["아래쪽 한 각: (180 − 140) ÷ 2 = 20.","그 각과 ?가 일직선을 이루어요: 180 − 20 = 160.","?는 160°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,59.483463602],[166.0,59.483463602],[91.0,32.185696032]]],"seg":[[[166.0,59.483463602],[236.0,59.483463602]]],"arc":[[[91.0,32.185696032],[16.0,59.483463602],[166.0,59.483463602]],[[236.0,59.483463602],[166.0,59.483463602],[91.0,32.185696032]],[[16.0,59.483463602],[91.0,32.185696032],[166.0,59.483463602]]],"tick":[[[16.0,59.483463602],[91.0,32.185696032],1],[[166.0,59.483463602],[91.0,32.185696032],1]],"lab":[[[91.0,80.185696032],"140°"],[[171.904038041,26.0],"?"]],"w":252,"h":104}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#19','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C7',3,'sa','auto','정삼각형의 각을 한 점에 나란히 모아 300°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u4-C7","difficulty":3,"kind":"sa","stem":"정삼각형의 각을 한 점에 나란히 모아 300°를 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형의 한 각은 60°예요.","300 ÷ 60 = 5.","5개예요."],"variant_rule":{"alt":[{"stem":"한 점을 빈틈없이 둘러싸려면 정삼각형이 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형의 한 각은 60°예요.","한 바퀴 360° — 360 ÷ 60 = 6.","6개예요."],"asset":null},{"stem":"정삼각형의 각을 한 점에 나란히 모아 일직선(180°)을 만들려면 몇 개가 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형의 한 각은 60°예요.","180 ÷ 60 = 3.","3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#20','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C8',3,'sa','auto','세 변이 모두 11 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"세 변이 모두 11 cm인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["변으로: 정삼각형·이등변삼각형.","각으로: 예각삼각형 (세 각 모두 60°).","모두 3개예요."],"variant_rule":{"alt":[{"stem":"세 변의 길이가 모두 다르고 가장 큰 각이 70°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["변으로: 붙일 이름 없음.","각으로: 예각삼각형 (가장 큰 각 70°).","모두 1개예요."],"asset":null},{"stem":"두 변의 길이가 같고 가장 큰 각이 90°인 삼각형이에요. 붙일 수 있는 이름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변으로: 이등변삼각형.","각으로: 직각삼각형 (가장 큰 각 90°).","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#21','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C8',3,'sa','auto','둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 146°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-1-u4-C8","difficulty":3,"kind":"sa","stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 146°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["둔각은 하나뿐 — 146°가 아닌 두 각이 크기가 같아요.","(180 − 146) ÷ 2 = 17.","한 각은 17°예요."],"variant_rule":{"alt":[{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 168°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["둔각은 하나뿐 — 168°가 아닌 두 각이 크기가 같아요.","(180 − 168) ÷ 2 = 6.","한 각은 6°예요."],"asset":null},{"stem":"둔각삼각형이면서 이등변삼각형인 삼각형의 한 각이 122°예요. 나머지 두 각 가운데 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["둔각은 하나뿐 — 122°가 아닌 두 각이 크기가 같아요.","(180 − 122) ÷ 2 = 29.","한 각은 29°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#22','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C10',3,'sa','auto','색종이를 그림처럼 잘랐어요. 예각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u4-C10","difficulty":3,"kind":"sa","stem":"색종이를 그림처럼 잘랐어요. 예각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 직각, ② 예각, ③ 둔각.","예각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[228,8],[8,228],[8,8]],[[184,52],[228,228],[8,228]],[[228,8],[228,228],[184,52]]],"lab":[[[81.333333333,81.333333333],"①"],[[140.0,169.333333333],"②"],[[213.333333333,96.0],"③"]],"right":[[[8,228],[8,8],[228,8]]],"w":236,"h":236}],"tag":false},"variant_rule":{"alt":[{"stem":"색종이를 그림처럼 잘랐어요. 둔각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 예각, ② 직각, ③ 둔각.","둔각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[228,8],[228,228],[96,140]],[[228,8],[8,228],[8,8]],[[96,140],[228,228],[8,228]]],"lab":[[[184.0,125.333333333],"①"],[[81.333333333,81.333333333],"②"],[[110.666666667,198.666666667],"③"]],"right":[[[8,228],[8,8],[228,8]]],"w":236,"h":236}],"tag":false}},{"stem":"색종이를 그림처럼 잘랐어요. 직각삼각형 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["조각마다 가장 큰 각을 봐요(ㄱ 표시는 직각).","① 예각, ② 직각, ③ 둔각.","직각삼각형 조각은 1개예요."],"asset":{"type":"geo","items":[{"poly":[[[52,52],[228,8],[228,228]],[[8,8],[228,228],[8,228]],[[8,8],[228,8],[52,52]]],"lab":[[[169.333333333,96.0],"①"],[[81.333333333,154.666666667],"②"],[[96.0,22.666666667],"③"]],"right":[[[228,228],[8,228],[8,8]]],"w":236,"h":236}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#23','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C6',4,'sa','auto','이등변삼각형의 꼭대기 각이 아래쪽 한 각의 7배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u4-C6","difficulty":4,"kind":"sa","stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 7배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 7묶음.","모두 9묶음 = 180°, 한 묶음 = 180 ÷ 9 = 20.","꼭대기 각 = 20 × 7 = 140 — 140°예요."],"variant_rule":{"alt":[{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 8배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["144"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 8묶음.","모두 10묶음 = 180°, 한 묶음 = 180 ÷ 10 = 18.","꼭대기 각 = 18 × 8 = 144 — 144°예요."],"asset":null},{"stem":"이등변삼각형의 꼭대기 각이 아래쪽 한 각의 10배예요. 꼭대기 각은 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["아래쪽 두 각은 크기가 같아요 — 아래쪽 한 각을 한 묶음으로 보면 꼭대기 각은 10묶음.","모두 12묶음 = 180°, 한 묶음 = 180 ÷ 12 = 15.","꼭대기 각 = 15 × 10 = 150 — 150°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#24','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C5',4,'sa','auto','한 변이 4 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u4-C5","difficulty":4,"kind":"sa","stem":"한 변이 4 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["큰 정삼각형의 한 변은 작은 정삼각형의 변 2개 — 4 × 2 = 8.","8 × 3 = 24.","세 변의 길이의 합은 24 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"seg":[[[61.0,93.942286341],[151.0,93.942286341]],[[151.0,93.942286341],[106.0,171.884572681]],[[106.0,171.884572681],[61.0,93.942286341]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1],[[196.0,171.884572681],[151.0,93.942286341],1],[[151.0,93.942286341],[106.0,16.0],1],[[106.0,16.0],[61.0,93.942286341],1],[[61.0,93.942286341],[16.0,171.884572681],1]],"w":212,"h":188}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["큰 정삼각형의 한 변은 작은 정삼각형의 변 2개 — 6 × 2 = 12.","12 × 3 = 36.","세 변의 길이의 합은 36 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"seg":[[[61.0,93.942286341],[151.0,93.942286341]],[[151.0,93.942286341],[106.0,171.884572681]],[[106.0,171.884572681],[61.0,93.942286341]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1],[[196.0,171.884572681],[151.0,93.942286341],1],[[151.0,93.942286341],[106.0,16.0],1],[[106.0,16.0],[61.0,93.942286341],1],[[61.0,93.942286341],[16.0,171.884572681],1]],"w":212,"h":188}],"tag":false}},{"stem":"한 변이 9 cm인 정삼각형 4개를 겹치지 않게 붙여 큰 정삼각형을 만들었어요. 큰 정삼각형의 세 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["큰 정삼각형의 한 변은 작은 정삼각형의 변 2개 — 9 × 2 = 18.","18 × 3 = 54.","세 변의 길이의 합은 54 cm예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,171.884572681],[196.0,171.884572681],[106.0,16.0]]],"seg":[[[61.0,93.942286341],[151.0,93.942286341]],[[151.0,93.942286341],[106.0,171.884572681]],[[106.0,171.884572681],[61.0,93.942286341]]],"tick":[[[16.0,171.884572681],[106.0,171.884572681],1],[[106.0,171.884572681],[196.0,171.884572681],1],[[196.0,171.884572681],[151.0,93.942286341],1],[[151.0,93.942286341],[106.0,16.0],1],[[106.0,16.0],[61.0,93.942286341],1],[[61.0,93.942286341],[16.0,171.884572681],1]],"w":212,"h":188}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u4_review_d#25','math',4,1,'u4','','g4_1_math_u4_review_d','unit_review','M4-1-u4-C10',4,'essay','teacher','색종이를 잘라 예각·직각·둔각삼각형을 모두 만든 친구가 「조각을 다시 모으면 원래 색종이가 돼요.」라고 했어요. 이 말이 맞는 까닭을 조건과 함께 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u4-C10","difficulty":4,"kind":"essay","stem":"색종이를 잘라 예각·직각·둔각삼각형을 모두 만든 친구가 「조각을 다시 모으면 원래 색종이가 돼요.」라고 했어요. 이 말이 맞는 까닭을 조건과 함께 설명해 보세요.","answer_guide":{"answer":"예: 맞다. 색종이를 남김없이 모두 잘라야 한다는 조건을 지켰으므로 조각들은 색종이를 빈틈없이 나눈 것이다. 그래서 모두 모으면 원래 색종이가 된다.","scoring_points":["맞다고 답했는가","남김없이 자른다는 조건을 썼는가","빈틈없이 나눈 것이라 다시 모인다고 했는가"]},"explanation":["남김없이 잘랐어요.","조각은 색종이를 나눈 것.","모으면 처음 색종이."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
